window.__D("text/likkutei-sichot/c035",{"p":[[1301870070,"<h3>דברים (תש\"נ)</h3>\nא. \"ה' אלקיכם הרבה אתכם והנכם היום ככוכבי השמים לרוב\"<sup data-n=\"1\">1</sup>, ובפרש\"י מעתיק התיבות \"והנכם היום ככוכבי השמים\" ומפרש: \"וכי ככוכבי השמים היו באותו היום והלא לא היו אלא ס' רבוא, מהו והנכם היום, הנכם משולים כיום, קיימים לעולם<sup data-n=\"2\">2</sup> כחמה וכלבנה וככוכ­בים\"<sup data-n=\"3\">3</sup> [היינו, שפירוש \"והנכם היום\" הוא \"כאילו<sup data-n=\"4\">4</sup> אמר הנכם כיום\"].\nוהנה ע\"ד פי' זה בתיבת \"היום\" (\"משולים כיום קיימים לעולם\") מצינו בפרש\"י לקמן עה\"פ \"אתם נצבים היום\"<sup data-n=\"5\">5</sup> — \"הרי אתם קיימים לפניו היום<sup data-n=\"6\">6</sup>, כיום הזה שהוא קיים כו'\", אלא ששם מקדים רש\"י שהוא \"מדרש אגדה\"<sup data-n=\"7\">7</sup>, ואילו כאן סתם רש\"י היינו שלרש\"י זהו פשוטו של מקרא.\nוטעם הדבר מבואר בדברי רש\"י עצמו, שמקדים השאלה \"וכי ככוכבי השמים היו באותו היום והלא לא היו אלא ס' רבוא\" — אף שאין דרכו בפי­רושו לפרט את הקושי שאותו בא ליישב, אלא כותב הפירוש עצמו באופן שה­שאלה בטלה מאלי' — כי כאן מוכרח, שאי אפשר לפרש \"והנכם היום\" בפש­טות (שהרי באותו יום לא היו ככוכבי השמים<sup data-n=\"8\">8</sup>), ונמצא שפשוטו של מקרא זה",[["1","1","פרשתנו א, י."],["2","2","ראה גם רש\"י לך טו, י. וראה רש\"י פינחס כט, יח."],["3","3","ופירוש סיום הכתוב \"לרוב\" — ראה לקמן סעיף ג."],["4","4","רא\"ם כאן (ובבאר בשדה על פרש\"י, ד\"כ\"ף דככוכבי משמש גם לתיבה שלפניו\"). וראה אמרי שפר כאן: \"לפי זה יהי' מלת היום חסר כ\"ף ומלת כוכבי חסר וי\"ו וכאלו אמר והנכם כהיום וככוכבי השמים\"."],["5","5","בפי' הב' (בפרש\"י שם כט, יב)."],["6","6","בדפוסים הנפוצים (וכן בדפוס א' דפרש\"י) תיבת \"היום\" הוא ד\"ה חדש. אבל לכאורה הי' יותר נ\"ל שהוא המשך לדיבור הקודם (וכ\"ה בדפוס שני וכמה כת\"י רש\"י שתח\"י. ובכמה כת\"י אין תיבת \"היום\" — \"קיימים לפניו כיום הזה כו'\")."],["7","7","ראה תנחומא ר\"פ נצבים."],["8","8","לכאורה צ\"ע, שהרי מפורש בפ' עקב (י, כב) \"בשבעים נפש גו' ועתה שמך ה\"א ככוכבי השמים לרוב\", וגם אז \"לא היו אלא [מעט יותר מ]ס' רבוא\" (כמפורש במנין דפ' פינחס), ועכצ\"ל שגם הריבוי דס' רבוא אנשים מבן כ' עד בן ס' (שלא נכללו בזה רובם הגדול של האנשים, ונשים וטף), מספיק לתאר בלשון \"ככוכבי השמים לרוב\" (וראה גם באר יצחק על פרש\"י כאן. צידה לדרך ס\"פ ואתחנן. וראה בארוכה לקו\"ש חי\"ט ע' 17 ואילך (ובהערה 46 שם)). ובפרט שבפסוק שלאח\"ז ממשיך \"יוסף גו' אלף פעמים גו'\", ומוכח שאין הכוונה ב\"ככוכבי השמים לרוב\" לריבוי אין מספר.\nויש לומר (בדוחק עכ\"פ), שדיוקו של רש\"י כאן הוא תיבת \"היום\" (דלכאורה מיותרת היא), שמשמעה, שריבוי זה ד\"ככוכבי השמים לרוב\" נתחדש רק אז (ביום ההוא), בעת שאמר להם \"לא אוכל לבדי שאת אתכם\" (מחרת יוהכ\"פ בשנה השנית לצאתם ממצרים — רש\"י יתרו יח, יג. וראה צידה לדרך ואתחנן שם). וזוהי כוונת רש\"י \"וכי ככוכבי השמים היו באותו היום והלא לא היו אלא ס' רבוא\", שלא נתחדש אצלם לגבי הריבוי בעת יצי\"מ (שגם אז היו ס' רבוא) [משא\"כ לגבי \"שבעים נפש\" כבפ' עקב שם].\nועכצ\"ל ד\"מהו והנכם היום — הנכם משולים כיום\". וראה לקמן הערה 28."]]],[1301870071,"מכריח לפרש תיבת \"היום\" — \"משולים כיום\".\nב. ויש לעיין בטעם שרש\"י בפר­שתנו מסיים \"כחמה וכלבנה וככוכבים\", אף שבכתוב נזכרו רק כוכבים.\nבמפרשים<sup data-n=\"9\">9</sup> ביארו ד\"כחמה וכלבנה\" הוא הפירוש ד\"כיום\", כי \"סיבת היום הם חמה ולבנה\"<sup data-n=\"10\">10</sup>, דיום שלם הוא כש­לילו עמו, כמ\"ש<sup data-n=\"11\">11</sup> \"ויהי ערב ויהי בוקר יום אחד\" (ובפרט ע\"פ פרש\"י בפ' ברא­שית עה\"פ<sup data-n=\"12\">12</sup> \"(יהי מאורות גו') ולימים — שמוש החמה חצי יום ושמוש הלבנה חציו הרי יום שלם\").\nואינו מובן שהרי רש\"י מפרש בקו­שיתו ש\"היום\" דמקרא זה פירושו \"אותו היום\"<sup data-n=\"13\">*12</sup>, ומה זה שייך ל\"סיבת היום\"?\nכן צ\"ע: מקורו של פרש\"י הוא מספ­רי כאן, ולשון הספרי הוא \"אתם קיימים כיום\", ורש\"י משנה מלשון הספרי ומפ­רש \"משולים (לא \"קיימים\") כיום קיימים לעולם כחמה וכלבנה\"<sup data-n=\"14\">13</sup>.\nבפשטות יש לומר, שפירוש רש\"י הוא בהתאם ללשון הכתוב \"והנכם היום ככוכבי השמים\", שלפי פרש\"י פירוש הכתוב הוא כאילו נאמר<sup data-n=\"15\">14</sup> \"והנכם כיום וככוכבי השמים\" (כלשון רש\"י \"משולים כיום. . כחמה (בחלק היום שביום) וכ­לבנה וככוכבים (בחלק הערב שביום)\"), ומצירוף שני הענינים (\"יום\" ו\"כוכבים\") מובן<sup data-n=\"16\">15</sup>, שהכוונה בהמשלת בנ\"י ל\"יום\" היא למאורות המושלים בכל חלקי היום (כמו החמה הלבנה והכוכבים, שמאירים את הארץ).\nוצריך ביאור: מהו טעם השינוי, שבפ' נצבים מספיקה ההשוואה ל\"יום\", וכאן מוסיף הכתוב \"ככוכבי השמים\"<sup data-n=\"17\">16</sup>? הלא לענין \"קיימים לעולם\" מספיק להמשיל בנ\"י ל\"יום\", \"כיום הזה שהוא קיים\".\nג. עוד יש לדייק ברש\"י כאן:\nנת' כמ\"פ שלשונו של רש\"י היא בדיוק לא רק בגוף פירושו, אלא גם בתיבות שמעתיק בהדיבור­המתחיל. וב­נדו\"ד יש דיוק בולט — שהעתיק מה­כתוב רק התיבות \"והנכם היום ככוכבי השמים\", והשמיט התיבה האחרונה \"ל­",[["9","9","אמרי שפר. באר מים חיים (לאחי ה­מהר\"ל). צידה לדרך. שפ\"ח. ועוד."],["10","10","ל' הצידה לדרך, ועוד."],["11","11","בראשית א, ה."],["12","12","שם, יד. הובא באמרי שפר כאן."],["13","*12","ובתירוצו מוסיף רק ד\"משולים כיום\"."],["14","13","בהמשך הענין מובא בספרי שם \"פניהם של צדיקים דומים לעתיד לבא לחמה ללבנה. . לכוכבים כו'\", אבל בפשטות אין כוונת הספרי שזה נלמד מתיבת \"היום\" כאן, והרי מביא שם עוד כמה ענינים — רקיע, ברקים, שושנים ומנורת ביהמ\"ק.\n[וכדמוכח מזה שמביא ראי' שדומים ללבנה ולחמה מהכתוב (שה\"ש ו, י) \"יפה כלבנה ברה כחמה\" — דלא ככוכבים, שלא הביא ראי' לזה<sup data-n=\"e4\">*</sup>, כי מפורש הוא בכתוב דידן עצמו, \"ככוכבי השמים\"]."],["15","14","ראה אמרי שפר שבהערה 4."],["16","15","בנחלת יעקב כאן, דבכתוב יש \"תרי מילי\", \"חדא שהם משולים כיום. . ועוד דבר אחר שיבא זמן שיהיו ככוכבי השמים לרוב\" (וראה רא\"ם שהובא לקמן סעיף ג). ומשמע שמפרש שהמשל ל\"כוכבי השמים\" אינו לענין שקיימין לעולם אלא רק לענין הריבוי.\nוצ\"ע, שהרי זהו היפך פשטות לשון רש\"י \"כחמה וכלבנה וככוכבים\", דמשמע שכולם ענין אחד. ובפרט שרש\"י משמיט בהד\"ה תיבת \"לרוב\", כדלקמן שם."],["17","16","ראה גם בצידה לדרך כאן. ומתרץ ע\"פ מדרש (הובא לקמן סעיף ח), ולא ע\"פ פשט."],["e4","*","משא\"כ להגהת הגר\"א בספרי שם."]]],[1301870072,"רוב\"<sup data-n=\"18\">17</sup>, ולא עוד, אלא שאפילו לא רמזה ב\"וגו'\".\nויש לומר, שזהו יסודו של הרא\"ם, שכ' שלפי פרש\"י, הפירוש של \"לרוב\" הוא — \"שיבא זמן שתהיו כמותם [ככוכבי השמים] גם לרוב, אבל עכשיו אתם קיימים כיום דהיינו כחמה וכלבנה וככוכבי השמים, אבל לא לרוב\".\nוצ\"ע (קצת עכ\"פ) — למה נדחק הרא\"ם לפרש ד\"לרוב\" כאן היינו ריבוי בכמות, ובמילא הוכרח לומר שהכוונה \"שיבא זמן שתהיו. . לרוב\" — ולא פי' ד\"לרוב\" כאן הוא מלשון גדולה וחשי­בות<sup data-n=\"19\">18</sup>, כדמצינו בכמה קראי<sup data-n=\"20\">19</sup>, וכמו ש­פרש\"י<sup data-n=\"21\">20</sup> התחלת כתוב דידן, \"ה' אלקיכם הרבה אתכם\" — \"הגדיל והרים אתכם\" (כדלקמן סעיף ד)?\nוהרא\"ם הכריח כן מדיוק רש\"י, שלא העתיק תיבת \"לרוב\" בהד\"ה, שמזה מובן, שרש\"י ס\"ל ש\"לרוב\" הו\"ע בפ\"ע.\nאבל צ\"ע: (א) פי' הרא\"ם ש\"לרוב\" היינו \"שיבא זמן\" שיהי' כן, לכאורה קשה להולמו בפשוטם של כתובים. (ב) ועיקר: מה הכריח את רש\"י להפריד תיבת \"לרוב\" מ\"והנכם היום ככוכבי השמים\"?\nד. ויש לומר הביאור בכל זה:\nכוונת רש\"י בפירושו היא (לא רק לבאר התיבות שהעתיק בפירושו, אלא) לבאר ולישב את תוכן כללות הכתובים הללו:\nבפסוק הקודם<sup data-n=\"22\">21</sup>, \"לא אוכל לבדי שאת אתכם\", פרש\"י: \"אפשר שלא הי' משה יכול לדון את ישראל, אדם שהוציאם ממצרים כו'<sup data-n=\"23\">22</sup>, אלא כך אמר להם, ה' אלקיכם הרבה אתכם, הגדיל והרים את­כם על דייניכם, נטל את העונש מכם ונתנו על הדיינין. . אם חייבתי ממון שלא כדין נפשות אני נתבע שנאמר<sup data-n=\"24\">23</sup> וקבע את קובעיהם נפש\" — שמזה מובן, שלפרש\"י, אין הריבוי במספר של בנ\"י גורם לקושי לשפוט אותם, אלא הקושי הוא מפני ש\"הגדיל והרים אתכם על דייניכם\" [\"הרבה\" — גדולה וחשיבות];\nולפ\"ז צריך לומר, שגם המשך ה­כתוב, \"והנכם היום ככוכבי השמים לרוב\", בא לתאר גדולתם וחשיבותם של ישראל.\nאבל לאידך, בפסוק שלאח\"ז<sup data-n=\"25\">24</sup> מפורש \"ה' אלקי אבותיכם יוסף עליכם ככם אלף פעמים וגו'\", שלשון זו א\"א לפרשה (כמו \"הרבה אתכם\") מלשון גדולה וחשיבות, אלא הוא ענין של ריבוי בכמות. ועכצ\"ל שאף שעיקר טענת משה \"לא אוכל לבדי שאת אתכם\" מבוססת על גדולתם וחשי­בותם של ישראל, מ\"מ נוגע כאן גם ענין הריבוי בכמות.",[["18","17","בדפוס שני וכמה כת\"י רש\"י שתח\"י הועתק גם \"לרוב\" בהד\"ה. אבל בדפוס ראשון דפרש\"י ודפוסי רש\"י הנפוצים ליתא. וכנראה כן היתה גירסת הרא\"ם, כדלקמן בפנים."],["19","18","וכן פירשו ברש\"י כאן בקיצור מזרחי, משכיל לדוד. ועוד (ובבאר בשדה על פרש\"י: לרוב ר\"ל לחוזק ולקיום מלשון (ישעי' ג, ה) ירהבו הנער בזקן)."],["20","19","כמו תולדות כה, כג. ובכ\"מ."],["21","20","בפסוק שלפנ\"ז (א, ט), כהובא במשכיל לדוד כאן."],["22","21","א, ט."],["23","22","כבר האריכו במפרשי רש\"י בפירוש ה­דבר. ואכ\"מ."],["24","23","משלי כב, כג."],["25","24","א, יא."]]],[1301870073,"וזהו שמתווך רש\"י ומחלק את הכתוב לשנים:\nעיקר הכתוב — \"והנכם היום ככוכבי השמים\" — הוא המשך ל\"ה' אלקיכם הרבה אתכם — הגדיל והרים אתכם\"<sup data-n=\"26\">25</sup>, ופירושו \"הנכם משולים כיום, קיימים לעולם כחמה וכלבנה וככוכבים\", שזה מורה על גודל חשיבותם של ישראל, ומגדיל עוד יותר את הקושי לדון אותם, כי כאשר הדיין מחייב איש ישראל שלא כדין אין זו רק פגיעה עראית, אלא פגי­עה במי שקיים לעולם (וכדלקמן סעיף ה),\n[ורק כדי להכריח עוד יותר ש\"והנכם היום\" פירושו \"משולים כיום\", מקדים רש\"י עוד שאלה<sup data-n=\"27\">26</sup> — \"וכי ככוכבי השמים היו באותו היום כו'\", שממנה הכרח גמור שפירוש \"והנכם היום ככוכבי השמים\" הוא \"והנכם משולים כיום כו'\", כנ\"ל סעיף א];\nוסיום הכתוב — תיבת \"לרוב\" — הוא הקדמה לפסוק הבא, המדבר אודות ריבוי במספר בנ\"י, \"ה' אלקי אבותיכם יוסף עליכם ככם אלף פעמים גו'\".\nושיעור הכתוב כך הוא: \"לא אוכל לבדי שאת אתכם\" מחמת גודל חשיבותם של ישראל: \"ה\"א הרבה אתכם\" — \"הג­דיל והרים אתכם כו'\", \"והנכם. . קיי­מים לעולם כחמה וכלבנה וככוכבים\" — שהקושי לדון אותם הוא גם אם היו רק מתי מספר, וכ\"ש וק\"ו שהנכם \"לרוב\", שיש ריבוי במספר \"אנשים חשובים\" (ו­עוד עתידים להרבות כמה פעמים ככה — \"ה' אלקי אבותיכם יוסף עליכם ככם אלף פעמים ויברך אתכם<sup data-n=\"28\">27</sup> גו'\") — עד כמה קשה \"לשאת אותם\".\n[ועפ\"ז אתי תיבת \"לרוב\" כפשוטו, ד­קאי בזמנו של משה שהיו אז \"לרוב\", ומ\"מ לא קשה \"וכי ככוכבי השמים היו באותו היום\", כי תיבת \"לרוב\" אינה המשך ל\"כוכבי השמים\" כנ\"ל, ובנ\"י היו אז \"לרוב\", אבל לא \"ככוכבי השמים\"<sup data-n=\"29\">28</sup>].\nה. ע\"פ הנ\"ל, שהכוונה בהמשלת בנ\"י ל\"יום\" בכתוב זה היא לבאר ולחזק את הטענה שקשה לו לדון את ישראל (\"לא אוכל לבדי שאת אתכם\") — מצד זה שהם \"קיימים לעולם\" — יובן ג\"כ הטעם שהכתוב כאן מוסיף גם \"ככוכבי הש­מים\" (דלא כבפ' נצבים שישראל נמשלו רק ל\"יום\"), ובהקדים:\nעיקר הענין ד\"קיימים לעולם\" ע\"פ פשוטו של מקרא<sup data-n=\"30\">29</sup>, קאי על כללות עם",[["26","25","ראה גם נחלת יעקב כאן."],["27","26","ואף שאינו רגיל ברש\"י אבל בכ\"ז בכמה מקומות מפרט רש\"י השאלה בפירושו. ולהעיר שאין זו השאלה העיקרית שאותה בא רש\"י ליישב, אלא שע\"י ישוב שאלה זו מתורצת גם השאלה העיקרית שבכתוב."],["28","27","ובפרט ע\"פ פרש\"י שם, \"זו משלי היא [שיש בה קצבה] אבל הוא יברך אתכם כאשר דבר לכם\". וראה בארוכה לקו\"ש שנסמן בהערה 8."],["29","28","אלא שע\"פ הנ\"ל (הערה 8) — שגם מספר ס' רבוא כו' אפשר לומר עליו \"ככוכבי השמים לרוב\", אלא שריבוי זה לא נתחדש \"היום\" — בלאה\"כ לא קשה, כי אפשר לחלק הכתוב לשנים (כפי' הנחלת יעקב הנ\"ל הערה 15): א) \"והנכם היום\" — \"משולים כיום קיימים לעולם\", ב) ו\"ככוכבי השמים לרוב\" (ובמילא ל\"ק \"וכי ככוכבי השמים היו באותו היום\").\nוהטעם שרש\"י פי' ש\"ככוכבי השמים\" הוא המשך ל\"והנכם היום\" (\"כחמה וכלבנה וככוכבים\") מובן מהמבואר לקמן סעיף ה."],["30","29","משא\"כ בספרי כאן, שמפרש שקאי על גן עדן (כהמשך ל' הספרי \"ז' כתות של צדיקים בג\"ע כו'\" — ראה פי' רבינו הלל שם). ולרשב\"י שם (\"פניהם של צדיקים דומים לעת\"ל כו'\") קאי על עוה\"ב."]]],[1301870074,"ישראל, שעם ישראל קיים לעולם<sup data-n=\"31\">30</sup> [היינו כל זמן קיום העולם, כלשון רש\"י<sup data-n=\"32\">31</sup> \"שהם קיימים לעולם\" בנוגע לשמים וארץ] — משא\"כ בנוגע לכאו\"א מישראל בפרט, שאינו קיים לעולם בחיים גשמיים בעוה\"ז (ורק לעולם הבא אפשר לומר כן<sup data-n=\"33\">32</sup>).\nועפ\"ז, חשיבותם של ישראל ש\"קיי­מים לעולם\" אינו ענין, לכאורה, להקושי לדון את ישראל בזמן משה, שהרי לכאורה, משפט של אדם פרטי אינו שייך ואינו פוגע בקיום כללות עם יש­ראל.\nולכן מוסיף הכתוב \"ככוכבי השמים\": המשלת ישראל לכוכבי השמים כבר הובאה בפרש\"י לעיל (בר\"פ שמות) — \"להודיע חבתן שנמשלו לכוכבים שמו­ציאן ומכניסן במספר ובשמותם\", ונמצא, שהמשל לכוכבי השמים מדגיש חשיבות הפרט, דעל אף הריבוי העצום של כוכבי השמים, מ\"מ יש התייחסות לכאו\"א מהם בפרטיות, \"במספר ובשמותם\". וכן הוא בעניננו, שהמשלת ישראל ל\"כוכבי ה­שמים\" מדגישה גודל חשיבותו של כאו\"א מישראל בפרט, וזהו גודל האז­הרה לדייני ישראל עד כמה צריכים הם להזהר במשפטו של כאו\"א מישראל.\nו. עפ\"ז יש לבאר גם הדיוק בפרש\"י, שהמשיל את ישראל לחמה ולבנה (ולא סתם ל\"יום\" כבפ' נצבים) — כי בזה נרמזת שייכותו של כל יחיד ויחיד להנצחיות של כלל ישראל (שלכן, זה שישראל \"קיימים לעולם\" מוסיף חומר וזהירות במשפטם של ישראל).\nוהביאור בזה:\nהמשל דשמש ירח וכוכבים הוא מקרא מלא בחומש לפני זה — בחלום יוסף<sup data-n=\"34\">33</sup>: \"והנה השמש והירח ואחד עשר כוכבים משתחווים לי\", והנמשל — \"אני ואמך ואחיך\"<sup data-n=\"35\">34</sup>, כלומר: השמש הוא משל על אב, ירח — אם, וכוכבים — בנים.\nוזהו מ\"ש רש\"י כאן, שישראל \"קיי­מים לעולם כחמה וכלבנה וככוכבים\", ש­זהו משל על המשך הדורות של עם יש­ראל, שאין לו הפסק, \"קיימים לעולם\". ובזה גופא מודגשת חשיבות הפרט בנצ­חיותו של עם ישראל, שכאו\"א הוא טבעת אחת מהשלשלת הנצחית של עם ישראל (\"חמה לבנה וכוכבים\"), ולכן הפגיעה ביחיד אינה רק פגיעה בו (באיש פרטי, והיא פגיעה זמנית), אלא בכל המשך הדורות<sup data-n=\"36\">35</sup>, \"לעולם\".\n[ומטעם זה נאמר בכתוב \"היום\" ואינו מפרט \"שמש וירח וכוכבים\" — כי אין הדיוק כאן על כאו\"א מהמאורות בפ\"ע, אלא על הצירוף של כולם, כאב ואם ובנים ובנות, שכולם יחד הם המשך הדורות].\nז. ויש לבאר דיוק ל' רש\"י ש\"היום\" כאן פירושו \"כחמה וכלבנה וככוכבים\" גם ע\"פ פנימיות הענינים:",[["31","30","ראה גם נחלת יעקב כאן: כדאמרינן (ב\"ב קטו, ריש ע\"ב) גמירי דלא כלה שבטא."],["32","31","ס\"פ נצבים (ל, יט). ר\"פ האזינו. — ומתורצת עפ\"ז הסתירה מפרש\"י תשא (לב, יג) \"לא. . בדבר שהוא כלה. . בשמים. . בארץ\"."],["33","32","ראה רש\"י אחרי יח, ה."],["34","33","וישב לז, ט."],["35","34","שם, י."],["36","35","ע\"ד פרש\"י בראשית (ד, י) \"דמו ודם זרעיותיו\". וראה פנים יפות כאן."]]],[1301870075,"עה\"פ<sup data-n=\"37\">36</sup> \"אשר אנכי מצוך היום\" אמרו רז\"ל<sup data-n=\"38\">37</sup> (והובא בפרש\"י על התורה) \"יהיו בעיניך. . כחדשה\", \"בכל יום יהיו בעיניך חדשים\"<sup data-n=\"39\">38</sup>, שענין זה מורה על שתי תנועות הפכיות<sup data-n=\"40\">39</sup>:\nזה שהאדם מרגיש תמיד — בכל יום ויום — שדברי תורה הם כחדשים, מורה על ענין התמידיות שבעבודתו, שלמעלה משינויים; וביחד עם זה, התמידיות והנצחיות שבעבודתו אינה רק בכך שהוא עובד את ה' תמיד, אלא שתמיד נרגש אצלו שד\"ת הם כחדשים — שזוהי תנועה מנוגדת לענין התמידיות, כי ע\"פ טבע, ענין ישן, ובפרט ענין תמידי, א\"א להרגיש בו ענין של התחדשות.\nונמצא, שתיבת \"היום\" מורה על חיבור שני הפכים — ענין התמידיות והנצחיות (\"קיים לעולם\"), וענין ההת­חדשות.\nוהם הענינים ד\"חמה ולבנה וכוכבים\" (שכולם יחד נהי' \"יום שלם\"):\nמעלת ה\"חמה\" (שמש) היא, שאור השמש אין בו שינויים, דלא כאור הלבנה שתמיד הוא במצב של שינויים (בחצי הראשון של החודש הולך וגדל, ובחציו השני — הולך ומתמעט);\nולאידך יש מעלה באור הלבנה, שדו­קא בגלל השינויים שבו, יש בו המעלה שבענין ההתחדשות, וכתורת הרב המ­גיד<sup data-n=\"41\">40</sup> על \"ועינינו מאירות כשמש וכ­ירח\"<sup data-n=\"42\">41</sup> [דלכאורה תמוה, כיון שמאירים \"כשמש\", מה מוסיף זה שמאירים גם כ\"ירח\" ש\"היא (רק) מקבלת האור מן השמש\"?] — ד\"בזה (אור הירח) יש לה יותר תענוג, כי השמש אין לה תענוג כי תענוג תמידי אינו תענוג, אבל הירח יש לה תענוג בהגיע לה אור\".\nוזהו שהיום כלול מחמה ולבנה — לפי שבו מתחברות שתי המעלות, תמי­דיות החמה והתחדשות הלבנה, גם יחד.\nח. עפ\"ז יש לבאר גם בפנימיות הענינים טעם ההוספה \"(כחמה וכלבנה) וככוכבים\" — דיש לומר, שהכח לחבר שני הענינים דחמה ולבנה, בא מ\"כוכ­בים\" שלמעלה משניהם<sup data-n=\"43\">42</sup>.\nוהביאור בנפש האדם: \"כוכב\" מרמז על אור (הנעלם) של (פנימיות) הנשמה [כמו כוכבים בפשטות, שהם נראים לעין רחוקים ביותר מן הארץ, ועד שרוב הכוכבים אינם נראים לעין<sup data-n=\"44\">43</sup>], ועד לדרגת יחידה שבנפש<sup data-n=\"45\">44</sup>, עצם הנשמה;",[["37","36","ואתחנן ו, ו."],["38","37","ספרי שם."],["39","38","ל' רש\"י תבוא כו, טז. וראה גם רש\"י יתרו יט, א. עקב יא, יג."],["40","39","בהבא לקמן ראה גם סה\"מ — מלוקט ח\"ג ע' רלד."],["41","40","אור תורה שלו ד\"ה ועינינו מאירות (פד, סע\"ד). הובא ונת' באוה\"ת ואתחנן ע' קט (וראה שם ע' קי, דכל יום יהיו בעיניך כחדשים (ענין ההתחדשות) שייך לירח. ע\"ש). ועוד."],["42","41","תפלת \"נשמת\"."],["43","42","במעלת כוכבים על שמש וירח ע\"ד החסידות — ראה ס' הליקוטים (דא\"ח) דהצ\"צ ע' כוכבים (ס\"ב), ס' הערכים—חב\"ד ע' אור הכוכבים (ס\"א), וש\"נ."],["44","43","ראה רד\"ק ישעי' (מ, כו). לקו\"ת ראה כז, סע\"ב. וראה דיוק לשון הרמב\"ם (הל' יסוה\"ת פ\"ג ה\"ח) \"כוכבים הנראים\" (ובפירוש שם). וברש\"י פסחים (צד, א ד\"ה תחת כוכב) \"וכמה כוכבים יש ברקיע לאין מספר\". ועוד. ואכ\"מ."],["45","44","כמובן ממחז\"ל ש\"דרך כוכב מיעקב\" (בלק כד, יז) קאי על משיח (תרגום ועוד שם) — והרי משיח הוא בחי' יחידה (הכללית), כמבואר בכתבי האריז\"ל (ל\"ת בראשית עה\"פ ויתהלך חנוך. רמ\"ז לזח\"ג (רס, ב) — הובא בסה\"מ תרצ\"ט ע' 207. ועוד).\nוידוע מ\"ש בס' מאור עינים (ס\"פ פינחס) בשם הבעש\"ט, שבכל א' יש ניצוץ משיח. ונת' במ\"א (לקו\"ש ח\"ב ע' 599, ועוד) שזהו הטעם שבירו­שלמי (מע\"ש פ\"ד ה\"ו) מפרש \"דרך כוכב מיעקב\" על כאו\"א מישראל, כי קאי על ניצוץ משיח שבו."]]],[1301870076,"ומצד גודל ההתקשרות של עצם הנשמה בקוב\"ה, \"יחידה לייחדך\"<sup data-n=\"46\">45</sup>, נע­שה החיבור דשני ההפכים<sup data-n=\"47\">46</sup> (המרומזים בחמה ולבנה), שעבודתו היא בתמידיות בלי שינויים, וביחד עם זה — הרי היא מתוך שמחה רבה ועצומה וחביבות יתי­רה, באופן של התחדשות, \"בכל יום ויום יהיו בעיניך כחדשים\", ועד — חדשים ממש<sup data-n=\"48\">47</sup>.\nוזהו גם הטעם שבפשטות משמעות לשון הכתוב נמשלו ישראל לכוכבי הש­מים — כי זהו העיקר, וענין זה יאיר בגי­לוי אצל כאו\"א מישראל לעת\"ל, וכ­מרז\"ל<sup data-n=\"49\">48</sup> שישראל נמשלו לכוכבים דוקא, כי \"חמה ולבנה יש להם בושה לעתיד לבא. . דכתיב<sup data-n=\"50\">49</sup> וחפרה הלבנה ובושה החמה וגו' אבל הכוכבים אין להם בושה לעולם. . שכן כתיב<sup data-n=\"51\">50</sup> וידעתם כי בקרב ישראל אני ואני ה' אלקיכם ואין עוד וגו'\"<sup data-n=\"52\">51</sup>.\n<span data-k=\"q\">(משיחת ש\"פ דברים תש\"ל)</span>",[["46","45","נוסח הושענות ליום ג'."],["47","46","ראה סה\"מ מלוקט שם (ע' רלג), בענין יחוד סובב וממלא ע\"י כח העצמות שלמעלה משניהם."],["48","47","כל' רש\"י (במקומות שנסמנו בהערה 38) \"חדשים\" (בלי כ\"ף הדמיון). וראה ספר המאמרים — מלוקט ח\"א ע' קנב ובהערה 15 שם."],["49","48","דב\"ר עה\"פ כאן (פ\"א, יד)."],["50","49","ישעי' כד, כג."],["51","50","יואל ב, כז."],["52","51","\"וסיפי' דקרא ולא יבושו עמי לעולם\" (מת\"כ שם)."]]],[1301870077,"<h3>שבת חזון</h3>\nא. בביאור הפנימי של השם \"שבת חזון\" (שבפשטות הוא ע\"ש ההפטרה<sup data-n=\"53\">1</sup>), ידוע מה שהביא<sup data-n=\"54\">2</sup> הרה\"ח הנודע ר' הלל מפאריטש<sup data-n=\"55\">3</sup> \"בשם הרב מבאַרדיטשוב נבג\"ם\", ד\"שבת חזון\" הוא מלשון מחזה, \"שמראין לכאו\"א מישראל<sup data-n=\"56\">4</sup> המקדש דל­עתיד מרחוק\" (וכדלקמן ס\"ב).\nויש לומר, שכאשר שבת חזון חל ביום הת\"ב בעצמו (כקביעות שנה זו<sup data-n=\"e1\">*</sup>), הרי ענין זה דשבת חזון — ראיית בית המקדש דלעתיד — הוא ביתר שאת ויתר עז.\nדהנה ידוע<sup data-n=\"57\">5</sup> שמטרת ענין הצומות (ובמילא — כוונתם הפנימית גם עתה) היא שיהפכו לימים טובים, בלשון הרמ­ב\"ם<sup data-n=\"58\">6</sup> \"שהם עתידים להיות ימים טובים<sup data-n=\"59\">7</sup> וימי ששון ושמחה\". וענין זה הוא בהד­גשה יתירה בתענית דת\"ב, ד\"אין<sup data-n=\"60\">8</sup> אומ­רים תחנון ולא סליחות בת\"ב ואין נופלין על פניהם משום דאקרי מועד\". ויתירה מזו איתא בירושלמי<sup data-n=\"61\">9</sup> שביום שחרב הבית (ת\"ב) \"יליד מלכא משיחא\"<sup data-n=\"62\">10</sup>. ובפרט ע\"פ הידוע<sup data-n=\"63\">11</sup> שביום הולדתו של אדם מזלו גובר, דלפי זה נמצא, שביום ת\"ב מתגבר מזלו של משיח צדקנו<sup data-n=\"64\">12</sup>, והוא יום מסוגל לענין של ישועה וגאולה<sup data-n=\"65\">13</sup>. וענין זה נוגע להלכה למעשה, וכמ\"ש הרח\"ו<sup data-n=\"66\">14</sup> בשם האריז\"ל שזהו מהטעמים שאומרים \"פסו­קי נחמה\" \"ביום ט\"ב במנחה. . כי אז במנחת ט\"ב נולד המשיח הנקרא מנ­חם\"<sup data-n=\"67\">15</sup>, וי\"ל שזהו הטעם הפנימי שנק' ת\"ב בשם \"מועד\".\nועפ\"ז יש לומר, דכאשר הצום דת\"ב",[["53","1","שאומרים בשבת שלפני ת\"ב — תוס' מגילה לא, ב ד\"ה ר\"ח (בתחלתו). טושו\"ע או\"ח סתכ\"ח ס\"ח. הגמ\"יי לרמב\"ם הל' תפלה פי\"ג ה\"ד."],["54","2","נעתק באוה\"ת לנ\"ך ח\"ב ע' א'צז — בשוה\"ג — על רשימת הצ\"צ שם \"ומחזון ותחזינה עינינו\"."],["55","3","להעיר, שיום ההילולא שלו הוא י\"א מנ\"א (תרכ\"ד) — ראה ראשי פרקים מתולדותיו בהקדמה לספרו פלח הרמון בראשית ושמות (הוצאת קה\"ת)."],["56","4","כ\"ה בגוף כת\"י דהרר\"ה (בוך 1228 — צז, א). ובהנעתק באוה\"ת שם ליתא תיבה זו."],["57","5","ראה בארוכה לקו\"ש חט\"ו ע' 412 ואילך."],["58","6","סוף הל' תעניות."],["59","7","כ\"ה בדפוס רומי רמ ועוד (ראה רמב\"ם הוצאת פרענקל). ולכאורה כצ\"ל (בל' רבים, ככל ההמשך שם), ולא \"יום טוב\" כבדפוסים הנפוצים."],["60","8","שו\"ע או\"ח סתקנ\"ט ס\"ד. וש\"נ."],["61","9","ברכות פ\"ב ה\"ד. איכ\"ר פ\"א, נא."],["62","10","בבמדב\"ר (פי\"ג, ה בסופו): אף היא אינה צרה אלא שמחה שבו ביום נולד מנחם כו' (וראה מ\"כ שם)."],["63","11","ראה ירושלמי ר\"ה פ\"ג ה\"ח ובקה\"ע ופני משה שם."],["64","12","ראה מאמרי אדמו\"ר האמצעי דברים ח\"א ע' קב שבכל ט\"ב נולד משיח. וראה בארוכה יפה ענף (השלם) לאיכ\"ר שם."],["65","13","להעיר מפסיקתא רבתי פ' על נהרות בבל (בסופו) \"אין שמחה בא אלא בתשעה באב\"."],["66","14","שער הכוונות ענין ט\"ב בסופו, הובא בברכ\"י או\"ח סתקנ\"ט אות ז."],["67","15","כ\"ה בשער הכוונות שם וברכ\"י שם, ומס­יים \"כנזכר במדרש איכה רבתי\" (וכ\"ה בירושלמי ברכות שם). ובפע\"ח (שכ\"ג — כוונת ט\"ב ובין המצרים בסופו) בהגהת צמח מביא מהרח\"ו הטעם למה שאומרים ברכת הלבנה במוצאי ת\"ב \"כי בט' באב נולד משיח\". וכ\"ה במשנת חסידים (סוף מס' תמוז ואב) \"מפני שבתשעה באב נולד מנחם לפיכך כו'\"."],["e1","*","שנת הדפסת השיחה (תנש\"א), וכן דשנת תשמ\"ח. המו\"ל."]]],[1301870078,"חל ביום הש\"ק, שדוחין את התענית ליום א', אין זה אלא בשייכות לענין הצום ודיני עינוי ואבילות כו', אבל ענין ה­\"מועד\" שבו, בגלל זה שביום זה נולד מושיען של ישראל והוא יום מסוגל לנחמה וגאולה, אינו נדחה ע\"י ש\"ק, ואדרבה, ענינים אלה הם בעיקר ביום הש\"ק.\nוע\"ד משנ\"ת במ\"א<sup data-n=\"68\">16</sup> בנוגע לכל ה­צומות, שכשחלים ביום הש\"ק נדחה רק ענין הצום, אבל זה שיום צום נקרא \"יום רצון לה'\"<sup data-n=\"69\">17</sup> אינו נדחה מיום הש\"ק, ו­אדרבה, ה\"ה עת רצון ביתר שאת ויתר עז, כי \"חמדת ימים אותו קראת\"<sup data-n=\"70\">18</sup>, ונצטוינו לענגו בעונג אכילה ושתי' כו'<sup data-n=\"71\">19</sup>, ונמצא, שכשהצום חל ביום ש\"ק הרי הוא כמו \"יום טוב\" ויום \"ששון ושמחה\"<sup data-n=\"72\">20</sup>.\nומזה מובן גם לעניננו, דכיון שכשחל ת\"ב בש\"ק מודגש באופן גלוי ענינו ה­פנימי, שהוא \"מועד\"<sup data-n=\"73\">21</sup> ויום מסוגל לעניני ישועה גאולה ונחמה, הרי גם ראיית בית המקדש דלעתיד ביום זה (להיותו שבת חזון), היא ביתר שאת וביתר עז.\nב. ויש לבאר העילוי המיוחד דראיית המקדש דלעתיד כשחל שבת חזון ביום הת\"ב עצמו, בהקדם הביאור בהמשך דברי הרב לוי\"צ מבאַרדיטשוב, שמביא שם משל לבאר זה שמראין את המקדש דלעתיד לכאו\"א מרחוק, וז\"ל<sup data-n=\"74\">22</sup>:\n\"משל. . מאב שיש לו בן יקר ועשה לו מלבוש יקר להתלבש בו ומצד שלא נזהר הבן באותו בגד ועשה מעשים אשר לא יעשו קרע אותו לכמה קרעים. ועשה לו פעם שני לבוש יקר וקרע אותו ג\"כ<sup data-n=\"75\">23</sup>. מה עשה האב עשה לו לבוש שלישי ולא נתן לו ללבוש אותו רק גנזו ולפרקים<sup data-n=\"76\">24</sup> ידועים הוא מראה לו הלבוש ואומר לו ראה שאם תתנהג בדרך הישר ינתן לך לבוש זה ללבוש אותו [ומצד זה מרגילו לילך בדרך הישר עד שיודע בו שנעשה אצלו כמו טבע אז יתן לו הלבוש להלביש אותו כי אז אינו ירא ממנו פן יחזור לסורו מאחר שנעשה כמו טבעית כו'] וזהו ענין שבת חזון ל' מחזה שמראין לכאו\"א מישראל המקדש דלעתיד מרחוק כו' וד\"ל\".\nוהיינו שהתכלית של זה ש\"מראין. . המקדש דלעתיד\" היא להרגיל את בנ\"י",[["68","16","ראה לקו\"ש חל\"ג ע' 159 ואילך. סה\"ש תנש\"א ח\"ב ס\"ע 683 ואילך."],["69","17","ישעי' נח, ה. וראה תניא אגה\"ת ספ\"ב."],["70","18","נוסח תפלת עמידה דש\"ק."],["71","19","שו\"ע אדה\"ז או\"ח ר\"ס רמב. וי\"ל שאז (כשיום התענית ובפרט ת\"ב חל בשבת) יש להוסיף בזה יותר מכל שבתות השנה כדי לשלול הקס\"ד של מיעוט בזה בגלל יום הצום. וראה לקו\"ש ח\"ד ע' 1091."],["72","20","וראה ספרי (בהעלותך י, י): ביום שמחת­כם אלו שבתות. וכן משמע בירושלמי מגילה פ\"א ה\"ד בתחלתה (\"ששמחתו תלוי' בידי שמים\"), וכן נפסק בשו\"ע או\"ח סתרפ\"ח ס\"ו — ראה נ\"כ ה­טושו\"ע שם. וראה תוס' סד\"ה מ\"ד (מו\"ק כג, ב). ועוד. וראה לקו\"ש שם ע' 1090 בהערה 31 מה שלא נזכר בפוסקים ובשו\"ע אדה\"ז. ובארוכה לקו\"ש חל\"ג ע' 62 ואילך."],["73","21","והרי דוקא בקביעות כזו שחל ת\"ב בשבת ונדחה לאחר השבת (או שחל תשעה באב באחד בשבת), איתא (טושו\"ע שם סתקנ\"ב ס\"י) \"אוכל בשר ושותה יין בסעודה המפסקת ומעלה על שולחנו ואפילו כסעודת שלמה בעת מלכותו\"."],["74","22","בביאור מאמר הנ\"ל והמשל כו' — ראה לקו\"ש ח\"ט ע' 24 ואילך. חכ\"ט ע' 18 ואילך."],["75","23","וראה זח\"א סא, ב ובאוה\"ח שם."],["76","24","כ\"ה בכת\"י דהרר\"ה. ובאוה\"ת שם: לפר­קים רחוקים ידועים."]]],[1301870079,"ללכת בדרך הישר עד שהליכה זו תהי' אצלם \"כמו טבע\", ואז ניתן להם המקדש למטה.\nוצ\"ב בהתאמת המשל לתוכן הנמשל, דלכאורה, בשלמא במשל, הרי הלבוש עצמו אינו אלא שכר צדדי ואינו גורם מצד עצמו שיתנהג הבן כדבעי, ולכן רק עי\"ז שאביו אינו נותן לו הלבוש ורק מראה לו ואומר לו ראה שאם תתנהג בדרך הישר ינתן לך לבוש זה, הרי זה מרגילו ללכת בדרך הישר; אבל בנמשל, הרי עצם מציאות המקדש פועל שיפור והטבה במצב בנ\"י בגלל היותו מקום גילוי שכינה וראיית אלקות. ולפי זה צ\"ב, איך יתכן, שראיית אלקות בזמן הבית, כשהי' בית המקדש על מכונו ובנ\"י עלו לרגל וראו במו עיניהם את עשרת הנסים שנעשו לאבותינו בביהמ\"ק<sup data-n=\"77\">25</sup>, ובמשך שנים רבות, הרי כ\"ז לא פעל עליהם שייטיבו את דרכם, אע\"פ שבשעת מעשה היו נביאים שהוכיחו את ישראל והזהירום שעל ידי מעשיהם הרעים יגרמו לגלות וחורבן הבית — ואילו זה שרק מראין את המקדש דלעתיד מרחוק, וזה גופא רק \"לפרקים ידועים\", יש בכוחו לפעול על בנ\"י להרגילם ללכת בדרך הישר עד שזה יהי' \"כמו טבע\" בנפשם?\nג. ויש לומר, שהביאור בזה נרמז במ\"ש הרב לוי\"צ מבאַרדיטשוב \"שמראין לכאו\"א מישראל המקדש דלעתיד מר­חוק\". דלכאורה צ\"ב, הרי ראי' וריחוק הם שני ענינים שונים, ויתרה מזה — הראי' 1) מורה שהדבר הוא בקירוב, 2) \"מקרבת\" ומודיעה פרטי הדבר להרואה.\n[וכידוע החילוק בין ראי' לשמיעה<sup data-n=\"78\">26</sup>, דראי' היא מקרוב ושמיעה מרחוק<sup data-n=\"79\">27</sup>. כלו­מר: ראי' מגיעה בנפש וחודרת בהאדם בוודאות והתאמתות כזו שאינה בשמיעה, דכשהאדם רואה איזה דבר, לא יועילו הוכחות וראיות לסתור את ראייתו<sup data-n=\"80\">28</sup>, כי מאחר שהוא בעצמו ראה את הדבר הרי נתאמת ונתברר אצלו הדבר יותר מכל בירור שכלי.\n— וכמודגש בההלכה<sup data-n=\"81\">29</sup> ד\"אין עד נע­שה דיין\", כדאיתא בגמ'<sup data-n=\"81\">29</sup> הטעם \"כיון דחזיוהו כו' לא מצו חזו לי' זכותא\", משא\"כ כשהדיינים שומעים מהעדים, אף שברור להם שהעדים אומרים אמת<sup data-n=\"83\">30</sup>, חזו לי' זכותא, כי הוודאות והתפעלות שמצד ראי' היא גדולה יותר מהוודאות והת­פעלות שמצד שמיעה],\nוא\"כ מהו שאומר ש\"מראין לכאו\"א מ­ישראל המקדש דלעתיד מרחוק\" — דאם זהו באופן של ראי', הרי זה מדגיש שאינו \"מרחוק\" אלא \"מקרוב\".\nויש לומר, דכוונתו בזה ללמדנו שני ענינים הפכיים הנצרכים בכדי שההליכה בדרך הישר תעשה ותהי' \"כמו טבע\" ב­אופן שתביא את נתינת המקדש דלעתיד.\nד. ביאור הענין:\nידועה דעת הזהר<sup data-n=\"84\">31</sup> שבית המקדש השלישי ייבנה ע\"י הקב\"ה, \"בניינא ד­",[["77","25","אבות פ\"ה מ\"ה."],["78","26","ראה סה\"מ תרס\"ג ע' יג. סה\"מ תש\"ט ע' מה ואילך. ובכ\"מ. ולהעיר מאגה\"ק סי\"ט (קכז, ב). וראה בהנסמן בהערה הבאה."],["79","27","מאמרי אדמו\"ר האמצעי בראשית ע' תקד. ס\"ע תקמג ואילך. המשך תער\"ב ח\"ב ע' תדש ואילך. סה\"מ פר\"ת ע' סט. ובכ\"מ."],["80","28","ראה רמב\"ם הל' יסוה\"ת ספ\"ח."],["81","29","ר\"ה כו, א."],["81","29","ר\"ה כו, א."],["83","30","להעיר מרמב\"ם שם ספ\"ז. ואכ\"מ."],["84","31","ח\"א כח, א. ח\"ב נט, סע\"א. קח, סע\"א. ח\"ג רכא, א."]]],[1301870080,"קוב\"ה\". וכמ\"ש רש\"י<sup data-n=\"85\">32</sup> \"מקדש העתיד שאנו מצפין בנוי ומשוכלל הוא יגלה ויבא משמים שנאמר<sup data-n=\"86\">33</sup> מקדש אדנ­י כוננו ידיך\". אבל לאידך מצינו ברז\"ל<sup data-n=\"87\">34</sup> שה­מקדש ייבנה על ידי בנ\"י, וכן פסק הרמב\"ם<sup data-n=\"88\">35</sup> דמשיח בונה המקדש, ולכאו­רה טעמו פשוט, שהרי בנין ביהמ\"ק היא מצות עשה<sup data-n=\"89\">36</sup>, כמ\"ש<sup data-n=\"90\">37</sup> ועשו לי מקדש, ומצוה היא דבר המוטל על בנ\"י.\nוהנה כבר נת' כמ\"פ<sup data-n=\"91\">38</sup> שי\"ל כמה תיווכים בין ב' הדיעות, דתרווייהו אית­נהו בי' [דבנין הבית למטה יהי' בידי אדם, ובמקדש זה שלמטה ירד וישכון המקדש הרוחני דלמעלה, או שמקדש גשמי ירד מן השמים אבל הדלתות או השערים שטבעו בארץ, שהן היו בידי אדם, יעלו ויתגלו ויעמידום במקומם והמעמיד הדלתות נחשב<sup data-n=\"92\">39</sup> כאילו בנאו]. ועפ\"ז נמצא, שבבנין דלעתיד יש צורך בשני הענינים — הן הענין ד\"בניינא דקוב\"ה\", וכן שייעשה על ידי בני אדם, המלך המשיח.\nונקודת הביאור בזה היא, כי עיקר החידוש דבית השלישי הוא שיהי' בית נצחי, דלא כבית הא' ובית הב', ולכן צ\"ל \"בניינא דקוב\"ה\", ולא בניינא דבר נש, שאין לו קיום (כמבואר בזהר שם<sup data-n=\"93\">40</sup>). אבל לאידך, נצחיות המקדש צ\"ל (גם) כמו שהוא בגדרי המטה, ולכן קביעות נצחית זו למטה היא ע\"י מעשה בני אדם, שאז הנצחיות כמו שהיא מצד \"בניינא ד­קוב\"ה\" נקבעת גם ב(גדרי) המטה<sup data-n=\"94\">41</sup>.\nה. ויש לומר, דכשם שהוא בנוגע ל­בנין ביהמ\"ק, עד\"ז הוא גם בזה שמראין את המקדש דלעתיד לכאו\"א מישראל, שיש בזה מעין שני ענינים אלה — \"בנינא דקוב\"ה\" ומעשה בני אדם (ונרמזים בב' הלשונות \"מראין. . מרחוק\", כדלקמן):\nמ\"ש \"לשון מחזה שמראין לכאו\"א מ­ישראל\", אין כוונתו רק שבשבת חזון ישנו המקדש דלעתיד בבחי' ראי' אצל כאו\"א (שאז הי' כותב כאו\"א רואה ופשיטא שביכלתו לראות וכיו\"ב), אלא ש\"מראין\" אותו, היינו שהראי' באה לא מצד האדם עצמו, אלא היא פעולתו של זה שמראה אותו, שהראי' באה מלמעלה, ע\"ד שהבנין הוא \"בניינא דקוב\"ה\".\nוזהו החידוש בראי' זו לגבי ראיית השכינה במקדש הא' והב':\nבמקדש הא' והב', אף שבנ\"י עלו לרגל והקריבו קרבנות במקדש וראו גילוי שכינה ע\"י עשרת הנסים שנעשו לאבותינו, שפשיטא שכ\"ז מביא ליר\"ש [במכ\"ש וק\"ו מזה שהעלי' עצמה לירו­שלים לאכול מעשר שני מביאה ליר\"ש, \"",[["85","32","סוכה מא, סע\"א. ר\"ה ל, סע\"א. וכ\"ה בתוס' סוכה שם. שבועות טו, ריש ע\"ב ד\"ה אין."],["86","33","בשלח טו, יז. וראה פרש\"י שם."],["87","34","ירושלמי מגילה פ\"א הי\"א. ויק\"ר פ\"ט, ו. וראה ירושלמי פסחים פ\"ט ה\"א (תוספתא פסחים פ\"ח, ב)."],["88","35","הל' מלכים רפי\"א וסופו."],["89","36","רמב\"ם הל' ביהב\"ח בתחלתן."],["90","37","תרומה כה, ח."],["91","38","ראה לקו\"ש חי\"ח ע' 418. וש\"נ (נדפס בחידושים וביאורים בהל' ביהב\"ח \"פתיחה\" ס\"ו. שם סימן יט. ועוד)."],["92","39","ראה ב\"ב נג, ב."],["93","40","ח\"א וח\"ג שם. וכ\"ה בפסיקתא רבתי שם."],["94","41","ועד\"ז הוא בקדושת המקדש וירושלים, דאף שכ' הרמב\"ם (שם ספ\"ו) ד\"קדושת המקדש וירושלים מפני השכינה ושכינה אינה בטילה\", קבי­עות קדושה זו נעשה עי\"ז ש\"קדשה שלמה שהוא קידש העזרה וירושלים\" (רמב\"ם שם הי\"ד), ע\"י מעשה הקידוש."]]],[1301870081,"שהי'<sup data-n=\"95\">42</sup> רואה קדושה גדולה וכהנים עוסקים בעבודה הי' מכוון לבו יותר ליראת שמים וללמוד תורה כדדרשי' בספרי למען תלמד ליראה וגו'<sup data-n=\"96\">43</sup> גדול מעשר שני שמביא לידי תלמוד לפי שהי' עומד בירושלים עד שיאכל מע\"ש שלו והי' רואה שכולם עוסקים במלאכת שמים ובעבודה הי' גם הוא מכוון ליראת שמים ועוסק בתורה\"] — הרי ראי' זו היא מה שבנ\"י ראו ונתעוררו ליר\"ש; ואילו בבית המקדש הג' ה\"ז באופן ש\"מראין לכאו\"א מישראל\", שהקב\"ה מראה אותו.\nוהחילוק בין דבר שהאדם רואה מ­עצמו לזה שמראין לו מלמעלה הוא הן בכמות והן באיכות: כאשר האדם רואה מעצמו אינו רואה את כל פרטי הדבר, אלא מה שביכלתו לראות בכח עצמו; משא\"כ כשמראין לו, הרי יכול לראות את כל הדבר. ועוד זאת: כאשר ראיית הדבר היא בכח האדם, הרי תפיסת הדבר היא לפי אופן כליו וחושיו, ואינו תופס את הדבר כמו שהוא; ואילו כאשר מראין לו את הדבר, אין זה לפי מדידת תפיסת האדם, אלא לפי ערך הדבר שמראין לו.\nועד\"ז הוא בנוגע לבתי המקדשות: בבית המקדש הא' והב' \"ראו\" בנ\"י מ­עצמם את הגילוי, וכיון שהיא ראי' של נברא, הרי אין זה גילוי אלקות דהמקדש כמו שהוא, כי אין ביכולתו של נברא לראות ולהשיג מאלקות אלא באופן מוג­בל, לפי ערך מדידות והגבלות האדם<sup data-n=\"97\">44</sup>; משא\"כ המקדש דלעתיד שמראין לכאו\"א מישראל, אין זה לפי ערך ודרגת הנברא, אלא זהו המקדש עצמו, כי הקב\"ה מראה אותו, וענין זה הוא נעלה שלא בערך ממה שנברא יכול לראות ולהשיג.\nומטעם זה ראיית הגילויים שבבית ראשון ובית שני והעבודה אז לא פעלה שהנהגת בנ\"י בדרך הישר תהי' \"כמו טבע\" בנפשם, ענין הנצחיות, ודוקא ראיית המקדש דלעתיד יש בכוחה לפעול שהנהגתם תהי' בדרך הישר,\nכי ראיית ועבודת ישראל במקדש ראשון ושני אינה אלא ראייתו ועבודתו של נברא, דלהיותו מדוד ומוגבל ובעל שינוי, הרי גם עבודתו היא בהגבלה וא\"א שיהי' לה נצחיות; משא\"כ ראיית המקדש דלעתיד, ה\"ז פעולה מצד הקב\"ה, ולכן דוקא בכוחה לפעול שההנהגה בדרך ה­ישר תיעשה כמו טבע.\nו. אמנם אעפ\"כ, מכיון שכ\"ז הוא מצד ה\"מראין\" שמלמעלה, ולא מצד האדם שלמטה, נמצא, שמצד מצב בנ\"י מצד עצמו אין ראיית המקדש פועלת בו באופן נצחי.\n[וע\"ד המבואר בכ\"מ<sup data-n=\"98\">45</sup> בנוגע להכרו­זים השונים שמכריזים מלמעלה, כדי לעורר את האדם לתשובה, שהוא ע\"י שהנשמה למעלה שומעת את הבת קול, וע\"י שהיא שומעת זה למעלה נמשך ונרגש גם בנשמה שלמטה, כמאמר<sup data-n=\"99\">46</sup>",[["95","42","ל' התוס' ב\"ב כא, א ד\"ה כי מציון."],["96","43","פ' ראה יד, כג. בספרי לפנינו ליתא. וראה בספרי מכת\"י (נ.י., תשכ\"ט)."],["97","44","שלכן הי' בזה חילוקים בדרגת הגילוי כמבואר בלקו\"ת ברכה צח, ב: שכל אחד ואחד מישראל לפום שיעורי' דילי' הי' מקבל גילוי זה כשהיו עולין לרגל שכולן חייבין בראי', לכך נאמר פני הוי' ל' רבים שלכל אחד הי' הגילוי לפי ערכו."],["98","45","ראה לקו\"ת תצא לו, ד. במדבר טז, א ואילך. יז, א. ד\"ה אריב\"ל בכ\"י ב\"ק כו' תש\"ב פ\"א. ובכ\"מ. וראה ספר חרדים בחתימת הספר (סגולה ו)."],["99","46","מגילה ג, א. סנהדרין צד, רע\"א."]]],[1301870082,"אע\"ג דאיהו לא חזי מזלי' חזי, ולכן אנו רואים שנופלים לו לאדם פתאום הרהורי תשובה בלי שום הכנה והתבוננות לזה מצדו — שמבואר בזה<sup data-n=\"100\">47</sup>, דכיון שהיא באה לא מצד האדם שלמטה, שהוא נתעורר בתשובה מצד עצמו, אלא מצד אתערותא דלעילא, אין להתעוררות זו קיום אצל האדם].\nוזהו שמדייק ש\"מראין לכאו\"א מ­ישראל המקדש דלעתיד מרחוק\", שאף שמראין המקדש דלעתיד, צריך שיורגש אצל האדם שהוא \"מרחוק\", ועבודת ה­אדם צ\"ל להתבונן בזה גופא, שמראין לו המקדש דלעתיד, והוא מצד עצמו רחוק מזה, וה\"ז גורם אצלו תנועה של ביטול עד שעי\"ז נעשה \"כלי\" שההמשכה מל­מעלה תורגש ותוקלט במציאותו.\nעפ\"ז יש לבאר גם השייכות לענין שבת חזון כפשוטו, שהוא ע\"ש התחלת ה­הפטרה \"חזון ישעיהו\", שבגלוי הוא \"אשר חזה על יהודה וירושלים גו'\", ענינים שהם היפך הישועה והנחמה, כי גילוי המחזה דהמקדש דלעתיד, בא ע\"י רגש הריחוק, המבואר בהפטרה ד\"שבת חזון\", שזה פועל הקירוב ש\"מחזון (יהי') ותחזינה עינינו\"<sup data-n=\"101\">48</sup>, דראיית המקדש לע­תיד לא תהי' מרחוק, אלא מקרוב.\nז. ע\"פ כל הנ\"ל יש לבאר העילוי המיוחד בראיית המקדש דלעתיד בקבי­עת שבת חזון שחל ביום ת\"ב עצמו, שאז נוסף ע\"ז שמראין לכאו\"א מישראל ה­מקדש דלעתיד, מעלת הגילוי שמצד למעלה, הרי כיון שבו ביום נולד משיח צדקנו, ועומד מוכן<sup data-n=\"102\">49</sup> לגאול את ישראל ולבנות המקדש במקומו, הרי זה מוסיף בהנתינת כח דעבודת האדם בשייכות ל­מקדש דלעתיד, שלא יהי' באופן של \"מרחוק\", אלא באופן קרוב, וקרוב ממש, השייך למציאות האדם,\nועי\"ז יורד ונתגלה ביהמ\"ק למטה בגלוי ממש לכאו\"א, ויה\"ר שנזכה לזה בשבת חזון דשנה זו ממש, ובפרט שר\"ת של השנה הם \"הי' תהי' שנת אראנו נפל­אות\", שהקב\"ה בעצמו מראה — אראנו — לכאו\"א מישראל נפלאות, דגאולה האמי­תית והשלימה, ד\"כימי צאתך מארץ מצ­רים אראנו נפלאות\"<sup data-n=\"103\">50</sup>, ותיכף ומיד ממש.\n<span data-k=\"q\">(משיחות ש\"פ דברים תשמ\"ז­ח)</span>",[["100","47","לקו\"ת ויקרא ד\"ה אדם כי יקריב ב, סע\"ב ואילך."],["101","48","ל' הצ\"צ באוה\"ת נ\"ך שם, כנ\"ל הערה 2."],["102","49","ראה יפה ענף לאיכ\"ר שם."],["103","50","מיכה ז, טו."]]],[1301870083,"<h3>שיחה א</h3>\nא. בפסוק<sup data-n=\"104\">1</sup> \"אז יבדיל משה שלש ערים בעבר הירדן גו'\" פרש\"י \"אז יבדיל — נתן לב להיות חרד לדבר שיבדילם, ואע\"פ שאינן קולטות כו'\" (כדלקמן סעיף ב).\nוכתבו המפרשים<sup data-n=\"105\">2</sup>, שהטעם שפירש רש\"י ש\"אז יבדיל\" קאי על המחשבה ל­הבדיל, \"נתן לב להיות חרד לדבר שיב­דילם\", ולא על מעשה ההבדלה עצמו, הוא מחמת התיבות \"אז יבדיל\", ד\"אז\" הוא לשון עבר, ובהמשך לזה הול\"ל \"(אז) הבדיל\", לשון עבר, ולא יבדיל לשון עתיד. ולכן פירש ש\"אז יבדיל\" קאי על המחשבה להבדיל (\"נתן לב. . לדבר\"), וכמו שפירש בפסוק<sup data-n=\"106\">3</sup> \"אז ישיר משה\" — \"אז כשראה הנס עלה בלבו שישיר שירה, וכן אז ידבר יהושע<sup data-n=\"107\">4</sup> וכן ובית יעשה לבת פרעה<sup data-n=\"108\">5</sup> חשב בלבו שיעשה לה אף כאן ישיר אמר לו לבו שישיר וכן עשה. . למדנו שהיו\"ד על שם המחשבה נאמרה\". וכן בנדו\"ד, דמ\"ש \"אז\" לשון עבר ו\"יב­דיל\" לשון עתיד, הוא לפי שקאי על המחשבה שיבדיל שהיא לפני (והסיבה ל)מעשה של ההבדלה בפועל.\nוצריך להבין, דאם הכוונה היא רק על המחשבה הי' לו לרש\"י לכתוב \"נתן לב להבדיל\" וכיו\"ב, ולמה מחזק ומדגיש \"נתן לב להיות חרד לדבר\".\nגם צריך ביאור: מהו הדיוק \"אז יב­דיל\", דמשמע שכאן קרה מאורע מיוחד שבגללו \"נתן לבו כו' שיבדילם\" (וע\"ד שפרש\"י תיבת \"אז\" בפסוק \"אז ישיר\" — \"אז כשראה הנס\", וכן בשאר הדוגמאות שם).\nב. להלן ממשיך רש\"י: \"ואע\"פ שאינן קולטות עד שיבדלו אותן שבארץ כנען אמר משה מצוה שאפשר לקיימה אקיי­מנה\"<sup data-n=\"109\">6</sup>.\nויש לדייק — למה הביא רש\"י ענין זה (\"ואע\"פ שאינן קולטות כו'\") באותו ד\"ה, שלא כדרכו ברוב המקומות, לכתוב כל ענין בד\"ה בפ\"ע, והרי לפום ריהטא ביאר רש\"י כאן ב' דברים שונים: א) פירוש התיבות \"אז יבדיל\", ב) ביאור הענין ש­הבדיל משה ערים אלו \"אע\"פ שאינן קולטות כו'\" — ומה טעם צירפם רש\"י בד\"ה אחד?\nיש מפרשים<sup data-n=\"110\">7</sup>, שהמשך דברי רש\"י \"ואע\"פ שאינן קולטות כו'\" הוא הביאור<sup data-n=\"111\">8</sup> והתירוץ ע\"ז שנאמר \"אז יבדיל\" — לשון עתיד, דכיון שלא היו קולטות אז, לפיכך לא שייך לומר הבדיל (ל' עבר). אבל פירוש זה דורש ביאור<sup data-n=\"112\">9</sup>, דאע\"פ שאינן קולטות, הרי ההבדלה של ערים אלו כבר הי', ולכן \"הבדיל\" הוא לשון עבר.",[["104","1","פרשתנו ד, מא."],["105","2","ראה רא\"ם, רע\"ב, גו\"א, משמרת הקודש, באר רחובות, ועוד. ספר זכרון בשלח טו, א."],["106","3","בשלח שם."],["107","4","יהושע יוד, יב."],["108","5","מ\"א ז, ח."],["109","6","והוא ממכות יוד, א."],["110","7","נחלת יעקב כאן. דבק טוב. וראה גם באר מים חיים (לאחי המהר\"ל). צפע\"נ עה\"ת פרשתנו ג, כה."],["111","8","ויומתק ע\"פ הגירסא בא' מכת\"י רש\"י (שתח\"י) \"אע\"פ\" (בלא וא\"ו)."],["112","9","כמו שהקשה בבאר בשדה על פרש\"י כאן."]]],[1301870084,"ג. והביאור בזה:\nהפעם הראשונה שנתפרש בכתוב ענין הבדלת ערי מקלט היא בפ' מסעי, ושם נאמר<sup data-n=\"113\">10</sup> \"כי אתם עוברים את הירדן ארצה כנען והקריתם לכם ערים ערי מק­לט תהיינה לכם. . והערים אשר תתנו שש ערי מקלט תהיינה לכם את שלש הערים תתנו מעבר לירדן ואת שלש ה­ערים תתנו בארץ כנען ערי מקלט תהיי­נה\", הרי שהזמנת והבדלת ערי מקלט (גם אלו שבעבר הירדן) הוא לאחרי ש\"אתם עוברים את הירדן\"<sup data-n=\"114\">11</sup>.\nומשמע מזה, שמצות ערי מקלט הוא דבר התלוי בארץ ישראל, ע\"ד מצוה ה­תלוי' בארץ, שלכן לא חל החיוב והמצוה אלא לאחרי שעברו את הירדן והיו בארץ ישראל, אלא שכיון שגם עבר הירדן ירשו בני ישראל ודרים שם<sup data-n=\"115\">12</sup>, לכן עו­שים ערי מקלט גם (בדרך טפל<sup data-n=\"116\">13</sup>) בעבר הירדן<sup data-n=\"117\">14</sup>.\nוהנה החידוש שנתחדש בפשטות ה­כתובים בפרשת ואתחנן הוא, שעד אז הי' משה עדיין מצפה שמא יורשה לו ליכנס לארץ (ובפרט לאחרי כיבוש סיחון ועוג, ש\"דמיתי שמא הותר הנדר\"<sup data-n=\"118\">15</sup>), אבל ב­פרשתנו כבר נאמר למשה (לאחרי ש­\"ואתחנן אל ה' גו' אעברה נא גו' — ויאמר ה' אלי רב לך אל תוסף דבר אלי עוד בדבר הזה עלה ראש הפסגה גו') כי לא תעבור את הירדן הזה\"<sup data-n=\"119\">16</sup>.\nוזהו מה שפירש רש\"י כאן עה\"פ \"אז יבדיל\" — שהמדובר הוא לאחרי שישראל כבר מוכנים ליכנס לארץ [וכמפורש בכתוב שלפנ\"ז<sup data-n=\"120\">17</sup> \"להוריש גוים גו' להבי­אך לתת לך את ארצם נחלה כיום הזה\", ובפרש\"י \"כאשר אתה רואה היום\"], וכבר ידוע שמשה אינו נכנס עמהם, הנה \"אז\" — \"נתן לב להיות חרד לדבר שיבדילם\":\nהפירוש הפשוט של חרדה זו, יראה הנובעת מחשש אם מעשיו בזה הם כדרוש וכדבעי. וזהו שמשה \"נתן לב להיות חרד לדבר שיבדילם — ואע\"פ שאינן קולטות עד שיבדלו אותן שבארץ כנען כו'\" — דכיון שהיא מצוה התלוי' בארץ, שכל גדר של ערי מקלט הוא לאחרי שיעברו את הירדן לארץ כנען, חשש שמא גם הזמנת והבדלת הערים היא רק לאחרי כניסתם לארץ ישראל, ואין מקום שמשה יבדילם קודם לכן.\nויתירה מזו יש לומר, ד\"חרדה\" זו היא",[["113","10","לה, יוד ואילך."],["114","11","ודוחק גדול לומר דפשוטו של מקרא זה הוא דכיון שאתם עומדים לעבור את הירדן לכן \"והקריתם\" עכשיו (לפני העברת הירדן), שהרי לשון הכתוב הוא \"כי אתם עוברים את הירדן גו'\" — שם לג, נא­נב (וראה רש\"י שם, נא)."],["115","12","ראה לקו\"ש חי\"ג ע' 124 ואילך (ובהערה 20 שם), דאף שלדעת רש\"י גם ארץ סיחון ועוג (עבר הירדן) ניתנה לאברהם כו' (דלא כאור החיים מטות לב, ז. דברים ב, כ. וראה אוה\"ח שם ג, יג — ב' האופנים), מ\"מ, המצות התלויות בארץ נוהגות רק ב\"זאת הארץ אשר תפול לכם בנחלה ארץ כנען לגבולותי'\" (מסעי לד, ב ורש\"י שם)."],["116","13","וע\"ד עצם נחלת בני גד ובני ראובן (וכיבוש ארץ סיחון ועוג בכלל), שבכל אופן נעשה נחלת ישראל בתור הוספה (וטפילה) לנחלת ארץ כנען, כמפורש בפשש\"מ בס\"פ מטות — ועד\"ז במצות ערי מקלט, שעיקר מציאותן הוא בארץ כנען, ורק בדרך טפל ישנן ערי מקלט בעבר הירדן. ולהעיר מאלשיך פ' שופטים (יט, ח), שלעת\"ל יתבטלו השלש שבעבר הירדן \"כי לא ישבו שם ישראל\". ע\"ש."],["117","14","וראה לקמן סעיף ה."],["118","15","פרש\"י ריש פרשתנו."],["119","16","ג, כג­כז."],["120","17","ד, לח."]]],[1301870085,"אם זה כפי רצון ה', דכשם שרצון ה' שמשה לא יכנס לארץ, כמו\"כ אולי רצונו ית' שמצוות התלויות בארץ לא ייעשו על ידו, וזהו טעם חרדתו של משה — לא רק אם יש איזו חלות בהבדלה שלו, אלא אם ההבדלה שלו היא כפי רצון ה'.\n[עפ\"ז י\"ל, שאין כוונת רש\"י כאן רק לפרש התיבות — \"אז יבדיל\" לשון עתיד על שם המחשבה שהיא לפני העשי' (כמו שפי' בפסוק \"אז ישיר\"), אלא שגם כל מעשה משה כאן הוא באופן של \"יבדיל\", שחרד בעשיית ההבדלה, והסיבה לכך היא — \"אז\", מאחר שעומדים ליכנס לארץ, והוא אינו נכנס עמהם (ונמצא שהוא דבר שאינו שייך אליו), כנ\"ל. וזהו \"יבדיל\" ל' עתיד, לפי שהי' מעין הבדלה בנוגע למעשה ההבדלה גופא].\nד. ויש לבאר הענין ע\"ד ההלכה, וב­הקדם דברי הרמב\"ם בהל' רוצח ושמי­רת נפש<sup data-n=\"121\">18</sup>:\n\"מצות עשה להפריש ערי מקלט שנאמר<sup data-n=\"122\">19</sup> שלש ערים תבדיל לך ואין ערי מקלט נוהגת אלא בארץ ישראל\". ובהלכה שלאח\"ז: \"ושש ערים היו, שלש הבדיל משה רבינו בעבר הירדן ושלש הבדיל יהושע בארץ כנען\", ובהלכה של­אח\"ז: \"אין אחת מערי מקלט קולטת עד שיובדלו כולן שנאמר<sup data-n=\"123\">20</sup> שש ערי מקלט תהיינה לכם, והודיענו משה רבינו שאין שלש שבעבר הירדן קולטות עד שיובדלו שלש שבארץ כנען, ולמה הבדילן אמר הואיל ובאה מצוה לידי אקיימנה\".\nוצריך ביאור:\nא) למה מביא בהלכה הא' \"מצות עשה להפריש ערי מקלט\" מהכתוב \"שלש ערים תבדיל לך\", הרי בהלכה שלאח\"ז מפורש \"ושש ערים היו\"? ולמה לא הביא הכתוב שבו מפורש שישנן שש ערי מקלט, וכמ\"ש בהלכה הג' \"שש ערי מקלט תהיינה לכם\", או הכתוב שלפנ\"ז<sup data-n=\"124\">21</sup> \"והקריתם לכם ערים ערי מקלט תהיינה לכם\"<sup data-n=\"125\">22</sup>.\nב) בהלכה ב' — מהו לשונו \"ושש ערים היו\" — לשון של סיפור דברים, דלכאורה הול\"ל לשון של ציווי וחיוב.\nג) בהלכה ג' כ' \"והודיענו משה רבינו שאין שלש שבעבר הירדן קולטות עד שיובדלו שלש שבארץ כנען\", ולכאורה הלכה זו כבר נכללת במ\"ש בתחילת ההלכה ש\"אין אחת מערי מקלט קולטת עד שיובדלו כולן שנאמר שש ערי מקלט תהיינה לכם\". ובפרט מהו שמוסיף \"והודיענו משה רבינו\", שמזה מוכח, ש­זהו דין נוסף שאינו נכלל בדברי הכתוב \"שש ערי מקלט תהיינה לכם\".\nובכלל צ\"ע מ\"ש הרמב\"ם \"(והודיענו משה רבינו כו') ולמה הבדילן אמר הואיל ובאה מצוה לידי אקיימנה\" — הרי א) ה­רמב\"ם הוא ספר \"הלכות הלכות\", ב)",[["121","18","רפ\"ח."],["122","19","שופטים יט, ב."],["123","20","מסעי לה, יג."],["124","21","שם, יא."],["125","22","במנין המצות שבריש ספר היד מ\"ע קפב \"להכין שש ערי מקלט שנאמר (שופטים שם, ג) תכין לך הדרך ושלשת\", ועד\"ז בסהמ\"צ שם [ובהוצאת העליר וקאפח, במקום \"להכין\" — \"להבדיל\". אבל בשניהם התוכן \"להכין\", וכמו שממשיך (בהוצאת העליר, ועד\"ז בהוצאת קאפח) \"ושיתוקן דרך אליהם ויישירו אותם\"]. ובהכותרת להל' רוצח \"להפריש ערי מקלט ולכוין<sup data-n=\"e5\">*</sup> להם הדרך\" ואינו כותב מנין הערים."],["e5","*","ובמנין המצות שעל סדר ההלכות בריש ספר היד — \"ולהכין לו\"."]]],[1301870086,"למאי נפק\"מ להלכה השקו\"ט למה הבדיל משה רבינו את שלש הערים בעבר הירדן<sup data-n=\"126\">23</sup>.\nה. ונראה שהן הן הדברים:\nבמ\"ש בריש הלכות מצות ערי מקלט \"מצות עשה להפריש ערי מקלט שנאמר שלש ערים תבדיל לך ואין ערי מקלט נוהגת אלא בארץ ישראל\", קמ\"ל הרמ­ב\"ם שמצוה זו היא מצוה התלוי' בארץ, ולכן יסוד מצות ערי מקלט הוא מ\"ש \"שלש ערים תבדיל לך\"<sup data-n=\"127\">24</sup>, כי עיקר חיוב ומצוה דהפרשת ערי מקלט היא על שלש הערים שבא\"י<sup data-n=\"128\">25</sup>; ואח\"כ ממשיך (בהלכה בפ\"ע) \"ושש ערים היו כו'\", כלומר, ש­הגם שיסוד החיוב והמצות עשה הוא הבדלת שלש ערים בארץ ישראל, מ\"מ, \"שש ערים היו\", שהלכה שבפועל יהיו שש ערי מקלט שקולטות את הרוצח (גם שלש בעבר הירדן), שדיני ערי מקלט חלים על כל ששת הערים.\nונקודה זו חוזר ומדגיש הרמב\"ם בה­לכה הג', דכשם שהוא בהמ\"ע דהפרשת ערי מקלט, שהמצוה היא בארץ ישראל דוקא (והבדלת ג' ערים בעבר הירדן היא כעין טפל ודבר נוסף), עד\"ז מצינו בדין קליטתן — ש\"הודיענו משה רבינו שאין שלש שבעבר הירדן קולטות עד שיובדלו שלש שבארץ כנען\", ודין זה אינו בכלל הלימוד שבתחילת ההלכה \"שש ערי מקלט תהיינה לכם\", שאין כל אחת משש ערי מקלט קולטת עד שיובדלו כולן — אלא הוא דין מיוחד בערי מקלט שבעבר הירדן<sup data-n=\"129\">26</sup>.\nכלומר: הדין הראשון שבהלכה זו — \"אין אחת מערי מקלט קולטת עד שיובדלו כולן\" — הוא, שדין קליטת ערי מקלט הוא רק כשישנן כל ששת ערי מקלט, דכל ששת ערי מקלט הוי כמו חפצא אחת, ולכן אם חסרה אחת מהן אין דין קליטה בכולן, ודין זה שווה בכל שש ערי מלקט, הן אותן שבארץ כנען והן אותן שבעבר הירדן<sup data-n=\"130\">27</sup>.\nואח\"כ מוסיף הרמב\"ם עוד הלכה — \"והודיענו משה רבינו שאין שלש שבעבר הירדן קולטות עד שיובדלו שלש שבארץ כנען\" — דכיון שכל עיקר מצות הפרשת",[["126","23","ראה שיח יצחק למשנה מכות שם (ט, ב) — במשנה וברמב\"ם. ובתפארת ישראל שם (אות לא) הקשה כן במשנה."],["127","24","דפסוק זה נאמר בנוגע לשלש שבארץ כנען."],["128","25","ראה גם מהריט\"ץ הובא בברכי יוסף או\"ח סתפ\"ט אות ג ד\"ה ואני. וראה השקו\"ט שם בלשון הרמב\"ם כאן (וכן בגדר עבר הירדן בכלל). וש\"נ (ובברכ\"י שם מסיק שלדעת הרמב\"ם עבר הירדן אינו בכלל א\"י). וראה הנסמן בלקו\"ש חי\"ג שם."],["129","26","להעיר מספרי דבי רב לספרי שם (לה, טו), דמפרש דדרשת המשנה (מהכתוב לה, יג) ודרשת הספרי (מהכתוב שם, טו) — הם בנוגע לב' דברים. ע\"ש."],["130","27","ראה ספרי דבי רב שם בנוגע לדרשת הספרי, דאפילו לאחר שהתחילו להפריש אותן שבארץ ישראל כ\"ז שלא הפרישו שלשתן לא קלטה שום אחת מהן, וממשיך \"ואולי דאיכא למשמע מזה גם לעת\"ל. . דהתם נמי לא תקלוט שום אחת [גם מאותן שבארץ קיני קניזי וקדמוני] עד שיפרישו כולן\", ומביא לשון הרמב\"ם הנ\"ל \"אין אחת מערי מקלט קולטות עד שיופרשו כולן כו'\".\nועוד י\"ל דנוגע לפועל בזמן הבית — אם חרבה אחת מהן אם השאר קולטות. וראה תוספ­תא מכות פ\"ב, ב. צפע\"נ להל' תרומות בתחלתו (ב, א ואילך), נעתק בצפע\"נ לירושלמי מכות שם. אבל ראה שירי קרבן לירושלמי מכות שם פ\"ב ה\"ו (לדף ז, ב) ד\"ה ותימה. שיח יצחק למשנה מכות שם. ועוד. וראה מדרש דברים רבה מכת\"י (ירושלים, תשל\"ד) ע' 62."]]],[1301870087,"ערי מקלט נוהגת רק בארץ ישראל (והיא מהמצות התלויות בארץ), לכן א\"א ש­יחול דין ערי מקלט על אותן שבעבר הירדן רק לאחרי שישנן השלש שבארץ כנען (שהפרשתן הוי עצם המצוה, \"שלש ערים תבדיל לך\"). וזהו גם החידוש בדין זה לגבי התלות של כל שש ערי מקלט זב\"ז, דשם תלויים זב\"ז רק לענין דין קליטתם, משא\"כ בנוגע לאותן שבעבר הירדן, שאין הכוונה רק בדין קליטתם, אלא שאין כאן חלות שם ערי מקלט כל זמן שלא נבדלו אותן שבארץ כנען.\nוי\"ל דנפק\"מ לענין הנודר \"מערי מק­לט שהיו קודם שנכנסו לארץ\".\nו. והנה ע\"פ הנ\"ל — שקודם הבדלת אותן שבארץ כנען לא חל שם עיר מקלט — יש לעיין מה הי' תוכן דמעשה משה בהבדלת ערי מקלט שבעבר הירדן.\nויש לבאר זה בשני אופנים:\nא) ההבדלה היתה הכנה בעלמא (ש­בחר את הערים ותחומיהן, ואולי גם כיוון את הדרכים<sup data-n=\"131\">28</sup>), דאף שלא הי' בזה קיום מצוה ולא חלות שם עיר מקלט, מ\"מ ה\"ז כמו הכנה<sup data-n=\"132\">29</sup> והכשר<sup data-n=\"133\">30</sup> לקיום מצות ערי מקלט לאחרי זה.\nב) אף שקודם הבדלת אותן שבארץ כנען לא חל שם עיר מקלט, הרי לאחרי שיהושע הבדיל את הג' שבארץ כנען חל שם עיר מקלט על אותן שבעבר הירדן בדרך ממילא מצד הבדלת משה<sup data-n=\"134\">31</sup>, ונמ­צא, שמעשה משה פעל שיובדלו כערי מקלט<sup data-n=\"135\">32</sup>, אלא שחלות הדבר לא היתה עד אחרי זמן יהושע [ואולי יש לומר יתירה מזו — שלאחרי שהבדיל יהושע ג' שבארץ כנען, חל שם עיר מקלט על הג' שבעבר הירדן למפרע<sup data-n=\"136\">33</sup>, מזמן הבדלת משה]<sup data-n=\"137\">34</sup>.\nוהנפק\"מ בפועל בין שני אופנים אלו<sup data-n=\"138\">35</sup>: לאופן הא' הי' יהושע צריך להב­",[["131","28","ראה לעיל הערה 22, שלהרמב\"ם (הן בסהמ\"צ והן בספר היד) זהו בכלל המצוה."],["132","29","ראה דב\"ר (פ\"ב, כו­כז) שמשווה הפרשת ערי מקלט ע\"י משה (\"אז יבדיל\") לדוד \"שאמר לו הקב\"ה רק אתה לא תבנה לי את הבית הזה. . מה עשה זירז את עצמו והתקין כל צרכיו כו' והנה בעניי הכינותי לבית אלקי\"."],["133","30","וכפשטות הפירוש ד\"והקריתם\" (מסעי לה, יא), דנאמר למשה — \"ותזמנון\" (ת\"א ורש\"י שם), ואח\"כ (שם, יג­יד) מפרש עוד ענין \"והערים אשר תתנו. . שלש הערים תתנו מעבר לירדן. . שלש הערים תתנו בארץ כנען\". וראה ספרי דבי רב לספרי ר\"פ מסעי. חסדי דוד לתוספתא מכות רפ\"ב."],["134","31","והיינו שהי' לא מעשה בעלמא אלא גדר בדין. ולפ\"ז יל\"פ דההשוואה בדב\"ר שם להכנה דדוד הוא בזה שדוד גם קידש את העזרה (ראה זבחים כד, א). אבל דוחק, כי בדב\"ר שם הובא רק הכתוב ע\"ד הכנת הזהב כו'."],["135","32","להעיר, שלהתוספתא והירושלמי מכות שם, גם ג' הערים שבארץ כנען הבדיל יהושע תיכף בכניסתו לארץ<sup data-n=\"e6\">*</sup>, ולא קלטו עד לאחרי ירושה וישיבה. וראה בהנסמן בהערה 30. וראה הערה 34."],["136","33","ראה צפע\"נ עה\"ת פרשתנו ג, כה בסופו."],["137","34","להעיר שלהצפע\"נ (הנסמן לעיל סוף הערה 27) גם לפני קליטת כל השש ערים, ע\"י עצם הפרשת הערים שבא\"י פעל שיקלטו הני שבעבר הירדן, עכ\"פ שיהי' כמו מחנה לוי' דמהני שקולט לדעת. ע\"ש."],["138","35","וי\"ל דנפק\"מ גם בפשטות, אם משה מדד בין כל עיר ועיר, דלאופן הא' י\"ל שלא הוצרך לזה כי לא הי' בזה דין הפרשה, משא\"כ לאופן הב' — ראה רמב\"ם שם ה\"ז \"וכן מושחין בין כל עיר ועיר מערי מקלט בתחילת הפרשתן כו'\" (וראה שיח יצחק למכות (ט, ב) שלדעת הרמב\"ם דין זה הוא (גם) בשלש של עבר הירדן)."],["e6","*","ולא כהדיעה (רש\"י מכות ט, ב במשנה ד\"ה עד. שם יא, רע\"א. רד\"ק יהושע כ, ב. רמב\"ן פ' שופטים יט, א) — שהפרשת ערי מקלט ע\"י יהושע היתה אחרי י\"ד שנים שכבשו וחלקו (כפשטות המקראות דיהושע שם)."]]],[1301870088,"דיל עוד פעם את הערים שבעבר הירדן לאחרי שהבדיל אותן שבארץ כנען, שרק אז חל עליהם שם עיר מקלט, וכן פירשו מפרשים<sup data-n=\"139\">36</sup> דברי הספרי<sup data-n=\"140\">37</sup> \"מנין שצוה משה את יהושע להפריש להם ערי מקלט כו'\", דהיינו \"שצוה משה את יהושע שהוא הוא יפריש כל ששה ערים שגם אותם שבעבר הירדן לא היו קולטים עד שהפריש יהושע כל שש ערים\"<sup data-n=\"141\">38</sup>; משא\"כ לאופן השני, לא הי' צ\"ל עוד הבדלה ע\"י יהושע, אלא לאחרי הבדלת יהושע חל שם עיר מקלט עליהם (למפרע?<sup data-n=\"142\">39</sup>) ע\"י הבדלת משה.\nויש לומר, שבזה פליגי רש\"י והרמ­ב\"ם, ובהקדם השינוי בין לשון הרמב\"ם ולשון רש\"י: ברמב\"ם הלשון \"אמר הואיל ובאה מצוה לידי אקיימנה\", והוא לשון הגמרא במכות; אבל רש\"י שינה מלשון הש\"ס וכ' \"מצוה שאפשר לקיימה אקיי­מנה\".\nוהחילוק בין ב' לשונות הנ\"ל: הלשון \"באה מצוה לידי\" מדגיש אפשריות קיום המצוה מצד הגברא (\"באה. . לידי\"), מש­א\"כ הלשון \"מצוה שאפשר לקיימה\" מד­בר על האפשריות מצד החפצא, \"מצוה שאפשר לקיימה\"<sup data-n=\"143\">40</sup>. וזהו תוכן החילוק בין שני אופנים הנ\"ל: לאופן הא' שמעשה משה הי' רק הכנה בעלמא, הרי מעשהו נקרא בשם \"מצוה\" רק מצד הגברא, שהוא הי' עסוק ב(הכנה ל)דבר מצוה, אבל מצד החפצא לא נפעל עדיין גדר של מצוה; משא\"כ לאופן הב' הרי חל שם \"מצוה\" על מעשה משה גם מצד החפצא, כיון שהוא הבדיל ערים אלו לערי מקלט (אלא שלא חל בפועל עד לאחרי שיהושע הבדיל אותן שבארץ כנען).\nובזה פליגי רש\"י והרמב\"ם — דרש\"י ס\"ל שמעשה משה פעל שיחול עליהן שם עיר מקלט<sup data-n=\"144\">41</sup> (אלא שהחלות בפועל היתה אח\"כ בימי יהושע), ולכן כ' \"מצוה שאפ­שר לקיימה אקיימנה\"; משא\"כ הרמב\"ם ס\"ל שהי' רק הכשר בעלמא, ולכן נקט לישנא \"הואיל ובאה מצוה לידי אקיי­מנה\"<sup data-n=\"145\">42</sup>.\nז. מ\"יינה של תורה\" שבפירוש רש\"י:\nזה ששלש הערים שבעבר הירדן לא קלטו עד שהובדלו אותן שבארץ כנען דורש ביאור, לכאורה, דכיון שבני גד ובני ראובן וחצי שבט מנשה כבר התייש­בו בעבר הירדן (כמסופר בס\"פ מטות",[["139","36","תולדות אדם לספרי."],["140","37","ריש פ' מסעי."],["141","38","ועפ\"ז לכאורה יש לפרש הכתובים ד­יהושע (כ, ח) בפשטות (ודלא כפרש\"י שם), שזה ש\"נתנו\" הערים שבעבר הירדן לערי מקלט היתה ע\"י יהושע."],["142","39","ואולי י\"ל דהנפק\"מ בזה — בא' שהי' נמצא בא' מערים אלו לפנ\"ז, דאת\"ל שהקליטה היא לא מה שהוא שם אלא הכניסה לשם (ראה צפע\"נ עה\"ת פרשתנו עה\"פ), יש לומר, דאם חל עליו שם עיר מקלט למפרע, נחשב שנכנס לעיר מקלט."],["143","40","אבל בדפוס ראשון דפרש\"י \"אפשי לקיים המצוה אקיימנה\" (ועד\"ז בכמה כת\"י רש\"י שתח\"י)."],["144","41","ולכן פרש\"י הכתוב דיהושע שם \"ומעבר לירדן יריחו מזרחה נתנו\" — \"בימי משה כו'\". ולהעיר מהוספת רש\"י במשנה מכות שם ט, ב ד\"ה לא היו \"שלש שהבדיל משה בעבר הירדן קולטות\"."],["145","42","להעיר מלשון הרמב\"ם פיה\"מ אבות (פ\"ד מ\"ב). וראה חקרי לב יו\"ד ח\"ב בסופו בקונ­טרס כונן לחוקר (שיח, ג). ואכ\"מ."]]],[1301870089,"וס\"פ דברים), מהו הטעם שלא ניתן להם מיד ההגנה דערי מקלט<sup data-n=\"146\">43</sup>?\n[ואע\"פ ש\"כל חלוץ מלחמה\" עבר עם שאר השבטים לכבוש את ארץ כנען — הרי (א) לא עברו ישראל את הירדן עד לאחרי כמה חדשים, ובמשך זמן זה ישבו בני גד ובני ראובן וחצי שבט מנשה בעריהם שנחלו בעבר הירדן, (ב) ועיקר: גם אח\"כ נשארו שם האנשים שקודם כ' ושלמעלה מבן ס', מלבד הנשים והטף].\nואולי י\"ל שהטעם הפנימי בדבר הוא — לפי שלא היו צריכים לערי מקלט, וכמו שאמר משה רבינו<sup data-n=\"147\">44</sup> \"ואתם הדבקים בה\"א חיים כולכם היום\", שבנ\"י היו דבוקים במקום<sup data-n=\"148\">45</sup> עד שלא היו שייכים כלל לענין של היפך החיים ר\"ל [והרי גם הורג נפש בשגגה צריך כפרה<sup data-n=\"149\">46</sup>, שמזה מובן שחסר אצלו בדביקות עם ה\"א].\nויש לומר, שמצב נעלה זה דבנ\"י נפעל בהם ע\"י משה רבינו, שהוא העלה אותם לדביקות נעלית זו בה\"א באופן ש\"חיים כולכם היום\", משא\"כ לאחרי הסתלקות משה<sup data-n=\"150\">47</sup> ירדו ממדריגתם כו' ובמילא הוצרכו לערי מקלט.\nח. ועפ\"ז יש לבאר החילוק בין שני האופנים הנ\"ל בגדר פעולת משה בהב­דלת ערי מקלט בעבר הירדן — אם היתה רק בגדר הכנה בעלמא, או שהבדלתו פעלה חלות שם עיר מקלט — ע\"פ פנימיות הענינים:\nענינן של ערי מקלט אינו רק שלילה — הגנה מגואל הדם — אלא גם ענין של חיוב — \"ונס אל אחת מן הערים האל וחי\"<sup data-n=\"151\">48</sup>, עביד לי' מידי דתהוי לי' חיותא<sup data-n=\"152\">49</sup>. ובפנימיות הענין: הריגת נפש בשגגה מורה על שליטת היצר הרע, דהוא השטן והוא המלאך המות<sup data-n=\"153\">50</sup>, ובלשון התניא<sup data-n=\"154\">51</sup> — שמקבל חיות מ\"מקום המיתה והטומאה\", ובעיר מקלט נמשך לו חיות מסטרא דקדושה — \"ונס. . וחי\", בחיים אמיתיים, חיים של קדושה הבאים ממקור החיים, \"ה' אלקים אמת הוא אלקים חיים\"<sup data-n=\"155\">52</sup>.\nולכן גם מצות הבדלת ערי מקלט היתה צ\"ל בזה פעולת משה, כי על ידו נמשך הענין ד\"אתם הדבקים בה\"א חיים כולכם היום\" לבני ישראל, כולל גם — המשכת החיות ע\"י ערי מקלט<sup data-n=\"156\">53</sup> להורג נפש בשגגה<sup data-n=\"157\">54</sup>.",[["146","43","אבל להעיר ממרז\"ל (מכות יב, ב. רש\"י משפטים כא, יג) דגם במדבר מחנה לוי' קולט."],["147","44","פרשתנו ד, ד."],["148","45","ראה גם אוה\"ח עה\"פ."],["149","46","רש\"י נח ט, ה. וראה מכות ב, ב (ובתוד\"ה מידי — שם יא, ב). ובכ\"מ."],["150","47","ראה וילך לא, טז. שם, כט (ולהעיר מ­פרש\"י שם)."],["151","48","פרשתנו ד, מב. וראה גם שופטים יט, ד­ה."],["152","49","מכות י, א. רמב\"ם שם רפ\"ז."],["153","50","ב\"ב טז, א."],["154","51","ח\"א פכ\"ב (כז, ב). ועד\"ז שם אגה\"ת פ\"ז (צז, סע\"א)."],["155","52","ירמי' י, י."],["156","53","להעיר דזה שד\"ת קולטים ממלאך המות למדין (במכות שם) מהמשך הכתוב בפרשתנו \"ש­נאמר (ד, מג) את בצר במדבר וגו' וכתיב בתרי' (שם, מד) וזאת התורה\", והיינו תורת משה כהמשך הכתוב \"אשר שם משה גו'\"."],["157","54","ראה מכות שם: \"דרש רב שמלאי מאי דכתיב אז יבדיל משה. . א\"ל הקב\"ה למשה הזרח שמש לרוצחים. . הזרחת שמש לרוצחים\" — ראה חדא\"ג מהרש\"א שם. וע\"פ הנ\"ל י\"ל שאין הכוונה רק \"שיראו (הרוצחים) וישמחו בהבדלתן (דערי מקלט)\", אלא שזה רפואתם והצלתם ממקום המיתה, כתוכן ענין זריחת השמש."]]],[1301870090,"וזהו תוכן ב' הסברות הנ\"ל בגדר פעולת משה:\nלאופן הא' שמעשה ידי משה הי' רק בגדר הכנה בעלמא אבל לא פעל ענין של הבדלת ערי מקלט בפועל — ה\"ז כדי להדגיש ולהורות שמצד מדריגת משה לא שייך מעיקרא כל הענין דהורג נפש בשגגה ואין צורך בערי מקלט כנ\"ל, והיינו שגם ענין המשכת החיות להורג נפש בשגגה הוא למטה ממדריגת משה.\n[ויש לומר, שלסברא זו, זה גופא ש­משה עשה רק הכנה בעלמא לערי מקלט (מבלי שיהי' עי\"ז חלות בפועל של שם ערי מקלט), הוא לפי שרצה לפעול עי\"ז, שגם אח\"כ לא יהי' צורך כ\"כ בערי מקלט, ע\"י שיתמעטו הורגי נפש שיצ­טרכו לערי מקלט].\nאבל לאופן הב' פעל משה חלות שם עיר מקלט — כי אע\"פ שמשה מצד עצמו הוא למעלה מכל ענין של הורג נפש בשגגה (גם מהמשכת חיות אליו), מ\"מ, להיותו רועה נאמן, הוריד את עצמו להמשיך חיות גם לבנ\"י שיצטרכו (לאחרי זמן) לערי מקלט<sup data-n=\"158\">55</sup>.\nוזהו שכ' רש\"י \"נתן לב להיות חרד לדבר שיבדילם\", כי הבדלת ערי מקלט ע\"י משה רבינו קשורה עם ירידתו ממדריגתו, להמשיך חיות גם למי שנפל ל\"מקום המיתה והטומאה ה' ישמרנו\"<sup data-n=\"159\">56</sup>, ולכן פעל עליו חרדה (המסלקת את הדמים<sup data-n=\"160\">57</sup>);\nאבל לאידך \"נתן לב להיות חרד לדבר שיבדילם\", שלא רק שעשה כן בפועל, אלא נתן לב על זה, כי זהו ענינו של רועה נאמן, שמוסר נפשו עבור צאן מרעיתו, וממשיך חיות גם למי שנצטרך ללכת בגולה, \"ונס. . וחי\", עד שגם הוא יתעלה להיות מן \"הדבקים בה\"א חיים כולכם היום\".\nוכן תהי' לנו, בגלותנו זה המר, שלא זו בלבד שאין להגלות שום שליטה ח\"ו על ישראל, כי ישנה ההגנה הרוחנית דערי מקלט — דברי תורה קולטין<sup data-n=\"161\">58</sup>, אלא עוד זאת, ש\"ונס. . וחי\", שנמשך לכאו\"א מישראל ענין החיים, חיים אמיתיים,\nעדי קיום היעוד<sup data-n=\"162\">59</sup> \"יחיינו מיומיים ביום השלישי יקימנו ונחי' לפניו\", בחיים הנצחיים<sup data-n=\"163\">60</sup>, בגאולה האמיתית והשלימה על ידי משיח צדקנו, ותיכף ומיד ממש.\n<span data-k=\"q\">(משיחת ש\"פ ואתחנן תשמ\"ה) </span>",[["158","55","וי\"ל שזהו החילוק דב' הלשונות במכות שם, אם א\"ל הקב\"ה \"הזרח שמש לרוצחים\" או \"הזרחת שמש לרוצחים\", דכפשוטו (ראה פרש\"י ומהרש\"א) החילוק הוא אם הקב\"ה ציוהו ע\"ז או שמשה מעצמו הבדילן — וע\"פ הנ\"ל יש לומר, שכיון דמשה מצ\"ע הוא למעלה מזה (כאופן הא'), וע\"ז אמר \"הזרחת\"; וכדי להמשיך חיות גם להורג נפש בשגגה, הוצרך להיות ציווי ונתינת כח מיוחד — \"הזרח כו'\"."],["159","56","לשון התניא הנ\"ל הערה 51."],["160","57","נדה לט, רע\"א (במשנה). וש\"נ."],["161","58","מכות שם. וראה לעיל הערה 53 שלמדין זה מפרשתנו שם."],["162","59","הושע ו, ב. וראה רש\"י ומצו\"ד שם."],["163","60","רד\"ק עה\"פ (בסופו). מצו\"ד שם. ובת­דב\"א רבא פ\"ה ד\"ביום השלישי\" קאי על עוה\"ב, וראה אוה\"ת עה\"פ, רד\"ה יחיינו תרנ\"ט — דקאי על עולם התחי', שאז יהיו חיים נצחיים (זח\"א קיד, ב)."]]],[1301870091,"<h3>שיחה ב</h3>\nא. במנין המצות שבריש הל' תפילין, כתב הרמב\"ם (אודות שתי המצות שב­הלכות אלו): א) להיות תפילין על הראש, ב) לקשרם על היד.\nוכבר תמהו מפרשים על זה שהקדים הרמב\"ם כאן תפלין של ראש לתפילין של יד (וכן בספר המצות שלו<sup data-n=\"164\">1</sup>, שמנה תפילין של ראש לפני תפילין של יד) — שהרי זה היפך סדרא דקרא, דבפסוק מפורש<sup data-n=\"165\">2</sup> \"וקשרתם לאות על ידך (והדר) והיו לטוטפות בין עיניך\"<sup data-n=\"166\">3</sup>, וכן הוא סדר הנחתן, ד\"כשהוא<sup data-n=\"167\">4</sup> מניח מניח של יד ואח\"כ מניח של ראש דכתיב וקשרתם לאות על ידך והדר והיו לטוטפות בין עיניך\" (וכנפסק ברמב\"ם<sup data-n=\"168\">5</sup>), ואמאי הקדים הרמב\"ם תפילין של ראש לתפילין של יד<sup data-n=\"169\">6</sup>?\nותמיהה זו היא לא רק במנין המצוות, אלא גם בגוף ההלכות עצמן, דבכל פעם מקדים הרמב\"ם הלכות תש\"ר להלכות תש\"י<sup data-n=\"170\">7</sup>, החל מריש הל' תפילין שכ' \"ארבע פרשיות אלו כו' ונקראין תפילין ומניחין אותן על הראש וקושרין אותן על היד\", וכן אח\"כ: בריש פרק ב' בכתיבת הפרשיות, מתחיל \"כיצד כותבין את ה­תפילין של ראש כו' (ואח\"כ) ושל יד כותבין אותם כו'\"; בפ\"ג<sup data-n=\"171\">8</sup> בעשיית הבתים — \"כיצד עושים תפילין של ראש כו'\",",[["164","1","מצוה יב­יג. וכן במנין המצות שלו בריש ס' היד (אבל בס' המדע — ירושלים, תשכ\"ד — הובאה גירסא מכת\"י, דשם מצות תש\"י באה לפני תש\"ר)."],["165","2","פרשתנו ו, ח. וכן הוא סדרם בשאר ג' פרשיות דתפילין (בא יג, ט. שם, טז. עקב יא, יח).\nולהעיר מפי' הזהר עה\"פ (שה\"ש ח, ו) שימני כחותם על לבך כחותם על זרועך — ד\"חותם על לבך\" הוא תש\"ר (דהיינו רצועות של ראש ד\"תליין על לבא\"), ו\"חותם על זרועך\" היא תפלה של יד (תקו\"ז תכ\"ב (סה, ב). לקו\"ת שה\"ש רד\"ה שימני (מה, א). וראה הנסמן שם) — תש\"ר קודם לתש\"י<sup data-n=\"e7\">*</sup>. ונת' הטעם לסדר זה ע\"ד החסידות באמרי בינה ש' התפילין פ\"ל. ע\"ש."],["166","3","בשו\"ת בנין שלמה (למהר\"ש כהן מ\"צ דווילנא) ס\"ד מתרץ ע\"פ המובא בסה\"ד (ד\"א תתקל) בוויכוח משה רבינו עם ר\"ת, דמשה אמר שצ\"ל קשירה בשל ראש, כי \"וקשרתם לאות\" קאי על של ראש \"שהם לאות\" — ונמצא, שבכתוב הקדים ש\"ר לש\"י. ומפרש שזוהי שיטת הרמב\"ם שהזכיר (פ\"ג סה\"א) רק קשר הרצועות בצורת דל\"ת שהוא של התש\"ר (ראה שם הי\"ג). וכן מדייק בלשונו במנין המצות שבריש ס' היד (מ\"ע יב) \"לקשור תפילין בראש\" (ע\"ש) — ולכן הקדימם גם הרמב\"ם.\nאבל נוסף שצ\"ע בעצם התי', הרי מובן גודל הדוחק לתרץ כן הקדמת הרמב\"ם השל ראש להש\"י בכ\"מ."],["167","4","מנחות לו, א."],["168","5","הל' תפילין פ\"ד ה\"ה."],["169","6","ולהעיר משאילתות פ' בא (שאילתא מה בתחלתה) \"דמחייבין דבי ישראל. . תפילין בראשי­הון (ואח\"כ) ותפילין בדרעיהון\"."],["170","7","משא\"כ בההלכות אודות שניהם יחד, פע­מים מקדים של ראש ולפעמים של יד (ראה פ\"ג ה\"ז (בין של ראש בין של יד). שם ה\"י (בין ש\"י בין ש\"ר). שם הי\"ד (בין ש\"ר בין ש\"י). הי\"ט (וראה שם הי\"ז). פ\"ד ה\"ג. שם ה\"ד. ואכ\"מ."],["171","8","ה\"ב."],["e7","*","אבל בתקו\"ז תי' א' (יח, א) מפרש \"על לבך\" על תש\"י ו\"על זרועך\" על תש\"ר. ע\"ש."]]],[1301870092,"ואח\"כ<sup data-n=\"172\">9</sup> \"וכיצד עושין תפילין של יד\"; וכן שם<sup data-n=\"173\">10</sup> לענין סדור הפרשיות (\"כיצד סדור הפרשיות, בתפלה של ראש מכניס פרשה אחרונה כו' (ואח\"כ) תפלה של יד כותבם בארבעה דפין כו'\"), אורך הרצועות (\"ואורך רצועה של ראש כו' ואורך רצו­עה של יד כו'\"<sup data-n=\"174\">11</sup>) ואופן קשירת הרצועות בבתים (\"ומכניס רצועה של ראש בתובר שלה כו' וכן בשל יד קושר כו'\"<sup data-n=\"175\">12</sup>); בריש פ\"ד במקום הנחתם — \"היכן מניחין תפילין של ראש מניחין אותן כו' ושל יד קושר אותה כו'\"; וכן שם<sup data-n=\"176\">13</sup> לענין ברכת תפילין — \"וכיצד מברכין על של ראש מברך כו' ועל של יד מברך כו'\"<sup data-n=\"177\">14</sup>.\nב. והנה יש שביארו<sup data-n=\"178\">15</sup> טעמו של ה­רמב\"ם משום דשל ראש קדושתו חמורה משל יד, שלכן \"תפלה של ראש אין עושין אותה של יד. . לפי שאין מורידין מקדושה חמורה לקדושה קלה\"<sup data-n=\"179\">16</sup>, ובאמת מטעם זה גם הנחת השל ראש הי' צ\"ל קודם להנחת השל יד (שהרי \"כל ה­מקודש מחבירו קודם את חבירו\"<sup data-n=\"180\">17</sup>), אלא שגזירת הכתוב היא<sup data-n=\"181\">18</sup>, \"דכתיב<sup data-n=\"167\">4</sup> וקשרתם לאות על ידך והדר והיו לטוטפות בין עיניך\".\nויש להוסיף על דבריהם ממ\"ש ה­ב\"ח<sup data-n=\"183\">19</sup> בביאור לשון הטור<sup data-n=\"184\">20</sup> שהקדים הל­כות כתיבת תפילין של ראש לכתיבת השל יד, שס\"ל להטור ש\"השל ראש מפני שקדושתן חמורה משל יד. . על כן חייב לכתוב של ראש תחלה ואח\"כ של יד\". ועפ\"ז י\"ל שהרמב\"ם ס\"ל שבכל מעשי תפילין (לבד הנחתם) יש להקדים של ראש לשל יד כיון שקדושתן חמורה משל יד.\nאבל לכאורה קשה לפרש כן דעת הרמב\"ם, שהרי נקט סדר זה לא רק גבי כתיבת הפרשיות ועשיית הבתים וכו', אלא גם לענין הנחתם וברכתם, שבזה גזרה תורה ששל יד קודמת, ואיך יתכן שברמב\"ם מקדים בזה השל ראש להשל יד, היפך סדרם בכתוב והיפך אופן קיום המצוה בפועל?\nוגם לענין סדרם במנין המצות כבר כתבו<sup data-n=\"185\">21</sup> שזהו \"טעם קלוש\", כי מה ענין קדושת וחומר המצוות לסדרם? דלא מ­צינו שהסדר דמנין המצות יהי' בהתאם לסדר מעלת קדושתן וחומרתן, וכמו ב­הלכות אלו גופא, שהרמב\"ם מצרף יחד הל' תפילין והל' מזוזה והל' ספר תורה, ונקטם בסדר זה, אע\"פ שקדושת ס\"ת",[["172","9","שם ה\"ד."],["173","10","שם הלכה ה­ו."],["174","11","שם הי\"ב."],["175","12","שם הי\"ג."],["176","13","ה\"ד."],["177","14","אבל זה שהקדים הרמב\"ם תש\"ר בסוף הל' תפילין (פ\"ד הכ\"ה) \"שכל זמן שהתפילין בראשו. . ועל זרועו הוא עניו כו'\" — מובן, כי בא בהמשך למ\"ש ד\"קדושת תפילין קדושתן גדולה היא\", וקדושת ש\"ר גדולה מש\"י (כדלקמן ס\"ב); ומטעם זה גופא, פעולת התפילין על האדם שיהי' עניו כו', היא ביותר ע\"י תש\"ר. ולכן גם בהא דהתפילין פועלים על האדם \"שלא יחטא\" תש\"ר קודם (רמב\"ם סוף הל' מזוזה (ספ\"ו), ממנחות מג, ב)."],["178","15","חמדת ישראל (להר' מאיר דן פלאצקי) קונטרס נר מצוה מי\"ב­יג (בשם אחרונים). ועוד."],["179","16","רמב\"ם פ\"ג הי\"ז, ממנחות לד, ב."],["180","17","זבחים פט, א (במשנה)."],["181","18","ראה גם העמק שאלה לשאילתות שם אות ג."],["167","4","מנחות לו, א."],["183","19","לטואו\"ח ר\"ס לב. וראה גם עטרת זקנים לשו\"ע או\"ח שם ס\"א. באר היטב שם סק\"ג מ­האריז\"ל. שו\"ע אדה\"ז שם."],["184","20","שם."],["185","21","בהגהות עמק המלך לרמב\"ם כאן."]]],[1301870093,"חמורה מקדושת מזוזה<sup data-n=\"186\">22</sup> ותפילין<sup data-n=\"187\">23</sup>.\nיש שכתבו<sup data-n=\"188\">24</sup> שהרמב\"ם נקט בסדר זה \"להורות הדין שכתב בפרק ד' הלכה ד' תפלה של יד אינו מעכב של ראש אפילו אין לו של יד רק של ראש מניח של ראש כדכתב מרן הכ\"מ שם ולכך התחיל בשל ראש לומר אם אין לו אלא של ראש מניח אותה לבדה. . גם בברכה מתחיל שם בשל ראש ג\"כ לכוונה זו\".\nאבל נוסף ע\"ז שלפי זה הי' מספיק לנקוט סדר זה גבי מקום הנחתן וברכתן ואין זה טעם לנקוט סדר זה גם במנין המצוות (וכן בכתיבת הפרשיות ועשיית התפילין כו'), הרי עוד זאת, כיון שה­רמב\"ם כתב בפירוש ד\"של יד אינה מעכבת של ראש מפני שהן שתי מצות זו לעצמה וזו לעצמה\", ל\"ל גם לרמז דין זה ע\"י הקדמת של ראש לשל יד (היפך סדרם בקרא והיפך סדר החיוב לכת­חילה).\nג. ויש לומר הביאור בזה, ע\"פ מ\"ש בצפנת פענח על הרמב\"ם<sup data-n=\"189\">25</sup>, שיש הבדל בין תפילין של יד לתפילין של ראש, \"דגבי תפילין של יד המצוה היא [מעשה] ההנחה או הקשירה. . אבל בשל ראש המצוה שיהי' מונח\" [וא' הנפק\"מ למע­שה, דהא שאמרו<sup data-n=\"167\">4</sup> דאם הניחם קודם אור הבוקר \"כשיגיע זמנן ממשמש בהן ומברך עליהן\", ד\"זה רק אשל יד. . דשם הנחה הוא מצוה (ולכן צריך למשמש בהן) מש­א\"כ בשל ראש דהמצוה שיהי' מונח\"<sup data-n=\"191\">26</sup>].\nויש לומר, שיסודו בלשון הכתוב עצמו, \"וקשרתם לאות על ידיך והיו ל­טוטפות בין עיניך\", דגבי של יד נקט הכתוב מעשה הקשירה, ואילו בתפילין של ראש נאמר \"והיו\". וכן מדייק ה­רמב\"ם במנין המצות בריש הל' תפילין (כנ\"ל ס\"א) — \"להיות<sup data-n=\"192\">27</sup> תפילין על הראש. . לקשרם על היד\"<sup data-n=\"193\">28</sup>.",[["186","22","רמב\"ם שם (הל' מזוזה) פ\"ה סה\"א."],["187","23","ב\"י לטוא\"ח סל\"ב ד\"ה ואם עבד. שו\"ע אדה\"ז שם סי\"א (ושם סמ\"ב ס\"ו)."],["188","24","הגהות טורי אבן לרמב\"ם כאן."],["189","25","להל' תפילין פ\"ד ה\"ד. מהד\"ת (ע, ד. פט, א). — וראה גם גליוני הש\"ס (להר\"י ענגל) לירו­שלמי זרעים כרך א אות מד (בדעת הירושלמי)."],["167","4","מנחות לו, א."],["191","26","וראה צפע\"נ בהשמטות שבסו\"ס הפלאה (נה, ב), שבזה א\"ש ל' הש\"ס (ביצה טו, א) \"הי' בא בדרך ותפילין בראשו ושקעה עליו חמה מניח ידו עליהם כו'\" — \"דנקט שם רק ותפילין בראשו. . דרק בש\"ר אסור ולא בש\"י\" — כי \"מה דהמצוה היא ביום, זה אסור בלילה, ובתפילין ש\"י המצוה היא רק ההנחה זה דוקא אסור [משא\"כ כשמונחים עליו אין איסור], משא\"כ בשל ראש דאסור גם אם מונחין כיון דהמצוה היא כן\"."],["192","27","וכ\"ה ל' הרמב\"ם במנין המצות שעל סדר הלכות (בריש ס' היד). וצע\"ק בלשונו במנין המצות שלו בריש ס' היד (מ\"ע יב) \"לקשור תפילין בראש\" (וראה לעיל הערה 3), ובסהמ\"צ לפנינו (מ\"ע יב) \"להניח תפילין של ראש\" (וכ\"ה במ\"ע יג בתש\"י). ובתרגום קאפח (מ\"ע יב­יג) \"במעשה תפלין\" (וראה הוצאת העליר שם בהערה). ואכ\"מ."],["193","28","וראה דרישה לטואו\"ח סכ\"ה (אות א) בשם המהר\"ל, בטעם ש\"תקנו על של ראש \"על מצות\" ועל של יד \"להניח\", משום דבשל יד כתיב וקשר­תם לאות על ידך וקשירה והנחה חדא היא<sup data-n=\"e8\">*</sup> לכן מברכין להניח אבל בשל ראש כתוב והיו לטוטפות הרי שלא נזכר בה אלא לשון ההווי' לפיכך שייך בה על מצות תפילין\". ואולי אין כוונתו רק ללשון לבד, אלא שזהו חילוק באופן מצותם, כבפנים."],["e8","*","בב\"ח שם (ד\"ה ויניח של יד), דהא ש\"תקנו ברכה להניח ולא לקשור תפילין כדכתיב וקשרתם. . דעיקר מצות תפילין הוא שיהיו מונחים עליו כל היום ואם הי' מברך לקשור הווה משמע [דבמה] שקושר תפילין על ידו ועל ראשו רגע א' ואח\"כ מסירן יוצא י\"ח לכך תקנו להניח דמשמע שיהו מונחים עליו כו'\".\nאבל נוסף לזה די\"ל ד\"קשירה והנחה חדא היא\" (כדרישה שבפנים) — ראה צפע\"נ (להל' תפילין שם), ד\"גם בשל יד מברך להניח בקמץ ולא בפתח משום דזה גורם לשל ראש שיהי' מונח משום דכל שבין עיניך יהא שנים\" (כדלקמן ב­פנים)."]]],[1301870094,"ועפ\"ז מובן בפשטות הטעם שמנה הרמב\"ם תש\"ר ותש\"י לשתי מצות במנין תרי\"ג. דלכאורה, אע\"פ שאינן מעכבות זו את זו, מאי שנא מציצית, דאע\"פ שלבן ותכלת אינן מעכבין זא\"ז מ\"מ הם מצוה אחת כיון ש\"הענין אחד\"<sup data-n=\"194\">29</sup> (כמו שהקשה הרמב\"ן<sup data-n=\"195\">30</sup>)? וע\"פ הנ\"ל מתורץ, כי תפילין של יד ותפילין של ראש חלוקים בעצם גדרם, דשל יד מצותה מעשה הקשירה, ואילו בשל ראש המצוה היא שיהיו מו­נחים על הראש.\nוהנה החילוק הנ\"ל בין תש\"י ותש\"ר הוא לא רק בתוכן המצוה (אם הוא הפועל או הנפעל), אלא גם בזמן המצוה, דכיון שבשל יד המצוה היא הקשירה או ההנחה נמצא שקיום המצוה הוא רק ברגע של מעשה הקשירה או ההנחה<sup data-n=\"196\">31</sup>, משא\"כ ב­תפילין של ראש שהמצוה היא שיהיו מונחים על ראשו, נמצא, \"דכל רגע ורגע שהוא לבוש מקיים מצוה\"<sup data-n=\"197\">32</sup> [וכפי שמביא בצפע\"נ<sup data-n=\"198\">33</sup> ע\"ז מחז\"ל<sup data-n=\"199\">34</sup> עה\"פ<sup data-n=\"200\">35</sup> \"בכל עת גו' ושמן על ראשך אל יחסר\" — \"אלו תפילין\", דהיינו תפילין של ראש<sup data-n=\"201\">36</sup> (\"על ראשך\"), שבהם דוקא נאמר \"בכל עת. . אל יחסר\", שמצותן בכל רגע ורגע<sup data-n=\"202\">37</sup>].\nואין זה סתירה למ\"ש הרמב\"ם<sup data-n=\"203\">38</sup> \"שמצותן ללבשן כל היום\", שזה קאי גם על השל יד — כי זה שצריך להיות לבוש גם בשל יד כל הזמן הוא רק לפי ש\"כל זמן שבין עיניך יהו שתים\"<sup data-n=\"167\">4</sup> (כדאיתא בגמרא<sup data-n=\"167\">4</sup> שזהו הטעם ד\"כשהוא חולץ חולץ של ראש ואח\"כ חולץ של יד\"), היינו שאינו מצות השל יד, אלא פרט בקיום מצות של ראש, שיש דין מיוחד בתש\"ר ש\"כל זמן שבין עיניך יהו שתים\"<sup data-n=\"206\">39</sup>.\n[ועפ\"ז מתרץ בצפע\"נ<sup data-n=\"207\">40</sup> הא דכתבו התוס'<sup data-n=\"208\">41</sup> גבי \"סח בין תפילה לתפילה עבירה היא בידו\", דזהו רק בתפילין (ולא בשוחט עופות הרבה וסח בין עוף לעוף) \"שמצוה אחת הן\"<sup data-n=\"209\">42</sup> — דלכאורה צ\"ב, שהרי מפורש בש\"ס<sup data-n=\"210\">43</sup> שהן שתי מצות?",[["194","29","ל' הרמב\"ם בסהמ\"צ שורש יא בסופו."],["195","30","בהשגותיו על סהמ\"צ שם [בדפוסי סהמ\"צ הנפוצים הוא בהשגות הרמב\"ן על שורש ט. אבל בדפוסים אלו יש השמטות בל' הרמב\"ן. והשגה זו שייכת לשורש י\"א — ראה סהמ\"צ הוצאת העליר. וכן סהמ\"צ עם השגות הרמב\"ן (ירושלים תשמ\"א)]."],["196","31","דלא כב\"ח הנ\"ל הערה 28 (בשוה\"ג)."],["197","32","ל' הצפע\"נ במהד\"ת (ע, ד. ועד\"ז שם פט, א). וראה גם בצפע\"נ להל' תפילין שם."],["198","33","להל' תפילין שם. וכן במהד\"ת שם."],["199","34","שבת קנג, א."],["200","35","קהלת ט, ח."],["201","36","כפרש\"י שבת שם."],["202","37","וראה צפע\"נ מהד\"ת (צא, א) המעלה ד\"אל יחסר\" דתפילין על \"בכל עת\" דציצית, אף שגם ציצית הוי \"מצוה נמשכת\"."],["203","38","פ\"ד הכ\"ו."],["167","4","מנחות לו, א."],["167","4","מנחות לו, א."],["206","39","וראה בארוכה לקו\"ש חי\"ט (ע' 47 ואילך) בביאור פלוגתת הש\"ס והמכילתא בזה. ואכ\"מ."],["207","40","הל' תפילין שם."],["208","41","מנחות לו, א ד\"ה סח."],["209","42","וראה שו\"ע אדה\"ז סכ\"ה סכ\"ב (מבעל המאור (הובא בר\"ן) סוף ר\"ה. ב\"י לטאו\"ח שם) \"ששתיהן נחשבים להוי' ועשי' אחת\"."],["210","43","שם מד, א."]]],[1301870095,"אלא \"דכאן ר\"ל על ההנחה ושם ר\"ל שיהי' מונח\", כלומר: זה שנחשבות לשתי מצות היינו לפי שתש\"י חלוקים מתש\"ר כי מצותן היא מעשה ההנחה (או הקשי­רה) כנ\"ל; משא\"כ לענין \"שיהי' מונח\" (היינו המצוה שתפילין יהיו מונחים עליו כל הזמן) ה\"ה מצוה אחת, כי בזה תש\"י הם רק פרט במצות השל ראש, כנ\"ל].\nד. עפ\"י הנ\"ל יש לבאר הטעם ש­הרמב\"ם הקדים בכל פעם תפילין של ראש לשל יד — דקדימה זו היא בהתאם לתוכנו של כללות ספר אהבה, שכולל (בלשון הרמב\"ם<sup data-n=\"211\">44</sup>) \"המצות שהם תדירות שנצטוינו בהם כדי לאהוב המקום ולזכרו תמיד\". ובענין זה הרי העיקר הוא המצוה דתפילין של ראש שהיא מצוה תמידית, שבכל רגע שהוא לבוש בהם מקיים מצוה (משא\"כ בשל יד שמצותן היא רק מעשה הקשירה, וזה שצ\"ל מונחין עליו תמיד הוא רק פרט במצות תש\"ר כנ\"ל)<sup data-n=\"212\">45</sup>.\nויש לומר עוד, שסדר זה דקדימת תש\"ר לתש\"י, הוא בהתאם ובהמשך לסד­רן של כל המצוות דספר אהבה:\nע\"פ דברי הרמב\"ם הנ\"ל בתוכן ס' אהבה, נראה שסדר המצות בספר אהבה הוא (בעיקר) לפי אופן התדירות של עשיית המצוה (ע\"ד \"כל<sup data-n=\"180\">17</sup> התדיר מחבירו קודם את חבירו\"):\nבתחלתו סידר הל' ק\"ש והל' תפלה — דחיוב ק\"ש הוא פעמיים בכל יום<sup data-n=\"214\">46</sup> וחיוב תפלה (מה\"ת) הוא \"להתפלל בכל יום\"<sup data-n=\"215\">47</sup> (אבל לא פעמיים כבק\"ש); ולאחרי ה­מצוות שבדיבור שחייבים בהם בכל יום — מונה המצוות שבמעשה, החל מהל' תפילין, שהנחתם היא פעם אחת ביום<sup data-n=\"216\">48</sup> [ובהמשך לתפילין באות הל' מזוזה וספר תורה מפני שייכותן בתוכנן, ובפרט שכו\"כ הלכות משותפות להן<sup data-n=\"217\">49</sup>], ואח\"כ הל' ציצית שחיוב ציצית אינו כתפילין שהרי אין המצוה אלא רק בכסות בת ד' כנפות<sup data-n=\"218\">50</sup>; ואח\"כ הל' ברכות שמה\"ת חיי­בים לברך רק \"אחר אכילה\"<sup data-n=\"219\">51</sup> ואף גם זאת \"אינו חייב מן התורה אלא אם כן שבע\"<sup data-n=\"220\">52</sup> [ויש לומר, בטעם הקדמת ציצית לברכות, כי בציצית מפורש בתורה ש­כוונת המצוה היא \"וזכרתם את כל מצות ה' גו' למען תזכרו גו'\"<sup data-n=\"221\">53</sup>, שזהו תוכן ספר אהבה כנ\"ל, \"לזכרו תמיד\", משא\"כ בבר­כות שלא מצינו כזאת מפורש בתורה<sup data-n=\"222\">54</sup>, ובפרט שחיוב ברכות מה\"ת אינו הכרחי",[["211","44","במנין המצות על סדר ההלכות שבריש ס' היד."],["212","45","וראה מנחות (מג, ב) \"חביבין ישראל שסיבבן הקב\"ה במצות תפילין בראשיהן ותפילין בזרועותיהן וציצית. . ומזוזה. . נזכר במילה כו'\" — דמצות אלו הן מצוות נמשכות כו', ולכן מקדים ש\"ר לש\"י, כי בענין זה הוא העיקר, כבפנים."],["180","17","זבחים פט, א (במשנה)."],["214","46","רמב\"ם ריש הל' ק\"ש (ובכותרת שם)."],["215","47","ל' הרמב\"ם ריש הל' תפלה. ובכותרת שם \"לעבוד את ה' בכל יום בתפלה\". ונת' במ\"א."],["216","48","דאף את\"ל דמ\"ש הרמב\"ם \"מצותן ללבשן כל היום\" הוא חיוב מה\"ת (וכבר האריכו בנ\"כ. ואכ\"מ), מעשה הנחתם הוא פ\"א."],["217","49","כרוב ההלכות בהל' תפילין פ\"א."],["218","50","ראה רמב\"ם הל' ציצית רפ\"ג. ושם הי\"א \"שאין אדם מחוייב כו'\"."],["219","51","ל' הרמב\"ם בכותרת להל' ברכות, וכן שם ה\"א \"אחר אכילת מזון\"."],["220","52","שם ה\"א."],["221","53","שלח טו, לט­מ. וראה רמב\"ם סוף הל' ציצית."],["222","54","ורק חכמים תקנו כמה ברכות \"כדי לזכור את הבורא תמיד\" (רמב\"ם הל' ברכות פ\"א ה\"ג. וראה שם ספ\"י וספי\"א)."]]],[1301870096,"בכל יום<sup data-n=\"223\">55</sup> כנ\"ל]; ומסיים במצות מילה שמעשה המצוה הוא רק פעם אחת ב­חיים.\nולכן הקדים הרמב\"ם תש\"ר לתש\"י, כי תש\"ר הוא יותר \"תדיר\", כיון שקיום המצוה דתש\"ר הוא בכל רגע ורגע, ואילו קיום מצות תש\"י אינו אלא בעת הקשירה.\nה. ויש להמתיק הענין יותר, ע\"פ דיוק לשון אדמו\"ר הזקן בשולחנו<sup data-n=\"224\">56</sup> בטעם הדיעות ש\"תקנו חכמים לברך עוד ברכה אחרת על תפילין של ראש\" (\"על מצות תפילין\") — \"לפי שהיא חשובה והיא עיקר המצוה\", ומקורו בתוס'<sup data-n=\"225\">57</sup>. אבל לשון ה­תוס' היא \"שהיא גמר מצוה ועיקר וכו'\", ובזה יש לפרש דלשון \"עיקר\" היא ע\"ד המעלה ד\"גמר מצוה\" [וברא\"ש<sup data-n=\"226\">58</sup> נקט רק \"שהיא גמר המצוה\"]. אבל מזה שרבינו הזקן השמיט הלשון \"גמר מצוה\" וכתב רק \"שהיא חשובה והיא עיקר המצוה\", משמע שס\"ל, שתש\"ר היא \"עיקר המצוה\" בכלל (בחשיבות).\nוע\"פ דברי הצפע\"נ אתי בפשטות, כי עיקר מצות תפילין היא השל ראש, שהיא מצוה תמידית כל זמן שהוא לבוש בהם, משא\"כ מצות השל יד היא רק בשעת מעשה הקשירה (או ההנחה), ואילו אח\"כ לבישת הש\"י היא רק פרט וטפל להשל ראש.\nויש לומר, דאע\"פ שלענין ברכה ס\"ל להרמב\"ם<sup data-n=\"227\">59</sup> שלא תיקנו ברכה אחרת על השל ראש (ורק כשסח בין תפילה ל­תפילה מברך על של ראש \"על מצות תפילין\"), מ\"מ, לענין קיום המצוה עצמו ס\"ל ג\"כ שתפילין של ראש \"היא עיקר המצוה\".\nועפ\"ז יומתק עוד יותר טעם הקדמת תש\"ר לתש\"י, שאין זה רק מחמת התמי­דיות והתדירות שבתש\"ר, אלא גם לפי ש\"היא עיקר המצוה\" (דתפילין).\nו. ויש להוסיף בביאור ההבדל הנ\"ל בין תש\"י ותש\"ר — ע\"פ פנימיות הענ­ינים:\nהחילוק הפנימי בין תש\"י ותש\"ר הוא, דתש\"י שמניחים על הזרוע כנגד הלב מו­רה על עבודת המדות, לשעבד להקב\"ה \"הלב שהוא עיקר התאוות והמחשבות\", ותש\"ר \"על הראש כנגד המוח\" — לשעבד \"הנשמה שהיא במוח\" להקב\"ה<sup data-n=\"228\">60</sup>.\nוזהו גם הטעם הפנימי דהפרשיות ד­תש\"י הם בבית א', ואילו בתש\"ר, ד' הפר­שיות מונחות כאו\"א בבית בפ\"ע, כי ענינו של המוח והשכל הוא לפרט כל דבר לפר­טים, משא\"כ רגש המדות אין בו התחל­קות פרטים, דרגש המדות מצד עצמו הוא למעלה ממדידה והגבלה (ורק מפני השפעת השכל על המדות, הרי גם המדות הם במדידה והגבלה), ולכן תש\"ר הם בד' בתים בפ\"ע, ותש\"י כל ד' הפרשיות הם בבית א'.\nועפ\"ז יש לבאר החילוק הנ\"ל בין",[["223","55","ולהעיר שגבי ציצית לא כ' הרמב\"ם התנאי דכסות בת ד' כנפות בכותרת, וגם בפנים ההלכות כתבו רק בפ\"ג. וכן להעיר שבהל' ברכות פי\"א ה\"ב לא נקט ציצית לדוגמא על מצות שאינן חובה \"אלא דומין לרשות\"."],["224","56","או\"ח סכ\"ה סי\"ד."],["225","57","ברכות ס, ב ד\"ה אשר קדשנו."],["226","58","פסחים פ\"א ס\"י (קרוב לסופו) — כצויין במ\"מ עה\"ג."],["227","59","פ\"ד ה\"ה. כדעת הרי\"ף (בהל' תפילין שלו). ועוד."],["228","60","שו\"ע או\"ח סכ\"ה ס\"ה. שו\"ע אדה\"ז שם סי\"א בשינוי ל' קצת."]]],[1301870097,"תש\"י ותש\"ר (דתש\"י מצותן רק מעשה הקשירה, ואילו תש\"ר היא מצוה תמידית, \"שיהי' מונח\") — בפנימיות הענינים:\nבנוגע למדות שבלב, הרי אין לבו של אדם (בינוני — שהיא מדת כל אדם) ב­רשותו \"להפך לבו מתאוות עוה\"ז לאה­בת ה' באמת\"<sup data-n=\"229\">61</sup> (דצדיקים דוקא לבם ברשותם<sup data-n=\"229\">61</sup>), ולכן אין מצות תש\"י — דהיינו שעבוד תאוות הלב — \"שיהי' מונח\", כ\"א רק מעשה הקשירה, זאת או­מרת, דאע\"פ שאין האדם יכול להפוך את לבו מתאוות לבו לאהבת ה' באמת, שיהי' משועבד בתמידיות לאהבת ה', מ\"מ עליו לקשור את לבו, בדרך אתכפיא, לשלוט על עצמו שלא להוציא תאוותו מן הכח אל הפועל<sup data-n=\"231\">62</sup>.\nמשא\"כ בנוגע למוחו, הרי \"מוחו בר­שותו\"<sup data-n=\"229\">61</sup> של כאו\"א מישראל, ש\"יכול להתבונן בו בכל אשר יחפוץ\"<sup data-n=\"229\">61</sup>, ולכן מצות תש\"ר היא \"שיהי' מונח\", היינו שיהי' משועבד באופן תמידי לעבודתו יתברך.\nאבל אעפ\"כ, כדי לקיים מצות תש\"ר צריכים גם לענין דתש\"י, \"כל זמן שבין עיניך יהו שתים\", כי כדי שעבודת המוח תהי' כדבעי, מוכרח שגם לבו יהי' \"קשור\" ומשועבד (עכ\"פ בדרך אתכפיא) במשך כל היום, כמובן בפשטות, שאם לא יהי' שולט על תאוות לבו, הרי זה יבלבל לעבודת המוח כו'.\nז. ובעומק יותר יש לומר, שהחילוק בין שני הענינים בתש\"י ותש\"ר — דלגבי מעשה ההנחה הם שתי מצוות, ולענין \"שיהי' מונח\" הם כמו מצוה אחת (כנ\"ל סעיף ג) — הוא משום שהן שתי דרגות בעבודת ה'<sup data-n=\"234\">63</sup>:\nמבואר בכ\"מ<sup data-n=\"235\">64</sup>, שיש ב' דרגות במוחין — חיצוניות המוחין ופנימיות המוחין, שההבדל ביניהם הוא: אע\"פ שהמוח שליט על הלב<sup data-n=\"236\">65</sup>, וההתבוננות בגדולת ה' מולידה בלב אהבת ה' ויראתו (כמבואר ברמב\"ם<sup data-n=\"237\">66</sup>), יש חילוק בין חיצוניות השכל ופנימיות השכל באופן השפעתן על מדות שבלב:\nהשפעת חיצוניות השכל על המדות היא בדרך פעולה, דלאחרי שהאדם מבין ומשיג בשכלו גדלות ה' (\"וידעת\"<sup data-n=\"238\">67</sup>) צ\"ל עבודה נוספת לפעול הולדת מדה שבלב (\"והשבות אל לבבך\"<sup data-n=\"238\">67</sup>), שזה בא ע\"י התעסקות מיוחדת מצד השכל שבראש, להתלבש ב\"עולם המדות\" ולעורר רגש שבלב. ומובן, שלגבי דרגת השכל עצמו ה\"ז ירידה;\nמשא\"כ השפעת פנימיות השכל, ה­קשורה עם עצם הנפש, הרי היא בכל חלקי האדם בדרך ממילא, כי השגת איזה דבר מצד פנימיות השכל היא באופן שהאדם נדבק בזה בכל מציאותו, באופן שהמדות נגררות בדרך ממילא אחרי ה­השגה.\nוזהו החילוק בין שני האופנים בתש\"י ותש\"ר:",[["229","61","תניא רפי\"ז."],["229","61","תניא רפי\"ז."],["231","62","ראה בארוכה תניא פי\"ב ואילך."],["229","61","תניא רפי\"ז."],["229","61","תניא רפי\"ז."],["234","63","בהבא לקמן להעיר גם מלקו\"ש ח\"ט ע' 56 ואילך."],["235","64","ראה קונטרס העבודה ע' 7­6. ד\"ה ואל מי תדמיוני תרס\"ה. ד\"ה לך אמר לבי עת\"ר (ע' יג ואילך). ד\"ה כי חק לישראל השי\"ת פי\"ג. ועוד."],["236","65","תניא פי\"ב (יז, רע\"א), מרע\"מ פ' פינחס."],["237","66","הל' יסוה\"ת רפ\"ב."],["238","67","פרשתנו ד, לט."],["238","67","פרשתנו ד, לט."]]],[1301870098,"בתחילת העבודה, כשעבודת השכל היא רק בדרגא של חיצוניות, אזי תש\"י ותש\"ר הם שתי מצוות, היינו שהן שתי עבודות שונות, עבודת הלב ועבודת המוח, וחלוקות גם במעלתן, ששעבוד המוח לעבודת ה' הוא באופן תמידי, \"שיהי' מונח\", ואילו התעוררות המדות היא בדרך פעולה, שע\"י המוח הרי הוא מקשר את לבו לה';\nמשא\"כ כאשר מתעלה בעבודתו, עד שעבודתו היא מצד פנימיות המוחין, הרי אז המדות נגררות בדרך ממילא אחרי השכל (כנ\"ל), ואז תש\"י ותש\"ר הם מצוה אחת, והמדות נטפלות לעבודת המוחין ונגררות אחרי'<sup data-n=\"240\">68</sup>, \"כל זמן שבין עיניך יהו שתים\".\n<span data-k=\"q\">(משיחות ש\"פ תרומה תשמ\"ז; יו\"ד שבט תשכ\"ט)</span>",[["240","68","כי אז המדות הן בדרגת המוחין (ראה במקומות שנסמנו בהערה 64)."]]],[1301870099,"<h3>תצא (תנש\"א)</h3>\nא. כתב הרמב\"ם בריש הל' אישות: \"קודם מתן תורה הי' אדם פוגע אשה בשוק אם רצה הוא והיא לישא אותה מכניסה לתוך ביתו ובועלה בינו לבין עצמו ותהי' לו לאשה. כיון שנתנה תורה נצטוו ישראל שאם ירצה האיש לישא אשה יקנה אותה תחלה בפני עדים ואח\"כ תהי' לו לאשה שנאמר<sup data-n=\"241\">1</sup> כי יקח איש אשה ובא אלי'\".\nוממשיך בהלכות שלאח\"ז<sup data-n=\"242\">2</sup> ש\"ליקוחין אלו מצות עשה כו' הן הנקראין קידושין או אירוסין בכ\"מ כו' וכיון שנקנית האשה ונעשית מקודשת אע\"פ שלא נבעלה ולא נכנסה לבית בעלה הרי היא אשת איש כו' ואם רצה לגרש צריכה גט\".\nולכאורה צ\"ע, למה הקדים הרמב\"ם כאן תיאור גדר האישות שקודם מ\"ת, ולא התחיל בדין אישות שלאחר מ\"ת: \"אם ירצה האיש לישא אשה צריך לקנות אותה תחלה כו' ואח\"כ תהי' לו לאשה כו'\"<sup data-n=\"243\">3</sup>?\nוהנה בפשטות, הנפקותא להלכה ב­זה\"ז היא לגבי בן נח, וכמ\"ש במגיד משנה כאן \"זה פשוט ומבואר בהרבה מקומות דלעכו\"ם בייחוד בעלמא<sup data-n=\"244\">4</sup> הויא אשתו וכיון שבא עלי' לשם אישות הויא לה אשת איש שחבירו עכו\"ם חייב עלי' כנזכר פרק ט'<sup data-n=\"245\">5</sup> מהלכות מלכים ומלחמו­תיהן\".\nאבל לכאורה אין זה טעם להביא ענין זה בריש הל' אישות, שבהן מדובר רק אודות דין אישות דישראל, והי' לו לה­ביאו בהל' מלכים<sup data-n=\"246\">6</sup>, ששם מבאר דיני בני נח.\nוכמו בדיני גירושין, דבריש הל' גירו­שין כ' הרמב\"ם רק דין גירושין דישראל (מבלי להקדים אופן הגירושין לפני מ\"ת) — \"אין האשה מתגרשת אלא בכתב שיגיע לה וכתב זה הוא הנקרא גט. . זה<sup data-n=\"247\">7</sup> שנאמר בתורה<sup data-n=\"248\">8</sup> ושלחה מביתו אין עניינו שלא יגמרו גירושי' עד שתצא מביתו אלא כשמגיע גט לידה גמרו גירושי' ואע\"פ שעדיין היא בביתו\"; ורק בהל' מלכים<sup data-n=\"249\">9</sup> מבאר דין גירושין דב\"נ — \"מאי­מתי תהי' אשת חבירו כגרושה שלנו מש­יוציאנה מביתו וישלחנה לעצמה או",[["241","1","פרשתנו כב, יג. ובסהמ\"צ (מ\"ע ריג) מביא הכתוב (שם כד, א) \"כי יקח גו' ובעלה\". וראה רמב\"ם הוצאת פרענקל בשינויי נוסחאות. ואכ\"מ."],["242","2","ה\"ב וג'."],["243","3","וכמו שהקשה הכס\"מ בדברי הרמב\"ם לקמן ה\"ד גבי איסור \"קדשה\", שמקדים \"קודם מ\"ת הי' אדם פוגע אשה בשוק כו' משנתנה התורה נאסרה הקדשה\". — וראה לקמן סוף סעיף ו."],["244","4","ראה חי' הרש\"ש לרמב\"ם כאן, דעכו\"ם אינו קונה אלא בביאה (וראה לקמן סעיף ה), \"ואולי ביחוד דקאמר ר\"ל בלא עדים\"."],["245","5","ה\"ז. — אלא ששם החידוש להיפך, שאינו חייב ע\"י אירוסין או כניסה לחופה אלא רק \"אחר שנבעלה לבעלה\", ואילו כאן החידוש ד\"בייחוד בעלמא (גם בלי אירוסין או חופה) הויא אשתו\"."],["246","6","ובפרט שענין זה ד\"בייחוד בעלמא הויא אשתו\" אינו מפורש בהל' מלכים שם, כנ\"ל בהערה הקודמת."],["247","7","שם ה\"ה."],["248","8","פרשתנו כד, ב."],["249","9","שם ה\"ח."]]],[1301870100,"משתצא היא מתחת רשותו ותלך לה שאין להם גירושין בכתב\".\nוצ\"ל, שהקדמה זו בענין האישות ד­קודם מ\"ת נוגע לדין אישות דישראל (שלאחר מ\"ת).\nב. לכאורה הי' אפשר לבאר זה ע\"פ משנ\"ת במ\"א<sup data-n=\"250\">10</sup>, שקודם מ\"ת לא הי' שייך כל ענין \"ליקוחין\" אלו דלאחר מ\"ת. כי ענין \"אשת איש\" (בפשטות) אינו שהאשה קנוי' לבעל כחפץ הנקנה לאדם, אלא שאשה זו ואיש זה הם כמו מציאות אחת שנעשית ע\"י זוג, ע\"ד לשון הכתוב<sup data-n=\"251\">11</sup> \"ודבק באשתו\". ולכן, לולא ציווי התורה שהאדם \"יקנה אותה תחלה. . ואח\"כ תהי' לו לאשה\", אין מקום לומר שיש \"ליקוחין\" שבכחם לפעול שיחול על ה­אשה שם \"אשת איש\" כאשר עדיין אינה \"אשתו\" במובן הפשוט, כי \"לא נבעלה ו(אפילו) לא נכנסה לבית בעלה\", ורק ציווי התורה עושה מציאות של \"ליקוחין\" העושה את האשה לאשת איש.\nויש לומר שנפק\"מ גם בזמן הזה בב\"נ, שב\"נ הקונה אשה בא' מדרכי הקנינים לשם אירוסין כו' — לא נפעל כלום ע\"י מעשה זה ועדיין היא פנוי' כמו לפני מעשה הקנין ממש<sup data-n=\"252\">12</sup>. וכדברי הרמב\"ם בהל' מלכים<sup data-n=\"253\">13</sup> ש\"אין ב\"נ חייב על אשת חבירו עד כו' אחר שנבעלה לבעלה, אבל מאורסה או שנכנסה לחופה ולא נבעלה אין חייבין עלי'\"<sup data-n=\"254\">14</sup>.\nועפ\"ז יש לומר, שמטעם זה הקדים הרמב\"ם דין אישות דקודם מ\"ת, כדי להדגיש יותר החידוש שבגדר קידושין דלאחר מ\"ת, וכדחזינן, שקודם מ\"ת ה­דרך היחידה ליצור גדר אישות היתה רק ע\"י שחיים יחד כבעל ואשה — \"מכניסה לתוך ביתו ובועלה כו'\".\nאבל ביאור זה אינו מספיק, כי אין בענין זה לכאורה שום נפק\"מ להלכה גבי אישות דישראל.\nזאת ועוד: מאי שנא קידושין מ­גירושין, דשם לא הקדים הרמב\"ם גדר הגירושין דלפני מ\"ת, אף שהחילוקים הנ\"ל בין ישראל וב\"נ בדין קידושין וגי­רושין תלויים זב\"ז. דכיון שענין האישות גבי ב\"נ נוצר ע\"י ההכנסה לביתו כו' (היינו חיי אישות בפועל), הרי כך גם שילוחה (או היציאה) מביתו היא העושה את הגירושין, משא\"כ בישראל שהאישות נבראה ע\"י קנין ו\"ליקוחין\", ולכן ביטול קנין זה הוא ע\"י כתב דוקא. וא\"כ כשם שהקדים הרמב\"ם דין אישות דקודם מ\"ת כדי להדגיש החידוש בליקוחין דמ\"ת, כן הו\"ל להקדים דין גירושין דקודם מ\"ת,",[["250","10","לקו\"ש ח\"ל ע' 243 ואילך. — וראה שם (ובהערה 34 שם) ביאור ל' אירוסין שבפרש\"י (ויחי מח, ט. וירא יט, יד), וכן מ\"ש \"הבה את אשתי\" (ויצא כט, כא. ובחדא\"ג מהרש\"א לסנהדרין (יט, ב) שכבר היתה מקודשת והויא אשתו). ועוד."],["251","11","בראשית ב, כד."],["252","12","בצפע\"נ עה\"ת שמות (ב, א) דעמרם \"הו­סיף דין של נישואין\" קודם מ\"ת. אבל י\"ל דשם הדיוק \"נישואין\", והיינו כניסה לחופה, וכל' הגמ' שמציין שם (ב\"ב קכ, א) \"הושיבה באפריון כו'\". אבל במהר\"ץ חיות לסוטה (יב, א) מפרש דעמרם הוסיף \"מצות קידושין\". וראה לקו\"ש שם הערה 42. לקו\"ש חי\"ח ע' 290 הערה 57."],["253","13","שם ה\"ז."],["254","14","ומ\"ש ש\"אין חייבין עלי'\", דמשמע שלכת­חילה אסור — י\"ל שאין זה מפני שכבר חל עלי' שם אשת איש, אלא לפי דכיון שנכנסה לחופה כו' ה\"ז כמו התחייבות להנשא, וה\"ז ע\"ד הונאה או גזל כו' (וראה סנהדרין נז, א ובפרש\"י שם ד\"ה על הגזל. רדב\"ז להל' מלכים שם ה\"ח). ואכ\"מ."]]],[1301870101,"כדי להדגיש החידוש בדין גירושין ש­אחרי מ\"ת (שמתגרשת ע\"י \"כתב\", גם כשהיא עדיין בבית בעלה).\nג. ויובן זה בהקדים עוד דיוק ב­רמב\"ם כאן:\nבגדר אישות דישראל יש שני שלבים — אירוסין שהם הקנין וליקוחין (ע\"י כסף שטר או ביאה) ונישואין (ע\"י כניסה לחופה). ואע\"פ שגם ע\"י אירוסין לחוד כבר חל על האשה שם \"אשת איש\", מ\"מ, כו\"כ חיובים (גם של תורה) חלים רק ע\"י נישואין<sup data-n=\"255\">15</sup>, שאז הרי הם איש ואשה לכל ה­דברים.\nועפ\"ז צע\"ק, שבריש הל' אישות מבאר הרמב\"ם רק ענין הקידושין (אירוסין) ואילו דין נישואין לא הזכיר עד פרק י', שרק שם<sup data-n=\"256\">16</sup> מבאר דכאשר \"יביא אותה לתוך ביתו ויתיחד עמה ויפרישנה לו (ו)יחוד זה הוא הנקרא כניסה לחופה והוא הנקרא נישואין בכל מקום. . והרי היא אשתו לכל דבר\". ולכאורה הו\"ל לבאר שם \"נישואין\" תיכף בריש הל' אישות, ביחד עם ביאור שם קידושין ואירוסין.\nואדרבה: קידושין \"היא (רק) תחילת מצות הנישואין. . אירוסין בלא נישואין ודאי לא השלים המצוה עדיין\"<sup data-n=\"257\">17</sup> (וכדיוק לשון הרמב\"ם בכותרת להל' אישות, ש­המצוה היא \"לישא אשה בכתובה וקידו­שין\", הרי שהמצוה היא הנישואין<sup data-n=\"258\">18</sup>), וא\"כ תמוה ביותר שלא ביאר ענין הנישואין תיכף בריש הל' אישות.\nוביותר אינו מובן, שהרי בב' הפרקים הראשונים דהל' אישות ביאר הרמב\"ם עשרים שמות השייכים להלכות אלו, ובסוף פרק ב' מונה כל העשרים שמות, החל משם \"קידושין\" (ומסיים \"שים כל השמות האלו לעומתך תמיד כו' כדי שלא נהי' צריכין לבאר כל שם מהן בכל מקום שנזכיר אותו\") — ואילו שם \"נישואין\" לא הזכיר כלל שם.\nד. ונ\"ל, שס\"ל להרמב\"ם, שעיקר חי­דוש התורה בענין אישות דישראל הוא רק בגדר קידושין, וכנ\"ל שכל גדר ליקו­חין אלו נתחדש ע\"י ציווי התורה, אבל בענין הנישואין, לא נשתנה מהות וגדר האישות מכפי שהי' קודם מ\"ת. דענין הנישואין עצמם הוא המציאות דחיי אי­שות, בלשון הרמב\"ם \"מכניסה לתוך ביתו כו' ותהי' לו לאשה\", ובזה אין שינוי (עיקרי) בין קודם מ\"ת ללאחר מ\"ת.\nוזהו שדייק הרמב\"ם בלשונו \"כיון שנתנה תורה נצטוו ישראל שאם ירצה האיש לישא אשה יקנה אותה תחלה כו' ואח\"כ תהי' לו לאשה\", והולך ומפרט ענין \"ליקוחין\" אלו ולא הענין ד\"לישא אותה\" (נישואין), כי חידוש התורה אינו בענין \"לישא אשה\" (\"תהי' לו לאשה\") גופא, שענין זה נשאר כמו שהי' קודם מ\"ת, אלא רק בליקוחין הקודמין לנישו­אין, \"יקנה אותה תחלה (ואח\"כ תהי' לו לאשה)\".\nוזה גופא הטעם שהקדים הרמב\"ם",[["255","15","כמו החילוק בין נערה המאורסה שהיא בסקילה ונשואה בחנק (פרשתנו כב, כ­כד. ספרי שם. סנהדרין נב, סע\"ב. ובכ\"מ); החילוק באופן הפרת נדר דארוסה ודנשואה (מטות ל, ז ואילך ובפרש\"י שם. נדרים רפ\"י). ועוד."],["256","16","ה\"א."],["257","17","תשובת ר\"א בן הרמב\"ם, הובאה בכס\"מ כאן פ\"א סה\"ב (ומתרץ עפ\"ז ל' הגמ' (מו\"ק יח, ב) \"לארס דלא קעביד מצוה. . לישא. . דקא עביד מצוה\")."],["258","18","כמו שמדייק בתשובת ר\"א בן הרמב\"ם שם."]]],[1301870102,"ע\"ד סדר ענין האישות \"קודם מ\"ת\", שאין זו (רק) הקדמה להבין החידוש בקידושין של ישראל, אלא כדי לבאר שם נישואין (גם עתה לאחר מ\"ת), שזהו עיקר ענין האישות. ונמצא, שלא זו בלבד ש­הרמב\"ם לא השמיט כאן ביאור שם נישואין, אלא אדרבה, זוהי התחלת הל' אישות [אלא שמבאר כיצד הי' \"קודם מ\"ת\", כיון שזה לא נשתנה אחרי מ\"ת] — ורק אח\"כ מבאר עשרים שמות פרטיים ה­שייכים לענין הנישואין (החל מהשם \"קידושין\").\nועפ\"ז מובן החילוק בין אישות לגי­רושין, דכאן הקדים הרמב\"ם דין אישות קודם מ\"ת משא\"כ גבי גירושין, כי בנוגע לאישות, הרי גדר האישות דקודם מ\"ת נשאר גם לאחר מ\"ת בענין הנישואין (וה­חידוש דמ\"ת הוא בהליקוחין שבאים קודם הנישואין); ואילו בגירושין, הרי היציאה (ושילוח) מבית הבעל כפי שהוא אצל ב\"נ, לא מהני כלל בישראל.\nה. ויש לומר, שדבר זה (שגדר ה­נישואין לא נשתנה אחר מ\"ת) נוגע להלכה — כי זהו יסוד שיטת הרמב\"ם בגדר חופה (שהיא העושה נישואין), שמצינו כמה שיטות<sup data-n=\"259\">19</sup> מהי כניסה לחופה, והרמב\"ם<sup data-n=\"260\">20</sup> פסק שכניסה לחופה היינו \"יחוד\", \"שיביא אותה לתוך ביתו ויתיחד עמה ויפרישנה לו\" — והרי זה קרוב מאד לתיאור האישות דקודם מ\"ת, ש\"מכניסה לתוך ביתו ובועלה כו'\". והיינו לפי שס\"ל להרמב\"ם שענין הנישואין שלאחרי מ\"ת הוא הוא ענין הנישואין שקודם מ\"ת, דהיינו המעשה דחיי אישות, ולכן כדי שיחול על האשה שם \"נשואה\" ה\"ז שווה לדרך הנישואין שקודם מ\"ת.\nואע\"פ שיש נפק\"מ בין נישואין דקודם מ\"ת ונישואין לאחרי מ\"ת, דקודם מ\"ת (וכן בב\"נ אחרי מ\"ת) צ\"ל חיי אישות ממש (\"בועלה כו'\"), ואילו בישראל מספיק ייחוד בלבד להשוותה נשואה, וכמ\"ש הרמב\"ם<sup data-n=\"261\">21</sup> ד\"משתכנס לחופה נקראת נשואה אע\"פ שלא נבעלה\" — הרי נוסף לזה שגם ענין היחוד (לשם אישות) גופא הוא כמו מעשה אישות<sup data-n=\"262\">22</sup> [ובפרט שה­רמב\"ם מדייק שלא מספיק יחוד בלבד אלא צ\"ל באופן ד\"יפרישנה לו\", וכמבואר בפוסקים<sup data-n=\"263\">23</sup> דהיינו שצ\"ל באופן של קבי­עות, ולא שמביאה לתוך ביתו באופן דלפי שעה כו'], הרי כ' הרמב\"ם<sup data-n=\"261\">21</sup> שיחוד זה צ\"ל \"ראוי' לבעילה, אבל אם היתה נדה אע\"פ שנכנסה לחופה ונתיחד עמה לא גמרו הנישואין והרי היא כארוסה עדיין\". וע\"פ הנ\"ל מובן הטעם בפשטות, כי זהו כל גדר ענין הנישואין, ההכנסה לתוך ביתו והחיים יחדיו כאיש ואשה, ולכן צ\"ל יחוד הראוי לחיי אישות.\nו. ע\"פ הנ\"ל יש לבאר בדרך הדרוש הקשר והשייכות שבין תחילת ספר נשים לסוף ספר זמנים שלפניו.\nובהקדם, שע\"פ הידוע גודל הדיוק בסדר הענינים שבספר הרמב\"ם, מסתבר לומר, שיש קשר עניני בין י\"ד ספרי הרמב\"ם, שתחילת כל ספר היא בהמשך לסיום הספר הקודמו<sup data-n=\"265\">24</sup>.",[["259","19","שו\"ע אה\"ע ר\"ס נה וברמ\"א שם. וראה אנציקלופדי' תלמודית ערך חפה בתחלתו. וש\"נ."],["260","20","הל' אישות פ\"י ה\"א."],["261","21","שם ה\"ב."],["262","22","כפסק הרמב\"ם (הל' גירושין פ\"י הי\"ח. וראה גם הל' אישות פ\"ג ה\"ה ובמגיד משנה שם) \"הן הן עדי יחוד הן הן עדי ביאה\"."],["263","23","ב\"ש וח\"מ לשו\"ע אה\"ע שם."],["261","21","שם ה\"ב."],["265","24","ראה גמ' ריש סוטה: מכדי תנא מנזיר סליק מאי תנא דקא תנא סוטה. ועד\"ז בגמ' ריש שבועות. ועוד. תוס' ריש ב\"מ וריש ב\"ב."]]],[1301870103,"ובעניננו — ספר זמנים וספר נשים — הקשר ביניהם גלוי ומפורש: ההלכה ה­אחרונה דספר זמנים היא \"הי' לפניו נר ביתו ונר חנוכה כו' נר ביתו קודם משום שלום ביתו, שהרי השם נמחק לעשות שלום בין איש לאשתו, גדול השלום שכל התורה ניתנה לעשות שלום בעולם שנאמר<sup data-n=\"266\">25</sup> דרכי' דרכי נועם וכל נתיבותי' שלום\". והרי זהו תוכן כל ספר נשים, ענין ה\"שלום שבין איש לאשתו\".\nויש להוסיף עוד, שבהתחלת ספר נשים מודגש לא רק הענין ד\"שלום בין איש לאשתו\", אלא גם הפרט שענין ה­שלום נפעל ע\"י (מתן) תורה, כהסיום ממש דספר זמנים \"שכל התורה ניתנה לעשות שלום בעולם\".\nשהרי, בהלכות הראשונות דספר נשים מדגיש הרמב\"ם (כנ\"ל) החידוש שנתחדש ע\"י מתן תורה<sup data-n=\"267\">26</sup> בענין האישות, \"קודם מ\"ת הי' אדם פוגע אשה בשוק כו' כיון שנתנה תורה נצטוו ישראל שאם ירצה האיש לישא אשה יקנה אותה תחלה כו' ואח\"כ תהי' לו לאשה\". ומובן בפשטות, שסדר זה שצריך קנין קודם שתהי' לו לאשה, מורה על חוזק הקשר והקביעות שביניהם. דקודם מ\"ת הרי תיכף ומיד כשרצה הוא והיא \"מכניסה לתוך ביתה כו'\", ומובן שאין כאן קשר חזק, וכמו שהכניסה כך יכול לשלחה מביתו תיכף ומיד כשירצה<sup data-n=\"268\">27</sup>, ע\"ד \"בן לילה הי' ובן לילה אבד\"<sup data-n=\"269\">28</sup>; משא\"כ לאחרי מ\"ת, כיון שאינו מכניסה לביתו תיכף ומיד שפוגע בה, אלא רק לאחרי ההקדמה ש\"יקנה אותה תחלה כו'\", מובן, שיש לזה קיום ותוקף גדול יותר. ועד שאינו יכול לשלחה תיכף ומיד כשירצה, אלא \"אם רצה לגרש צריכה גט\"<sup data-n=\"270\">29</sup>.\n[ועפ\"ז מובן גם הטעם שאח\"כ<sup data-n=\"271\">30</sup> ממ­שיך הרמב\"ם בעוד דין שנתחדש במתן תורה — \"קודם מ\"ת הי' אדם פוגע אשה בשוק כו' וזו היא הנקראת קדשה, משנת­נה תורה נאסרה הקדשה כו'\", שגם תוכן דין זה הוא להוסיף שלום, כמו שביאר הרמב\"ם במו\"נ<sup data-n=\"272\">31</sup> בטעם איסור קדשה, שה\"תועלות. . מניעת הקטטות. . אלו היתה הקדשה מותרת. . לא היו נמלטים מהמחלוקת וברוב הפעמים היו הורגים זה את זה או היו הורגים אותה כו'\"].\nז. ויש לומר, שגם משנת\"ל בכוונת הרמב\"ם בריש הל' אישות, שחידוש ה­תורה הוא בעיקר בענין הקידושין, ואילו ענין הנישואין הוא כמו ענין האישות דקודם מ\"ת, יש לו קשר לדברי הרמב\"ם בסוף ספר זמנים.\nויובן זה בהקדים דיוק לשון הרמב\"ם \"התורה ניתנה לעשות שלום בעולם\", ו­הרי התורה ניתנה לישראל דוקא, \"מור­שה קהלת יעקב\"<sup data-n=\"273\">32</sup>, וא\"כ הול\"ל \"לעשות שלום בישראל\" (וכיו\"ב), ומהו אומרו \"לעשות שלום בעולם\"?",[["266","25","משלי ג, יז."],["267","26","ראה לעיל הערה 12."],["268","27","כלשון הרמב\"ם (הל' מלכים פ\"ט ה\"ח) \"משיוציאנה כו' או משתצא כו' כל זמן שירצה הוא או היא לפרוש זה מזה פורשין\"."],["269","28","יונה ד, י."],["270","29","להעיר ממו\"נ (ח\"ג פמ\"ט) בטעם שגירו­שין אינם בדברים בלבד או ע\"י שילוחה מביתו אלא רק ע\"י שטר."],["271","30","ה\"ד."],["272","31","שם."],["273","32","ברכה לג, ד. סנהדרין נט, רע\"א. רמב\"ם הל' מלכים פ\"ח ה\"י."]]],[1301870104,"לכאורה הי' אפשר לבאר זה ע\"פ דברי הרמב\"ם<sup data-n=\"274\">33</sup>, ד\"צוה משה רבינו מפי הגבורה לכוף את כל באי העולם לקבל מצות שנצטוו בני נח\", וכן, שב\"נ שקיבל על עצמו שבע מצות ונזהר לעשותן אינו מחסידי אומות העולם אלא א\"כ עושה אותן \"מפני שצוה בהן הקב\"ה בתורה\"<sup data-n=\"275\">34</sup>, וא\"כ פעולת התורה היא גם בב\"נ, שע\"י קיום ז' מצות ב\"נ נעשה שלום בהם.\n[ועפ\"ז יש לבאר גם כפל הלשון בכתוב \"דרכי' דרכי נועם וכל נתיבותי' שלום\": החילוק בין \"דרך\" ו\"נתיב\" הוא, דדרך היא דרך רחבה וגדולה, ואילו נתיב הוא שביל צר וקטן<sup data-n=\"276\">35</sup>. ובענייננו — \"דרך\" קאי על תרי\"ג מצוות התורה ש­ניתנו לישראל דוקא, שזהו החלק הגדול והעיקרי שבתורה, ואילו \"נתיבותי'\" קאי על ז' מצות ב\"נ, שהם רק חלק הכי קטן כו'.\nוזהו הטעם שגבי \"דרכי'\" נקט \"נועם\" דוקא, וגבי \"נתיבותי'\" אומר \"שלום\": פעולת התורה בב\"נ היא עצם גדר השלום, משא\"כ בבנ\"י, ד\"כל איש ישראל גו' כאיש אחד חברים\"<sup data-n=\"277\">36</sup>, \"כל ישראל אחים\"<sup data-n=\"278\">37</sup>, ישנו ענין השלום מצד עצם תכונת נפשם, ופעולת התורה היא להו­סיף בשלום גופא, שיהי' גם ענין ה­\"נועם\"<sup data-n=\"279\">38</sup>].\nאבל אין זה ביאור מספיק, כי מלשון הרמב\"ם \"כל התורה ניתנה לעשות שלום בעולם\", מוכח, דמ\"ש \"שלום בעולם\" אין כוונתו לפעולת ז' מצות ב\"נ בב\"נ, אלא לפעולת תרי\"ג מצות דישראל.\nויש לומר הביאור בזה: בפעולת ה­תומ\"צ יש ב' סוגים: הנהגות בדברים שבקדושה ששייכים אך ורק בבנ\"י ומעי­קרא אינם עניני ה\"עולם\"; וענינים שב­כללות יש דוגמתם גם אצל אוה\"ע, אלא שבהם גופא נעשה שינוי עיקרי ע\"י נתינת התורה, באופן שהתורה עושה \"שלום בעולם\", שבעניני ודרכי העולם נתוסף ענין השלום<sup data-n=\"280\">39</sup>.\nוזהו שכ' הרמב\"ם, שעיקר כוונת נתינת התורה למטה, אינה (כ\"כ) בשביל פעולת התומ\"צ מה שהיא פועלת הת­נשאות אצל בנ\"י ומגבי' אותם למעלה מן העולם, אלא אדרבה, מה שעל ידה נפעל חידוש ותוספת \"שלום\" בעניני העולם גו­פא (\"שלום בעולם\").\nוענין זה הוא בהדגשה בענין \"שלום בין איש לאשתו\", שזהו מה שממשיך הרמב\"ם בריש הל' אישות, אודות גדר אישות קודם מ\"ת, דגם אז הי' גדר של אישות, שיש דרך ליצור ענין האישות, \"ותהי' לו לאשה\", שזה עצמו הוא ענין של \"שלום\", אבל בזה גופא פועלת התורה \"שלום בעולם\", שנתוסף בענין",[["274","33","הל' מלכים שם."],["275","34","הל' מלכים שם הי\"א."],["276","35","ראה אוה\"ת לנ\"ך ח\"א עה\"פ משלי שם (ע' תקנד). וש\"נ. מאמרי אדמו\"ר האמצעי בראשית ע' ו."],["277","36","ס' שופטים כ, יא. תניא אגה\"ק סו\"ס כב. שם סל\"א. וראה הערה הבאה."],["278","37","ראה פ' תצא כב, ב. יחזקאל יח, יח וב­רד\"ק. ועייג\"כ תנחומא נשא א. רמב\"ם הל' מתנות עניים פ\"י ה\"ב. ירושלמי נדרים פ\"ט ה\"ד ובקה\"ע שם. רדב\"ז להל' ממרים פ\"ב ה\"ד. תניא פרק לב. ס' המצות להצ\"צ מצות אהבת ישראל. ובכ\"מ."],["279","38","ראה מפרשים שהובאו באוה\"ת עה\"פ משלי שם."],["280","39","ובעיקרם הם המצות שבין אדם לחבירו. ולהעיר מל' חז\"ל (שבת לא, א) \"זו היא כל התורה כולה\", וברש\"י שם (בפי' הב') \"כגון גזלה גנבה ניאוף ורוב המצות\"."]]],[1301870105,"ה\"שלום\", באופן שיש בו (נוסף על \"שלום\") גם ענין ה\"נועם\", ע\"י שקודם הנישואין צריך לקנות את האשה תחילה \"ואח\"כ תהי' לו לאשה\".\nח. ויש לבאר ענין הנ\"ל בגדר קידו­שין ונישואין ע\"פ פנימיות הענינים:\nידוע שאיש ואשה, חתן וכלה, הם משל על הקב\"ה וכנסת ישראל, שהקשר של ישראל לאביהם שבשמים נמשל ל­אירוסין ונישואין. והחילוק ביניהם הוא: אירוסין שהם \"קידושין\" — מלשון \"אסר לה אכולי עלמא כהקדש\"<sup data-n=\"281\">40</sup> — מורה על המשכת קדושה עליונה על האדם, של­מעלה מעלה מגדרי העולם, שלכן היא בהבדלה מן העולם — קדושה מלשון הב­דלה<sup data-n=\"282\">41</sup> — הפועלת באדם פרישות והבדלה מן העולם (איסור, שלילה)<sup data-n=\"283\">42</sup>; משא\"כ ענין הנישואין הוא, כאשר קדושה זו נמשכת בהאדם בפנימיות, עד שהאדם, גם כפי שהוא בהגבלות הגוף והעולם, נעשה כלי לקדושה זו.\nוזהו שענין הנישואין כשלעצמו (היינו היחוד וההמשכה בפנימיות) אינו עיקר החידוש דמ\"ת, כי התנועה דהמשכת אור הקדושה בפנימיות ישנה גם קודם מ\"ת (היינו באור האלקי המוגבל, שלפי ערך העולמות); ועיקר חידוש התורה הוא בענין הקידושין, שהיא המשכת קדושה שלמעלה מגדרי העולם, שזו אינה בכחו של אדם מצד עצמו אלא רק בכח התורה;\nאלא שלאחרי שניתן לאדם הכח להמ­שיך קדושה זו, הרי הנישואין הבאים אחר כך, שבהם נמשכת קדושה עליונה זו בפנימיות, הם בדרך ממילא באופן אחר לגמרי, באופן של קביעות וקשר חזק (כנ\"ל), כיון שההמשכה בפנימיות היא מקדושה זו שלמעלה מגדרי העולם<sup data-n=\"284\">43</sup>.\nואדרבה: תכלית הכוונה היא לא בענין הקידושין (שהאור נשאר בבחי' הב­דלה ומקיף), אלא דוקא בענין הנישואין, וכלשון הרמב\"ם \"שכל התורה ניתנה לעשות שלום בעולם\", שהיא המשכת ה­קדושה בעולם דוקא, שענין זה יהי' בגילוי לעת\"ל, וכמרז\"ל<sup data-n=\"285\">44</sup> שבעת מ\"ת הי' רק ענין האירוסין, וענין הנישואין בין הקב\"ה לכנסת ישראל יהיו בגאולה ה­אמיתית והשלימה ע\"י משיח צדקנו, יבוא ויגאלנו ויוליכנו קוממיות לארצנו, במה­רה בימינו ממש.\n<span data-k=\"q\">(משיחת ש\"פ תשא תשמ\"ט)</span>",[["281","40","קידושין ב, ריש ע\"ב."],["282","41","ראה תניא פמ\"ו (סו, א)."],["283","42","להעיר מהמבואר בכ\"מ שקידושין הם בחי' מקיף, שלכן מקדשין בטבעת דוקא (תו\"א ס\"פ ויגש. ובכ\"מ)."],["284","43","להעיר מלקו\"ת שמע\"צ צא, א."],["285","44","שמו\"ר ס\"פ טו. נת' ע\"ד החסידות בתו\"א שם. לקו\"ת שה\"ש מח, סע\"א. ועוד."]]],[1301870106,"<h3>תבא (תנש\"א)</h3>\nא. \"אמר<sup data-n=\"286\">1</sup> רבי יוחנן<sup data-n=\"287\">2</sup> ג' מפתחות בידו של הקב\"ה שלא נמסרו ביד שליח ואלו הן מפתח של גשמים ומפתח של חי' ומפתח של תחיית המתים<sup data-n=\"288\">3</sup> מפתח של גשמים ד­כתיב<sup data-n=\"289\">4</sup> יפתח ה' לך את אוצרו הטוב את השמים לתת מטר ארצך בעתו כו' במע­רבא אמרי אף מפתח של פרנסה<sup data-n=\"290\">5</sup> דכתיב<sup data-n=\"291\">6</sup> פותח את ידיך וגו' ור' יוחנן מאי טעמא לא קא חשיב להא אמר לך גשמים נמי<sup data-n=\"292\">7</sup> היינו פרנסה\".\nולכאורה נראה, שר' יוחנן מדבר ב­כללות, ובאופן כללי \"גשמים נמי היינו פרנסה\", וכפרש\"י<sup data-n=\"293\">8</sup> \"שזרעים ופירות גדי­לים מהם (מגשמים) לפרנסת העולם\", וב­מערבא מפרטים יותר<sup data-n=\"294\">9</sup>, ולכן מנו \"פר­נסה\" כמפתח בפ\"ע, דאף שבכללות הרי גשמים הם המקור לפרנסת העולם, מ\"מ כיון שבפרטיות יש פרנסה שאינה ע\"י גשמים (וכן לאידך, יש גשמים כאלו שאינם נוגעים לפרנסה באופן ישר, שאינם יורדין במדה ראוי'<sup data-n=\"295\">10</sup> שיהיו זרעים ופירות גדילים מהם<sup data-n=\"296\">11</sup>), לכן חשבי \"פר­נסה\" בפ\"ע.\nאבל לא משמע כן מסגנון דברי הגמ' \"ור' יוחנן מאי טעמא לא קא חשיב להא אמר לך כו'\", דפשטות הלשון מורה שיש כאן פלוגתא והן שתי דיעות בענין זה.\nב. וי\"ל בביאור סברת הפלוגתא, ב­הקדים תירוץ קושיית המפרשים<sup data-n=\"297\">12</sup> על דברי ר\"י \"אמר לך גשמים נמי היינו פרנסה\", דר\"י גופי' אמר לקמן<sup data-n=\"298\">13</sup> \"מטר בשביל יחיד פרנסה בשביל רבים, מטר בשביל יחיד דכתיב יפתח ה' לך את",[["286","1","תענית ב, סע\"א ואילך. ובשינויים — בדב\"ר פרשתנו פ\"ז, ו. ב\"ר פע\"ג, ד. מדרש תהלים עח (קרוב לתחלתו). תרגום ירושלמי ויצא ל, כב."],["287","2","בדב\"ר ובמדרש תהלים בשם (ר' נחמי' או) ר' יונתן (ובב\"ר \"ר' תנחומא בשם ר' ביבי\"). וראה לקמן בפנים סעיף ו ובהערה 36."],["288","3","כ\"ה סדרן בגמרא לפנינו. אבל בע\"י (ובגי' הב\"ח בגמ'), חי' גשמים ותחיית המתים (וכ\"ה בסנ­הדרין קיג, סע\"א), כסדרן ב(הראיות מ)הכתובים (ראה דק\"ס תענית שם). בדב\"ר פרשתנו: תחה\"מ עקרות וגשמים. במדרש תהלים: רחם (חי') תחה\"מ וגשמים. בב\"ר: קבורה (תחה\"מ) גשמים ורחם. וב­תרגום ירושלמי שם מטרא פרנסה קבריא עקרתא. וראה יפ\"ת השלם לב\"ר שם ד\"ה מפתח של קבורה. ואכ\"מ."],["289","4","פרשתנו כח, יב."],["290","5","בשאר מדרשים הנ\"ל הערה 1 ליתא, מלבד בב\"ר שם שאי' \"וי\"א אף מפתח של פרנסה שנא' פותח כו'\", ועד\"ז בתרגום ירושלמי שם (ראה הערה 17)."],["291","6","תהלים קמה, טז."],["292","7","כ\"ה גי' הע\"י, והגי' בפרש\"י<sup data-n=\"e9\">*</sup> וב\"ח כאן."],["293","8","תענית שם ד\"ה גשמים — בע\"י ובגירסת הב\"ח."],["294","9","ראה לקו\"ש חכ\"ד ע' 169. ושם שזהו חילוק כללי בין שיטת הירושלמי והבבלי. ואכ\"מ."],["295","10","ראה תענית יח, ב ואילך (במשנה). יט, ב. כג, א. ועוד."],["296","11","ואפשר להיות גם \"פעמים שאינו מתבקש\" (שם ד, א. וראה שם יט, א (במשנה). ועוד)."],["297","12","פרשת דרכים דרוש כא. גבורת ארי לתע­נית כאן."],["298","13","תענית ט, א."],["e9","*","ראה מהר\"ץ חיות סוף מס' תענית; שם הגדולים להחיד\"א מערכת גדולים ערך רש\"י קרוב לסופו — אם הפירוש לתענית הוא לרש\"י."]]],[1301870107,"אוצרו הטוב לתת מטר ארצך, פרנסה בשביל רבים דכתיב<sup data-n=\"299\">14</sup> הנני ממטיר לכם לחם\", הרי דגם לר\"י מטר ופרנסה תרי מילי נינהו.\nויש לומר, ע\"פ מ\"ש רש\"י בפי' דברי הגמ' שם<sup data-n=\"300\">15</sup> \"מטר בשביל יחיד, שאם א\"צ מטר אלא לאדם אחד כגון שזרע אחר זמן זריעת בני אדם או שדר בעיר שכולה נכרים וצריך למטר בא בזכותו, ופרנסה שפע טובה ומחי' לכל העולם אינו בא לעולם בזכות אחד אלא בשביל רבים, שאם רבים צריכין שובע שתשלח ברכה בתבואה הקב\"ה עושה אם זכו, אבל יחיד הצריך שיתברכו תבואות שלו אין הקב\"ה משנה בעבורו דין השנה אלא כפי בר­כותי', ואע\"פ שמוריד בשביל יחיד מטר זה להשביח תבואותיו שלא יהו גרועות משל אחרים אבל לעשות שדהו כשדה שו­בע לא\".\nולפ\"ז מובן דהכוונה ב\"פרנסה\" שם היא לשפע מיוחד שהוא באופן דשובע, וא\"כ מובן דרק באופן זה פרנסה ומטר ב' מילי נינהו.\nובחדא\"ג מהרש\"א שם מפרש \"מטר שהוא אינו אלא צורך הפרנסה והוא ניתן בטבע מן השמים אם יש בה צורך ליחיד ניתן לו בזכותו, אבל פרנסה גופי' בענין שתבא מן השמים כגון המן והבאר הוא דבר ניסי ולא בא רק בשביל רבים\".\nועפ\"ז הי' אפשר לבאר החילוק בין דעת ר\"י ובני מערבא, דר\"י דקאמר \"גש­מים נמי היינו פרנסה\" מדבר בפרנסה רגילה, לא באופן של שובע מיוחד, ולא פרנסה הבאה באופן גלוי מלמעלה, ואילו במערבא דחשבי פרנסה בפ\"ע, קאי בפר­נסה שהיא השפעה מיוחדת מאת הקב\"ה שאינה באה אלא בשביל רבים.\nאבל לפי זה עדיין קשה קושיית הגמ' \"ור' יוחנן מאי טעמא לא קא חשיב להא\", היינו מדוע חשב ר\"י רק פרנסה הנכללת בגשמים (ואין כאן אלא ג' מפתחות), ולא חשיב גם מפתח זה של פרנסה שאינה נכללת ב\"גשמים\", והוא מפתח בפ\"ע שבא מה' ולא נמסר ביד שליח?\nג. ולכן נ\"ל דר\"י ובני מערבא מדב­רים שניהם אודות אותו סוג \"פרנסה\", אלא דפליגי בסברא אם \"פרנסה\" צריכה \"מפתח\" מיוחד, או נכללת בה\"מפתח\" דגשמים.\nוביאור הדברים:\n\"גשמים\" ו\"פרנסה\" בדרך כלל, הם תוארים להשפעת מזון וצרכי האדם, וה­חילוק ביניהם הוא, ד\"גשמים\" מורה על השפעת הפרנסה מלמעלה, \"ונתתי<sup data-n=\"301\">16</sup> גש­מיכם בעתם\", ואילו התואר \"פרנסה\" בדרך כלל בא לתאר את קבלת ההשפעה, שהאדם מתפרנס וניזון מהשפעה זו. וכן הוא גם בפשטות, שה\"גשמים\" באים מל­מעלה ופועלים צמיחה וכו', משא\"כ \"פרנסה\" באה ע\"י עבודת ופעולת האדם, חרישה זריעה וקצירה כו'.\nולפי זה, החילוק בין ר\"י ובני מערבא הוא, דר\"י מדבר ע\"ד ה\"מפתחות\" של הדברים כפי שהם באים מאת הקב\"ה, הנותן, ולכן חשיב רק \"גשמים\" ולא פר­נסה (שאין פרנסה השפעת הקב\"ה מצ\"ע, אלא זוהי עבודת האדם שהשפעת הקב\"ה תתקבל אצלו); ואילו במערבא מדברים גם כפי שהוא מצד המקבל, כפי שהש­",[["299","14","בשלח טז, ד."],["300","15","תענית שם ד\"ה מטר."],["301","16","בחקותי כו, ד."]]],[1301870108,"פעת המזון נעשית \"פרנסה\", ולכן חשבו גם \"פרנסה\".\n[ולפי ביאור זה, מובנת גם ההתאמה למספר המפתחות, דלר\"י יש ג' מפתחות, ולמערבא יש ד'<sup data-n=\"302\">17</sup>: החילוק בין אות ג' לאות ד' הוא (כדאיתא בגמ'<sup data-n=\"303\">18</sup>) — \"גמול דלים\", היינו שאות ג' מורה על הגורם ההשפעה ה\"גומל חסדים\"<sup data-n=\"303\">18</sup>, ואות ד' מו­רה על ה\"דלים\", מקבלי ההשפעה. ומזה מובן גם בנוגע להגימטריא של אותיות אלו — מספר ג' ומספר ד', דמספר ג' מורה על הנתינה, כמו שהוא מצד הנותן (\"גומל\"), ואילו ד' מורה כפי שהוא מצד המקבל (ה\"דלים\")<sup data-n=\"305\">19</sup>].\nד. אך עדיין צריך ביאור, שהרי תוכן המבואר בסוגיא זו הוא ע\"ד \"מפתחות בידו של הקב\"ה שלא נמסרו ביד שליח\", היינו, שגדר \"מפתחות\" אלה הוא שכולם באים מאת הקב\"ה, ואין יד \"ממוצע\" באמצע, וא\"כ מהו הפירוש ש\"במערבא אמרי אף מפתח של פרנסה\", שחשבו \"פרנסה\" למפתח בפ\"ע כיון שפרנסה הוא דבר התלוי ושייך לעבודת האדם (ולכן אינו פרט במפתח ד\"גשמים\") — דלפ\"ז איך אפשר לומר שזהו \"מפתח\" שהוא רק בידו של הקב\"ה?\nויש לבאר זה בהקדם מה שביארו חז\"ל<sup data-n=\"306\">20</sup> לענין ירידת גשמים שבאים מל­מעלה, שא' מהטעמים לכך הוא בכדי \"שיהו הכל תולין עיניהם כלפי מעלה\". כלומר, זה שפרנסתם של הבריות תלוי' בגשמים הבאים מלמעלה ולא בדבר שיש בידי האדם עצמו לעשות (כמו בארץ מצרים, שהשקאת השדות היא \"ברג­לך\"<sup data-n=\"307\">21</sup>), פועל בהם הכרה כדבעי שכל פר­נסתם וחיותם (ולא רק הגשמים) היא ע\"י הקב\"ה עצמו.\n[וזוהי גם מעלת ארץ ישראל על שאר הארצות, ש\"א\"י משקה אותה הקב\"ה בעצמו, וכל העולם כולו ע\"י שליח\"<sup data-n=\"308\">22</sup>, שבארץ ישראל ניכר בגלוי שכל השפעת החיות מלמעלה היא אך ורק ע\"י הקב\"ה, משא\"כ בחו\"ל אפשר לטעות<sup data-n=\"309\">23</sup> שיש תפי­סת מקום גם ל\"שליח\", וגם לכשרונות ומעלות האדם כו']<sup data-n=\"310\">24</sup>.\nומזה מובן גם לעניננו, דזה שמפתח גשמים לא נמסר ליד שליח (ו\"גשמים נמי היינו פרנסה\"), פירושו, שבאמת כל פר­נסת האדם היא אך ורק מהקב\"ה, באופן שאין תפיסת מקום לשום דבר שחוץ ממנו, וגם לא ללבושי הטבע שהאדם עושה כדי שעל ידם יוכל לקבל את פרנסתו מהקב\"ה. וזה ש\"יצא אדם לפעלו",[["302","17","בתרגום ירושלמי ויצא שם: ארבעה מפת­חין כו' מפתח מטרא מפתח פרנסה כו'."],["303","18","שבת קד, א."],["303","18","שבת קד, א."],["305","19","ראה מו\"נ (ח\"ב פ\"י) בענין מספר ארבעה. צפע\"נ עה\"ת ר\"פ ויצא. וע\"ד החסידות ראה תו\"א וארא נט, א. ביאוה\"ז בלק קז, ד ואילך. לקו\"ש חי\"ז ע' 202."],["306","20","ב\"ר פי\"ג, ט. ועד\"ז בירושלמי תענית פ\"ג ה\"ג."],["307","21","עקב יא, יא."],["308","22","תענית י, א."],["309","23","וכידוע פי' מרז\"ל (ע\"ז ח, סע\"א) ישראל שבחו\"ל עובדי ע\"ז בטהרה הם — ראה ד\"ה וידעת מוסקווא תרנ\"ז (סה\"מ תרנ\"ז ע' נח ואילך). ועוד. וראה לקו\"ש ח\"ו ע' 30 ואילך. וש\"נ."],["310","24","להעיר מצפע\"נ הל' תרומות בהשמטות (סא, ריש ע\"ד): וזהו כוונת הגמ' בתענית דף י' דבחו\"ל ע\"י שליח ר\"ל גדר הטבע אף בהני שלא נמסרו לשליח ע\"ש דף ב'. וראה צפע\"נ עה\"ת שם. ובפ' עקב יא, י. וראה ע\"ד החסידות (בביאור הגמ' בריש תענית ושם) אוה\"ת עקב ס\"ע תריג ואילך. בחקותי ס\"ע קצד ואילך. ובכ\"מ."]]],[1301870109,"ולעבודתו עדי ערב\"<sup data-n=\"311\">25</sup> בעסק הפרנסה, הוא אך כדי לקיים ציווי הקב\"ה \"וברכך<sup data-n=\"312\">26</sup> ה' אלקיך בכל אשר תעשה\", \"ששת<sup data-n=\"313\">27</sup> ימים תעבוד ועשית כל מלאכתך\".\nועוד זאת: לא זו בלבד שהאדם יודע שעצם ההשפעה באה רק מלמעלה, \"בר­כת<sup data-n=\"314\">28</sup> ה' היא תעשיר\", וכל מעשיו אינם אלא<sup data-n=\"315\">29</sup> \"כלי קבלה\" לברכת השם (ע\"ד כלי השמן דנס אלישע<sup data-n=\"316\">30</sup>, שכל ענינם הי' רק להכיל השמן הנסי), אלא יתר על כן, שגם ה\"כלים\" אין להם חשיבות אפי' בתור \"כלים\" (ולבושים) להכיל ברכת ה', ואינו עושה אותם אלא מחמת ציווי הקב\"ה, וא\"כ הרי הם טפלים לגמרי לברכת השם, שהיא ברכה שלמעלה מדרך הטבע לגמרי.\nה. אמנם הכרה זו גופא אפ\"ל בב' אופנים<sup data-n=\"317\">31</sup>:\nא) מעשי האדם ולבושי הטבע אין להם חשיבות כלל. דכשם שבהנהגה נסית נראה ונגלה בפועל שחוקי הטבע אין להם מציאות כלל — הרי באותו האופן ממש הוא גם כאשר ההשפעה מהקב\"ה באה ע\"י לבושי הטבע, וכמו המן שירד<sup data-n=\"318\">32</sup> מן השמים<sup data-n=\"319\">33</sup>;\nב) אף שמעשי האדם והכלי שעושה אין להם תפיסת מקום מצד עצמם ועושה זאת רק מפני ציווי ה', הרי מחמת ציווי ה' גופא יש להם חשיבות, שעל ידם מתקיים רצונו יתברך.\nבסגנון אחר: האמונה שלו היא בוד­אות גמורה שהכל בא רק מהקב\"ה, ובמילא הרי הוא בבטחון גמור בהקב\"ה שהוא יתן לו הכל מידו המלאה הפתוחה הקדושה והרחבה, אבל גם ענין זה ש­הקב\"ה ציוה שיעשה מעשה בזה בטבע, הוא יודע שגם זה בכוונה מכוונת, והיינו לידע ולהכיר שגם הטבע עצמו ועשיית האדם בזה, באים מאתו ית', מלבד עצם ההשפעה שבאה מהקב\"ה.\nוי\"ל שהם ב' האופנים אם המפתח של פרנסה נחשב למפתח בפ\"ע, או שהוא בכלל מפתח גשמים:\nלר\"י \"גשמים (נמי) היינו פרנסה\", כי כל לבושי הטבע וכן מעשי האדם שבזה, אין להם תפיסת מקום כלל — והא קמ\"ל, שביחס לענין הפרנסה כל מעשיו בזה הם פרט בהשפעת הקב\"ה להאדם;\nו\"מערבא אמרי אף פרנסה דכתיב פותח את ידיך וגו'\", והיינו שגם מעשי האדם בזה באים מהקב\"ה והוא ענין בפ\"ע. וגם זה נוגע לידיעת והכרת האדם, שלבושי הטבע ועשיית האדם אינם רק דבר שאין לו מציאות בפ\"ע, כ\"א זה גופא בא מהקב\"ה.",[["311","25","תהלים קד, כא."],["312","26","פ' ראה טו, יח. ובספרי עה\"פ יכול יהא יושב ובטל ת\"ל בכל אשר תעשה."],["313","27","יתרו כ, ט. וראה מכילתא הובאה בדרשות ר\"י אבן שועיב פ' וישב — שהוא מ\"ע. וראה מכיל­תא דרשב\"י יתרו כ, ט. לקו\"ש חי\"א ע' 71 בהערה."],["314","28","משלי י, כב."],["315","29","ראה הקדמה לדרך חיים (ג, א). סהמ\"צ להצ\"צ מצות תגלחת מצורע ספ\"ב ואילך. קונטרס ומעין מי\"ז ואילך. מכ\"ה. ובכ\"מ."],["316","30","מ\"ב ד, ב ואילך."],["317","31","להעיר מלקו\"ש חי\"ח ע' 295 ואילך."],["318","32","ראה דרמ\"צ שם (קז, סע\"א ואילך): וזהו ב' הכוונות טובות שיכוין האדם במו\"מ לבקש רחמים מה' שישלח חסדו כו' ב' בעסקו במו\"מ יכוין שמאמין שהשפע ברכת ה' היא כשאר הנסים הגלויים כמו שהוריד המן וכיוצא (ומה שממשיך \"אלא שהוא עושה לבוש כו' כי כך הוא רצון העליון ב\"ה\", י\"ל שהוא ע\"ד ב' האופנים שבפנים)."],["319","33","ראה בארוכה לקו\"ש חט\"ז ע' 176 ואילך."]]],[1301870110,"ו. ולפי זה מבואר גם הקשר לבעלי הפלוגתא:\nאמרו חז\"ל<sup data-n=\"320\">34</sup> \"הרואה יוחנן בחלום נסי נסים נעשו לו\" (דשם שיש בו נו\"ן א' הרי זה מורה על נס, ושם שיש בו יותר מנו\"ן א' הרי זה מורה על הרבה נסים<sup data-n=\"321\">35</sup>). ולכן ס\"ל לר\"י<sup data-n=\"322\">36</sup>, דפרנסה נכללת בגשמים, כי מצד דרגתו, \"נסי נסים\", ה\"ה רואה בכל ענין שבעולם רק את הנס שבזה. וזהו ענין \"נסי נסים\", שהנס אינו רק בדבר שנראה בו בגלוי שידוד מערכות הטבע, אלא שגם בהנהגת הטבע, הרי מצד דרגת ר' יוחנן הרי הוא בפנימיות רק נס הבא מלמעלה.\nאמנם \"במערבא אמרי\" דמפתח של גשמים הוא מפתח בפ\"ע, ד\"מערבא\", פירושו מקום מסויים בעולם, וארז\"ל<sup data-n=\"323\">37</sup> שכינה במערב. והיינו שאף ש\"מלא כל הארץ כבודו\"<sup data-n=\"324\">38</sup> וארז\"ל<sup data-n=\"325\">39</sup> לית אתר פנוי מיני', שכל מציאות המקום בטל אליו ית', מ\"מ \"שכינה במערב\", ש\"מקום\" זה יש בו השראה מיוחדת, עד שמציאות המקום גופא הוא אלקות<sup data-n=\"326\">40</sup>. ולכן בני \"מערבא\" ס\"ל שגם לבושי הטבע, \"פרנסה\", הם ענין בפ\"ע שהוא בידו של הקב\"ה<sup data-n=\"327\">41</sup>.\nז. ח\"י אלול — יום הולדת שני המ­אורות הגדולים, הבעש\"ט ואדה\"ז<sup data-n=\"328\">42</sup> — חל ברוב השנים בשבוע (או בש\"ק) דפ' תבא<sup data-n=\"329\">43</sup>. וענינם של שני בעלי יום ההולדת, מתאים לב' אופני עבודת ה' הנ\"ל: ע\"י הבעש\"ט בתורת החסידות הכללית; וע\"י אדמו\"ר הזקן בתורת חסידות חב\"ד<sup data-n=\"330\">44</sup>:\nהחידוש שנתגלה ע\"י הבעש\"ט בתורת החסידות הכללית הוא — תוספת חיות כללי בקיום התומ\"צ. ולכן א' מהענינים שהודגשו בתורת החסידות הכללית הוא",[["320","34","ברכות נז, רע\"א."],["321","35","ראה פרש\"י שם ד\"ה חנינא."],["322","36","ומתאים גם להגירסא בדב\"ר פרשתנו ו­מדרש תהלים \"יונתן\", שגם בו ב' נונין (משא\"כ בהשם נחמי' (ל' הא' במד\"ת) שיש בו רק נ' א')."],["323","37","ראה ב\"ב כה, א. במדב\"ר פ\"ב, י. שו\"ע אדה\"ז או\"ח (מהדו\"ת) ס\"ג ס\"ו. מהדו\"ק שם ס\"ז. סצ\"ד ס\"ג."],["324","38","ישעי' ו, ג."],["325","39","תקו\"ז תנ\"ז."],["326","40","ראה סה\"מ תקס\"ב ח\"ב ע' שצד. אוה\"ת מסעי ע' א'שס."],["327","41","להעיר מב' האופנים ודרגות באחדות ה' — ה' אחד מלמטה למעלה וה' אחד מלמעלה למטה (ראה המשך תרס\"ו ע' רכח. רמב. תורת שלום ע' 49 ואילך. 184 ואילך. ועוד): דמצד הענין דהוי' אחד מלמטה למעלה הרי לאחר התהוותם, העו­למות בטלים במציאות בתכלית כמו שהם קודם התהוותם, והיינו שהנבראים אינם שום מציאות, ואמיתית מציאותם הוא כמו שהם מצד למעלה;\nוהוי' אחד מלמעלה למטה, פי' כפי שאלקות מתפשט בכל דבר, והיינו שישנה מציאות, אלא שמציאות העולם גופא הוא אלקות (ראה המשך תרס\"ו שם (ע' רמב), דאופן זה הוא במדריגה נעלית יותר מאופן הא'), ודרגא זו של יחוד מביאה להעבודה שיש לו עסקים בעניני העולם, ועד שנהנה מדברים שבעולם, אבל זה גופא הוא (הנאה) אלקות."],["328","42","שיחת כ\"ק מו\"ח אדמו\"ר (סה\"ש תש\"ג ע' 141 ואילך. ועוד). ולהעיר דח\"י אלול תק\"ה, יום הולדת רבינו הזקן, חל כקביעות שנה זו<sup data-n=\"e10\">*</sup>, ביום ד' תבא."],["329","43","ולפעמים — ביום ב' אחרי פ' תבוא — שמתברך ממנו בתוך ג' ימים."],["330","44","בהבא לקמן ראה בארוכה בלקו\"ש לח\"י אלול (לקו\"ש חי\"ט, חכ\"ד, ועוד). וראה במקומות הנ\"ל בשייכות חי אלול ל\"אני לדודי ודודי לי\" וב' הפתגמים שבזה, והשייכות לתורת הבעש\"ט בענין הביכורים. ועוד."],["e10","*","שנת הדפסת השיחה — תנש\"א. המו\"ל."]]],[1301870111,"ענין האמונה, \"וצדיק באמונתו יחי'\"<sup data-n=\"331\">45</sup>. הרי אמונה זו היא כללית ובבחי' מקיף, והיינו דגם כשהאמונה היא באופן כזה שאינה בבחי' מקיף ממש (שאין לה פעולה על האדם — וגנבא אפום מח­תרתא רחמנא קריא<sup data-n=\"332\">46</sup>), אלא פועלת חיות בכל עניניו, ועד להנהגה בפועל, הרי כל הכחות שלו אינם ענין בפ\"ע אלא פרט בגילוי האמונה.\nואדמו\"ר הזקן בגילוי תורת חסידות חב\"ד חידש (בהמשך לגילוי תורת ה­חסידות הכללית של הבעש\"ט), שלא רק שנקודת האמונה תורגש גם בחב\"ד וכו', אלא שזה נעשה גם ענין בפ\"ע, שכל מציאות חב\"ד (שכל) שבנפשו הוא שמשיג אלקות, ועד\"ז במדות שבלב שמציאותם היא לא רק מקום גילוי נקודת האמונה (פרט בגילוי האמונה), אלא שזהו מצי­אותם גופא, אהבת ה' ויראת ה'.\nוגם זה הוא בהתאם לגילוי אחדות ה'<sup data-n=\"333\">47</sup> כפי שנתגלה ע\"י הבעש\"ט וכפי ש­נמשך ונתגלה ע\"י אדמו\"ר הזקן:\nע\"י הבעש\"ט נתגלה הענין ד\"אין עוד מלבדו\"<sup data-n=\"334\">48</sup> שאין שום מציאות זולתו ית', וכן נרגש גם בעבודת ה', שאין תפיסת מקום לעבודתו, אלא כל כולו הוא גילוי נקודת האמונה שבנפשו שישנו בכ\"א מ­ישראל מצד נשמתו, שלמעלה ממציאות האדם;\nוע\"י אדמו\"ר הזקן נתגלה הענין ד­אחדות ה' גם כמו שהוא מצד העולם, שלא רק שמציאות העולם אינה בסתירה לאחדותו ית', אלא שע\"י העולם מתגלה העומק דה' אחד, שמציאות העולם מיו­חדת בו ית', וכמבואר בארוכה בשער היחוד והאמונה לאדמו\"ר הזקן.\nוכן הוא גם בעבודת האדם, שלא רק שכל כחות שלו הם בהתאם לנקודת האמונה בה' אחד, אלא דזהו כל מציאות השכל שבו, שהשכל עצמו מצד ענינו מכיר ומרגיש אחדות ה' מצד מציאותו גופא, כי מציאות השכל גופא אינו דבר הנפרד ממנו ית'. וכן הוא בכל כחות נפשו.\nודבר זה בא דוקא ע\"י יגיעת ועבודת האדם, עבודה בכח עצמו דוקא, להבין ול­השיג אחדות ה' גם בשכלו ועד לשכל שבנפשו הבהמית, וע\"י התבוננות הרי זה נמשך גם במדותיו, אהבת ה' ויראת ה', באופן שהאהבה והיראה שייכות למצי­אות המדות שבלב, וכן הוא בכל כחות נפשו, שנראה וניכר שאמיתית המציאות של כל כח שבנפש מהותו הוא אלקות.\nוע\"י יפוצו מעינותיך (של הבעש\"ט) חוצה<sup data-n=\"335\">49</sup>, שנעשה (בעיקר) ע\"י המשכתו בחב\"ד שבנפש בתורת חסידות חב\"ד, ו­ממנה למדות ולבא פליג לכולא שייפין<sup data-n=\"336\">50</sup>, קאתי מר דא מלכא משיחא<sup data-n=\"335\">49</sup>, ותיכף ומיד ממש.\n<span data-k=\"q\">(משיחת ש\"פ בלק תשמ\"א)</span>",[["331","45","חבקוק ב, ד. וראה מכות בסופה (כד, א). תניא פל\"ג (מב, ב). וראה לקו\"ד ח\"א קמא, ב."],["332","46","ברכות סג, א (בגי' הע\"י). וראה כד הקמח מערכת בטחון (ע' עד). לקו\"ת ואתחנן ז, א. פרש­תנו מב, ד. ועוד. וראה גם בהנסמן במ\"מ ללקו\"ת דברים א, א."],["333","47","ראה גם לקו\"ש ח\"ט ע' 157 ואילך."],["334","48","ואתחנן ד, לה."],["335","49","דברי המלך המשיח להבעש\"ט — אגה\"ק הידועה של הבעש\"ט (נדפסה בסו\"ס בן פורת יוסף. בריש ספר כש\"ט. ובכ\"מ)."],["336","50","ראה זח\"ג שלח קסא, א­ב. רכא, ב. אגה\"ק סל\"א. תו\"א בראשית ז, ד. ועוד."],["335","49","דברי המלך המשיח להבעש\"ט — אגה\"ק הידועה של הבעש\"ט (נדפסה בסו\"ס בן פורת יוסף. בריש ספר כש\"ט. ובכ\"מ)."]]],[1301870112,"<h3>ר\"ה (תשנ\"ב)</h3>\nא. כתב רבינו הזקן בסידורו ב\"סדר תקיעות\": \"אחר קריאת התורה<sup data-n=\"338\">1</sup> יכין עצ­מו לתקוע בשופר ויאמר<sup data-n=\"339\">2</sup> קאַפּיטיל זה [מזמור מז שבתהלים] ז' פעמים\".\nובפשטות אומר כאן אדמו\"ר הזקן ב' ענינים שונים: (א) \"יכין עצמו לתקוע ב­שופר\"; (ב) \"יאמר קאפיטיל זה ז' פעמים\".\n[ובפרט שמקורם של שני הענינים הוא בב' מקומות שונים, דמ\"ש \"אחר קריאת התורה יכין עצמו לתקוע בשופר\" מקורו בפרי עץ חיים<sup data-n=\"340\">3</sup> ומשנת חסידים<sup data-n=\"341\">4</sup>, וב­מקומות אלו לא הובא ע\"ד אמירת מזמור מז; ואילו ענין אמירת מזמור מז מקורו בסידור האריז\"ל<sup data-n=\"342\">5</sup>, אבל שם (אף שהובאו הכוונות לתקיעת שופר) לא נמצא כלום ע\"ד ההכנה לתק\"ש — \"אחר קריאת התו­רה יכין עצמו לתקוע בשופר\"].\nוצ\"ע, מדוע סתם אדמו\"ר הזקן \"יכין עצמו לתקוע בשופר\", מבלי לפרש אופן ההכנה.\nוהנה בפע\"ח ומשנת חסידים שם ממ­שיך \"(יכין עצמו כו' לתקוע בשופר) לעורר הזעיר אנפין כו'\", ומפרט הכוונה הכללית (ע\"ד הסוד) של תק\"ש, שמזה מובן, שההכנה (\"יכין עצמו\") שייכת לכוונת דתק\"ש, שצריך להכין את עצמו באופן שע\"י תק\"ש וכוונות שלו יתעורר הז\"א כו'.\nואם הטעם שלא העתיק אדמו\"ר הזקן כוונות תק\"ש בסידור, הוא כמנהגו בסי­דורו בכלל שלא העתיק כוונות האריז\"ל, לפי שאינם דבר השווה לכל נפש<sup data-n=\"343\">6</sup> — לא",[["338","1","לכאורה צ\"ע מאי קמ\"ל. ודוחק לומר ששולל בזה המנהג (הובא בברכ\"י או\"ח ר\"ס תקפח, ועוד) שתוקעין בבוקר קודם התפלה, או ששולל סברא לתקוע קודם קה\"ת מצד זריזין מקדימין כו' (אף שאין מקדימין אותה קודם התפלה — ראה תוס' ר\"ה לב, ב) — שהרי \"המנהג הפשוט\" לתקוע אחר קה\"ת (רמב\"ם הל' שופר פ\"ג ה\"י. ובמגיד משנה שם \"בכל העולם\"). ובכל אופן, שלילת סברא זו אין מקומה בסידור.\nוי\"ל שמרמז על השייכות דתק\"ש לענין מ\"ת, כמ\"ש הרס\"ג (הובא באבודרהם) שזהו א' מהטעמים דתק\"ש, לזכור קול השופר דמ\"ת (וכפי שאומרים בפסוקי שופרות). וי\"ל דזהו טעם המנהג (רמ\"א (ואדה\"ז) או\"ח סתקפ\"ה ס\"א (ס\"ג)) לתקוע \"על הבימה במקום שקורין\"."],["339","2","צ\"ע, דמשמע שרק בעל התוקע אומרו, כהתחלת הלשון \"יכין עצמו לתקוע בשופר ויאמר כו'\"<sup data-n=\"e11\">*</sup>, ובפרט שגבי אמירת שש הפסוקים מדייק \"התוקע מתחיל וגם הקהל יאמרו כו'\". והוא היפך הפשט לומר ד\"יכין עצמו לתקוע בשופר\" קאי גם על כאו\"א מהשומעים!"],["340","3","דפוס דובראוונא ריש שער השופר (שער כו) — כצויין ב\"שער הכולל\" דלקמן הערה 9. — ובדפוס קארעץ שנדפס צילום ממנו ליתא."],["341","4","מס' ר\"ה פ\"ג מ\"א. — ולהעיר, שלשון אדה\"ז היא לשון המ\"ח (משא\"כ בפע\"ח שם הוא בשינויים קלים)."],["342","5","להעיר ממס' סופרים (פי\"ט ה\"ב) \"ובר\"ה אומר כל העמים תקעו כף\". אבל שם קאי על שיר של יום (ע\"ד שיר הלוים בביהמ\"ק) — ראה נחלת יעקב שם (ושם רפי\"ח) — ולא בקשר עם תקיעת שופר."],["343","6","ראה \"שער הכולל\" לאאזמו\"ר בהקדמתו. — וראה מג\"א ר\"ס צח (ובאלי' רבה שם סק\"א). אבל להעיר, שאדה\"ז לא הביאו בשולחנו שם."],["e11","*","משא\"כ בסי' האריז\"ל שליתא שם ההקדמה \"יכין עצמו כו'\", וגם הלשון שם \"צריך לומר\" (לא \"ויאמר\"), ואולי בדוחק יש לפרשו דקאי על כאו\"א."]]],[1301870113,"הו\"ל להעתיק גם תחלת ל' הפע\"ח ומ\"ח \"יכין עצמו\"; ואם ס\"ל שגבי תק\"ש הוי יוצא מן הכלל והכוונות דתק\"ש שייכות לכל נפש<sup data-n=\"344\">7</sup>, הו\"ל להעתיק הכוונות (בכל­לות, עכ\"פ) בפירוש (ע\"ד שמצינו בהגדה של פסח, שהעתיק הכוונות דשפיכת היין באמירת המכות כו'<sup data-n=\"345\">8</sup>).\nב. והנה אאזמו\"ר בספרו \"שער ה­כולל\" (על סידור אדה\"ז)<sup data-n=\"346\">9</sup> פי', דמ\"ש אדמו\"ר הזקן \"יכין עצמו לתקוע בשופר ויאמר כו'\" — \"ההכנה היא [בזה גופא] שיאמר זה המזמור ז' פעמים\" [היינו שהו' (ד\"ויאמר\") היא ו' הפירוש]. כי טעם אמי­רת מזמור זה הוא לפי שעי\"ז מהפכין מדת הדין למדת הרחמים (כמבואר ב­סידור האריז\"ל שם, ומיוסד על דברי המדרש<sup data-n=\"347\">10</sup>), והיא פעולת תק\"ש, כמבואר בפע\"ח<sup data-n=\"348\">11</sup> שע\"י השופר \"מתעלין<sup data-n=\"349\">12</sup> ומת­מתקין הדינים והגבורות דשם אלקים\". ונמצא, שאמירת מזמור זה ז' פעמים היא מהכוונות דתק\"ש.\nויש להוסיף ביאור בזה, בהקדם ענין כללי בשייכות לסידור אדמו\"ר הזקן, דאף שקבע את נוסח התפלה ע\"פ כוונות האריז\"ל, שיהי' מדוייק כפי היוצא ע\"פ קבלה (נוסף לזה שיהי' מכוון גם ע\"פ הדקדוק והלשון)<sup data-n=\"350\">13</sup>, מ\"מ לא העתיק ב­סידורו הכוונות עצמן, לפי שאינו דבר השייך לכל נפש כנ\"ל.\nבכלל משמע, שענין הכוונות שייך רק ליחידי סגולה (היודעים לכוון כוונות אלו), אבל יותר נראה לומר, דזה גופא ש­אדמו\"ר הזקן קבע נוסח התפלה (שהוא נוסח שווה לכל נפש) מכוון ע\"פ כוונות האריז\"ל, הוא לפי שע\"י עצם התפלה בנוסח זה (גם ע\"י אותם שאינם יודעים מענין הכוונות) נפעלים בפועל ההמ­שכות וכו' שבכוונות האריז\"ל<sup data-n=\"351\">14</sup>.\nומטעם זה גופא תיקן אדמו\"ר הזקן נוסח תפלה המיוסד על כוונות האריז\"ל, כדי שכל ישראל יהיו שייכים לענין כוו­נות אלו.\nוי\"ל שהוא ע\"ד מ\"ש אדמו\"ר הזקן בהל' ת\"ת שלו<sup data-n=\"352\">15</sup> לענין לימוד חלק הסוד",[["344","7","ובפרט דמ\"ש \"יכין עצמו\" קאי בפשטות על הבעל תוקע, והרי \"ראוי ליתן לתקוע לצדיק והגון\" (שו\"ע אדה\"ז או\"ח סתקפ\"ה ס\"ג). ובסי' האריז\"ל (קול יעקב) \"צריך להדר אחר תוקע היודע כוונות השייכים לתק\"ש\". וראה מטה אפרים שם. ולהעיר גם מפע\"ח שם (ועוד) \"סוד השופר צריך לידע מי הוא התוקע כו'\".\nולהעיר שאדה\"ז העתיק בסידורו ה\"יהי רצון\" (לבעל תוקע) קודם תקיעות (שמקורו בפע\"ח (הנ\"ל הערה 3) שם, וסידור האריז\"ל במקומו). אלא שהביא ג\"כ ה\"יהי רצון\" שאחרי תקיעות, שכל הקהל נוהגים לאומרו."],["345","8","וראה שער הכולל פמ\"ח ס\"ק לג. הגש\"פ עם לקוטי טעמים ומנהגים במקומו."],["346","9","פמ\"ג סק\"א."],["347","10","מדרש תהלים במקומו. ועוד. הובאו ב­שער הכולל שם."],["348","11","שער השופר שם."],["349","12","ל' שער הכולל שם."],["350","13","ראה בכ\"ז הסכמת המהרי\"ל (אחי אדה\"ז) לסידור אדה\"ז (בסידור עם דא\"ח הוצאת קה\"ת — שכג, ב). הקדמת שער הכולל. ועוד."],["351","14","כדמשמע ממ\"ש כ\"ק אדמו\"ר מהורש\"ב נ\"ע (אגרות קודש שלו ח\"א ע' יז­יח), דאין לומר שאדה\"ז השמיט דברים הנמצאים בפע\"ח כו' לפי שאינם שייכים רק ליודעים ועוסקים בחכמת הקבלה. ע\"ש. ושם, ש\"אפילו כולנו חכמים כולנו יודעים את הקבלה צריכים אנו להתפלל כמצווה עלינו בנוסח רבינו הגדול ז\"ל, עליו אין להוסיף וממנו אין לגרוע כו'\"."],["352","15","פ\"א ס\"ד."]]],[1301870114,"שבתורה, \"שכל נפש צריכה לתיקונה לעסוק בפרד\"ס כו' צריך לבוא בגלגול עד שישיג וידע כל מה שאפשר לנשמתו להשיג מידיעת התורה הן בפשטי ההל­כות הן ברמזים ודרשות וסודות\", היינו שכל נפש צריכה לעסוק בהשגת סודות התורה — דמעין זה ואולי ביתר שאת הוא בענין כוונות התפלה ע\"ד הסוד, שהן שייכות לכל נפש, אלא שרוב הצבור (ש­אין יודעים לכוין הכוונות בפועל) שייכים רק לה\"נפעל\", שע\"י התפלה בנוסח זה נפעלים הענינים. וידועים דברי כ\"ק מו\"ח אדמו\"ר<sup data-n=\"353\">16</sup>, \"ידוע ומקובל<sup data-n=\"354\">17</sup>. . אשר אלו שאין דעתם יפה לכוון מפני העדר הידי­עה כו' מספיק שיכוונו כוונה כללית: להיות תפלתו נשמעת לפניו ית' עם כל הכוונות המבוארות בספרי קבלה\".\nועד\"ז הוא בענין הכוונות דתק\"ש, שהן שייכות לכל נפש, אלא שפעולת הענינים — לרוב הציבור<sup data-n=\"355\">18</sup> (שאין יודעים לכוון כל הכוונות<sup data-n=\"356\">19</sup>) היא ע\"י אמירת מזמור מז שבתהלים ז' פעמים.\nג. אבל קשה לפרש כן כוונת אדמו\"ר הזקן, כי: (א) פשטות הלשון \"יכין כו' ויאמר\", משמע שהם ב' ענינים. (ב) ועיקר: כיון שלפי הנ\"ל אין כאן הכנה מלבד אמירת מזמור מז ז' פעמים — לא הול\"ל אלא העיקר בנוגע למעשה — \"יאמר קאַפּיטיל זה ז' פעמים\", ולמה הק­דים להעתיק ממ\"א \"יכין עצמו\"?\nואף את\"ל שבלשון זו מודגש שע\"י אמירת המזמור נפעל ענין הכוונות ד­תק\"ש (כנ\"ל) — למאי נפק\"מ הדגשה זו בסידור השווה לכל נפש? והרי לא מצינו במקומות אחרים בסידור שאדמו\"ר הזקן ירמז כיצד נפעלים הענינים שבכוונות, ורק קבע נוסח התפלה בהתאם לזה.\nומסתבר לומר, דמ\"ש אדמו\"ר הזקן בלשון סתמי \"יכין עצמו\", אין כוונתו ל­הכנה השייכת לכוונות דתק\"ש שבפע\"ח ומשנת חסידים (שלא העתיקן בסידורו), אלא כפשטות הלשון, שהבעל תוקע צריך להכין את עצמו לתק\"ש, וכמובא גם במטה אפרים<sup data-n=\"357\">20</sup> ע\"ד המנהג לעשות \"הכ­נה רבה\" לתק\"ש. ולא פירט אדמו\"ר הזקן שום הכנה פרטית, כיון שאינו דבר ה­שווה לכל נפש, דיש ריבוי אופנים שב­יכולתם לעורר את האדם ולהכינו לתק\"ש (וכפי שהובאו כמה מהם במטה אפרים שם), וכל חד וחד לפום שיעורא דילי' צריך להכין את עצמו לתק\"ש.\nד. אלא שעדיין אין זה מתרץ השאלה — מדוע רק הכא גבי מצות תק\"ש כ' אדה\"ז שצריכים להכין את עצמו לקיום המצוה? והרי כל קיום כל מצוה כדבעי הוא כשזהו בכוונה הראוי' (דמצוה בלי כוונה היא כגוף בלי נשמה<sup data-n=\"358\">21</sup>), ומ\"מ לא מצינו שאדה\"ז יכתוב בסידורו גבי עוד מצות שהובאו בסידור (כמו ציצית, תפי­לין, נטילת לולב ועוד) שהאדם צריך להכין את עצמו קודם עשיית המצוה.",[["353","16","\"היום יום\" י\"א אד\"ר (והוא מאגרות קודש שלו ח\"ג ע' קמד. ע\"ש)."],["354","17","ראה גם של\"ה מס' תמיד עניני תפלה (רנא, ב בהגה\"ה ד\"ה על חוט). ועוד."],["355","18","כולל כמה מבעלי תוקע שאינם שייכים לכוין כוונות השופר ע\"ד הסוד."],["356","19","משא\"כ אלה שיודעים לכוין, צריכים לכוין בפועל כדי שיפעלו כו' — ראה \"היום יום\" ב' תשרי (לענין אמירת אנא בכח קודם תק\"ש). ולהעיר מאגרות קודש אדמו\"ר האמצעי (ע' רסו­ז)."],["357","20","סי' תקפה."],["358","21","תניא פל\"ח (נ, א), ושם \"תפלה או שאר ברכה\", ולהלן שם (נא, א) \"וכוונת המצות. . שהיא כנשמה לגוף\"."]]],[1301870115,"לכאורה יש לבאר זה ע\"פ מ\"ש ה­רמב\"ם<sup data-n=\"359\">22</sup>, ד\"אע\"פ שתקיעת שופר בראש השנה גזירת הכתוב, רמז יש בו, כלומר עורו ישנים משנתכם כו' וחפשו במע­שיכם וחזרו בתשובה כו'\", דלכאורה יש לדייק, אמאי הביא הרמב\"ם דברי אגדה אלה בספר הי\"ד שהוא ספר הלכה? ומש­מע לכאורה, ש\"רמז\" זה נוגע להלכה, דאין תקיעת שופר רק מצוה שבמעשה (שמיעת קול שופר) אלא גם מצוה שבלב, שקול השופר צריך לעורר את האדם לתשובה, ומבלי זה חסר בעצם קיום המצוה [וע\"ד (ולא ממש) דברי הב\"ח<sup data-n=\"360\">23</sup> הידועים לענין ציצית תפילין וסוכה, ש­קיום מצות אלו תלוי גם בכוונתן]<sup data-n=\"361\">24</sup>, ומהאי טעמא כ' אדה\"ז שצריך להכין עצמו לתק\"ש, כיון שבלי זה חסר בעצם קיום המצוה.\nאבל דוחק לפרש כן, כי לא מצינו בספרי הפוסקים שבלי כוונה והתעוררות תשובה<sup data-n=\"362\">25</sup> חסר בקיום מצות תקיעת שופר, וגם ברמב\"ם קשה לפרש כן, דא\"כ הו\"ל להביא ענין זה בהל' שופר, ומזה שהביאו רק בהל' תשובה ולא בהל' שופר מוכח שאין \"רמז\" זה חלק מקיום מצות שו­פר<sup data-n=\"363\">*25</sup>.\nה. ויש לומר הביאור בזה, בהקדם תמי' כללית בסידור אדה\"ז: בס' קבלה איתא שקודם כל מצוה צריכים לומר \"לשם יחוד קוב\"ה ושכינתי'\"<sup data-n=\"364\">26</sup>, ובכמה סידורים הובא נוסח זה לפני קיום כמה מצות. ומצינו בזה דבר פלא בסידור אדה\"ז, שלא קבע לומר \"לשם יחוד\" לפני קיום מצוה (כפי שמצינו בהמצוות ש­הובאו בסידורו), אבל לאידך קבע לאומרו בכל יום בתפלה קודם ברוך שאמר.\nומבואר בזה<sup data-n=\"365\">27</sup>, ד\"אנחנו אומרים לשם יחוד קודם התפלה ויוצאים בזה על כל היום בקיום המצות כו'\"<sup data-n=\"366\">28</sup>.\nאבל עדיין דורש ביאור: אם זוהי הנהגה השייכת לכל אדם, למה לא קבע לאומרו קודם עשיית כל מצוה, ואם אינו דבר השווה לכל נפש, אמאי קבעו לפני ברוך שאמר<sup data-n=\"367\">29</sup>?\nוי\"ל עפמשנ\"ת לעיל (סעיף ב), דב­עצם ס\"ל לאדה\"ז שענין הכוונות (גם) ע\"ד הסוד שייך לכל נפש, אלא שזהו רק בנוגע לה\"נפעל\", שלכל נפש ניתן הכח לפעול את הענינים וההמשכות המפו­",[["359","22","הל' תשובה פ\"ג ה\"ד."],["360","23","לטאו\"ח ס\"ח, סתרכ\"ה."],["361","24","להעיר מל' הש\"ס (ר\"ה כח, ריש ע\"ב) \"אבל הכא זכרון תרועה כתיב\", ובר\"ח שם (וראה גם רמב\"ן במלחמות שם, ועוד) \"הכא בענין תקיעות כוונת הלב בעינן\". ומשמע דענין הכוונה בתק\"ש הוא יותר מהא דמצות בכלל צריכות כוונה."],["362","25","משא\"כ הכוונה לצאת י\"ח — רמב\"ם הל' שופר פ\"ב ה\"ד. טושו\"ע או\"ח סתקפ\"ט ס\"ח. שו\"ע אדה\"ז שם ס\"ה ואילך."],["363","*25","וראה לקו\"ש ח\"ד ע' 1355 בהערה."],["364","26","כ\"ה בלקו\"ת ואתחנן ט, סע\"א. ר\"ה נה, ג. וראה פע\"ח שער הזמירות ספ\"ה. ס' הליקוטים ס\"פ ראה. שער רוה\"ק (בדפוס ירושלים, תער\"ב — יב, ב). כסא מלך להקדמת ת\"ז ד\"ה ואי תימרון. ועוד — ראה הנסמן בסה\"מ מלוקט ח\"ב ע' פב הערה 60."],["365","27","סה\"מ תרנ\"ז ע' קצח. ועד\"ז בסה\"מ עטר\"ת ע' תקיח."],["366","28","ולהעיר ממשנ\"ת במ\"א (לקו\"ש שם ע' 1128 ואילך) בטעם שבכמה מצות א\"צ כוונה, גם כוונה לצאת י\"ח (ראה שו\"ע אדה\"ז או\"ח סתע\"ה סכ\"ח. ועוד), כי הכוונה בתחילת היום \"לעשות רצון אביך שבשמים\" נמשכת על הפעולות דכל היום כולו. ע\"ש."],["367","29","וראה השקו\"ט בשער הכולל פ\"ו סק\"ב."]]],[1301870116,"רשים בכוונות המצות, אף שמעשה ה­כוונות אינו דבר השווה לכל נפש.\nועפ\"ז נראה לומר עוד, שס\"ל לאדה\"ז שצריך אדם לומר \"לשם יחוד\" עכ\"פ פעם אחת בכל יום, כדי לפעול \"יחוד קוב\"ה ושכינתי'\" בקיום כל מצוה ומצוה במשך כל היום כולו. דאף שאינו דבר השווה לכל נפש לכוין \"לשם יחוד כו'\" בקיום כל מצוה ומצוה במשך כל היום כולו, מ\"מ, בידו של כאו\"א לכוין זה (עכ\"פ כל חד וחד לפום שיעורא דילי'<sup data-n=\"368\">30</sup>) בשעת התפלה, ואמירה וכוונה זו בתחי­לת היום הוי פעולה נמשכת לכל הדברים הנעשים במשך יום זה, כנ\"ל. ולכן קבע לאומרו בתפילת הבוקר, ובזה גופא, ב­תחילת התפלה, קודם ברוך שאמר.\nו. לפי הקדמה זו יש לבאר ג\"כ שיטת אדה\"ז בענין הכוונות לתק\"ש:\nמ\"ש אדה\"ז שצריך להכין את עצמו לתק\"ש ולא די בשמיעת קול השופר ל­חוד, מובן, כי בסידור אדה\"ז שנקבע ע\"ד הסוד, נוגע ביותר ענין ההכנה והכוונה שבמצוות. אלא שכיון שזהו סידור השווה לכל נפש, לכן, גם בענין זה נקט אדה\"ז דרך השווה לכל נפש, שלא חייב ענין ההכנה לפני כל מצוה ומצוה אלא רק לפני תקיעת שופר.\nדכשם שהוא בנוגע לכל יום ויום, שאדה\"ז קבע לומר \"לשם יחוד\" פ\"א ב­תחילת היום, הפועל על כל היום כולו כנ\"ל, מעין זה הוא לענין כללות השנה כולה, שבמצוה כללית זו דתקיעת שופר<sup data-n=\"369\">31</sup> שבתחילת השנה דרוש ענין ההכנה, ועי\"ז נמשך ג\"כ לכל השנה כולה.\nדהנה מבואר בכ\"מ, דתק\"ש היא מצוה כללית הנוגעת לעבודת האדם במשך כל השנה כולה, דראש השנה נקרא \"ראש\" (ולא תחילת השנה) לפי שהוא כמו ראש המנהיג את הגוף כולו<sup data-n=\"370\">32</sup>, וכך עבודת ה­אדם במשך הזמן דראש השנה משפיעה על עבודתו במשך כל השנה כולה. ובזה גופא הרי \"מצות היום בשופר\"<sup data-n=\"371\">33</sup>, שהיא היא המצוה (והעבודה) העיקרית דראש השנה. ולכן אף שענין הכוונה והכנה בכל מצוה אינו דבר השווה לכל נפש, מ\"מ, גבי תקיעת שופר שהיא בגדר \"ראש\" לכל השנה כולה, צ\"ל ההכנה בגלוי אצל כל ישראל<sup data-n=\"372\">34</sup>.\nועפ\"ז יש לפרש בעומק יותר לשון אדה\"ז \"יכין עצמו לתקוע בשופר\", ולא פירט במה היא ההכנה — שאין זה רק לפי שזה תלוי בכל חד וחד לפום שיעורא דילי' (כנ\"ל סעיף ג), אלא מפני שזהו בהתאם לתוכן העבודה דתקיעת שופר, שהיא העבודה הראשונה בתור \"ראש\" לעבודת האדם במשך כל השנה כולה. שתוכן \"ראשית\" זו היא — קבלת עול מלכות שמים, קבלת עול כללית<sup data-n=\"373\">35</sup>, והיינו שאין עבודת היום רק קבלת החלטות טובות לשפר את עצמו בענינים פרטיים",[["368","30","להעיר מתניא פמ\"א (נז, ב ואילך) \"ואף שלהיות כוונה זו אמיתית כו' מ\"מ יש לכל אדם להרגיל עצמו בכוונה זו כו'\". ע\"ש."],["369","31","ובפרט ע\"פ המבואר בלקו\"ת ר\"ה שם, דההמשכה הכללית דר\"ה על כל השנה וענין תק\"ש שייך לכוונת \"לשם יחוד כו'\" שאומרים בכל מצוה. ע\"ש."],["370","32","ראה לקו\"ת ר\"ה רד\"ה תקעו הא'. ועוד. עטרת ראש בתחלתו. ובכ\"מ."],["371","33","משנה ר\"ה כו, ב."],["372","34","אף שפשטות ל' אדה\"ז קאי על הבעל תוקע (כנ\"ל הערה 2), הרי מובן שגם כאו\"א צריך להכין עצמו כו' (וראה מטה אפרים שם)."],["373","35","ראה סה\"מ תש\"ד ע' 5 ואילך. ובכ\"מ."]]],[1301870117,"בתורה עבודה וגמ\"ח, אלא היא מסירה כללית לה' מעומק הנפש.\nוזהו מ\"ש אדה\"ז \"יכין עצמו לתקוע בשופר\" ולא כ' שום ענין פרטי, כי זהו כל התוכן דתקיעת שופר, הכנה כללית ל­עבודת השם במשך כל השנה כולה של­מעלה מפרטים.\n<span data-k=\"q\">(משיחת ש\"פ האזינו תשל\"א)</span>"],[1301870118,"<h3>אגרת התשובה א<sup data-n=\"e2\">*</sup></h3>\nא. באגרת התשובה פ\"ד מבאר אד­מו\"ר הזקן, שמ\"ש<sup data-n=\"374\">1</sup> \"כי חלק הוי' עמו\" היינו שבנ\"י הם \"חלק משם הוי' ב\"ה\"<sup data-n=\"375\">2</sup> — דכמו שיש ד' אותיות בשם הוי', שהם היו\"ד ספירות ש\"נכללות ונרמזות בשם הוי' ב\"ה\"<sup data-n=\"376\">3</sup>, כך יש דוגמת ד' אותיות אלו בכל נפש מישראל — ומבאר בפרטיות איך נכללות ונרמזות היו\"ד ספירות בד' אותיות השם:\n\"היו\"ד שהיא בחי' נקודה לבד מרמזת לחכמתו ית'. . ואחר שבאה [הנקודה] לבחי' התפשטות וגילוי ההשגה וההבנה לעלמין סתימין נכללת ונרמזת באות ה\"א שיש לה בחי' התפשטות לרוחב המורה ומרמז על הרחבת הביאור וההבנה וגם לאורך המורה על בחי' ההמשכה וההש­פעה מלמעלה למטה לעלמין סתימין. ואח\"כ כשנמשכת המשכה והשפעה זו יותר למטה לעלמין דאתגליין, וכמו ה­אדם שרוצה לגלות חכמתו לאחרים ע\"י דיבורו עד\"מ, נכללת ונרמזת המשכה זו באותיות ו\"ה, כי הוי\"ו מורה על ההמ­שכה מלמעלה למטה, וגם המשכה זו היא ע\"י מדת חסדו וטובו ושאר מדותיו ה­קדושות הנכללות בדרך כלל במספר שש. . (ו)מדת מלכותו ית' נקרא בשם דבר ה'. . ונכללת ונרמזת באות ה\"א אחרונה כו'\" [ואח\"כ מפרש דוגמתן בנפש האדם, כדלקמן].\nומבאר אאמו\"ר בהערותיו לתניא<sup data-n=\"377\">4</sup>, דמ\"ש אדה\"ז (בביאור ההמשכה הנרמזת באות וי\"ו דשם הוי') \"חסדו וטובו\" — \"נקט ב' לשונות, חסד וטוב, הוא ההתחלה והסוף דהששה מדות, שהתחלתן חסד וסופן יסוד הנק' טוב\"<sup data-n=\"378\">5</sup>. כלומר: אין ה­כוונה בתיבת \"וטובו\", כדמשמע בפשטות, שזהו חלק ופרט במדת החסד, אלא \"טו­בו\" קאי על מדת היסוד, \"הסוף דהששה מדות\".\nולכאורה צריך להבין: אמאי נחית אדה\"ז לפרט מדת היסוד בפ\"ע, ולא הס­תפק בזה שהיא נכללת ב\"שאר מדותיו הקדושות\"?\nזה שמפרט \"מדת חסדו\" (ולא כתב סתם \"המשכה זו היא ע\"י מדותיו הקדו­שות\"), יש לבאר בפשטות, שנקט המדה הראשונה<sup data-n=\"379\">6</sup> [וע\"ד שמצינו לעיל בשער היחוד והאמונה<sup data-n=\"380\">7</sup>, כשמדבר ע\"ד המשכת",[["374","1","האזינו לב, ט."],["375","2","ל' אדה\"ז שם (צג, סע\"ב)."],["376","3","שם צד, ריש ע\"ב ואילך."],["377","4","לקוטי לוי\"צ על תניא — ריש ע' ל."],["378","5","\"כמ\"ש (ישעי' ג, י) אמרו צדיק כי טוב וצדיק הוא יסוד\" (לקוטי לוי\"צ שם. ומסיים: \"בקר דאברהם ובקר דיוסף בזוה\"ק פ' בלק דר\"ד ועיין בביאורי הזהר שם\" (לאדמו\"ר האמצעי — קט, א ואילך). — וראה לקמן הערה 30)."],["379","6","והרי אח\"כ מעתיק (בפירוש) מהפסוק רק \"לך הוי' הגדולה\" (שכנגד חסד) והשאר מרמז ב\"וכו'\"."],["380","7","פ\"ז (פד, סע\"א)."],["e2","*","ביאורים בלקוטי לוי\"צ על אגה\"ת. הבי­אורים על חמשה קטעים הראשונים שבלקוטי לוי\"צ נדפסו בלקו\"ש חי\"ט (ע' 391 ואילך), ולשלימות הענין נדפסו גם להלן בההוספות (בתרגום ללה\"ק). המו\"ל."]]],[1301870119,"המדות, אומר \"חסד ורחמים<sup data-n=\"381\">8</sup> ושאר מדותיו הקדושות\"] — אבל מה נוגע ל­פרט מדת היסוד, \"הסוף דהששה מדות\"?\nובפרט שלקמן<sup data-n=\"382\">9</sup> בביאור ד' אותיות בנפש האדם, כשמזכיר ענין המדות, נקט \"אהבה ויראה ותולדותיהן\", הרי שמפרט רק עיקרי המדות<sup data-n=\"383\">10</sup>, וא\"כ גם כאן הו\"ל לפרט<sup data-n=\"384\">11</sup> \"חסד וגבורה\"<sup data-n=\"385\">12</sup> (ולא \"הסוף דה­ששה מדות\").\nגם צע\"ק לפ\"ז לשון אדה\"ז \"מדת חס­דו וטובו\" — \"מדת\" ל' יחיד, והרי ב\"חסדו וטובו\" כוונתו לשתי מדות, חסד ויסוד, והול\"ל \"מדות\" (ל' רבים)?\nב. ויש לומר, שבפירוש אאמו\"ר (ד­\"טובו\" כאן קאי על מדת היסוד, ולא שהוא פרט במדת החסד), נרמז תירוץ על תמי' כללית בתוכן הביאור באגה\"ת כאן בד' אותיות שם הוי' למעלה ובנפש האדם.\n[וכמשנ\"ת במ\"א<sup data-n=\"386\">13</sup> ע\"ד הערות אאמו\"ר אלו — שנרשמו על גליון ספריו בהיותו בגולה, ונכתבו בקיצור נמרץ מפני הצמ­צום בנייר ודיו וכו' — שנוסף על דיוקי הלשונות שנתבארו בהן, הנה בכמה מקומות נרמז בהן ביאור בתוכן הכללי של הענין].\nדהנה בביאור אות וי\"ו דשם הוי' כתב אדה\"ז, כנ\"ל, דקאי על מדותיו ית' [\"הנכללות. . במספר שש\"], אבל אח\"כ בנפש האדם כתב<sup data-n=\"387\">14</sup> ד\"אותיות וא\"ו ה\"א\" קאי על \"עסק התורה והמצות בקול ודבור או מעשה\" [וא\"ו — קול ודבור, וה\"א — מעשה], ואילו מדות האדם באו כפרט בביאור אות ה\"א (ראשונה) שקאי על בינה (התבוננות בגדולתו ית' בהר­חבת הדעת כו') — \"שיש לה רוחב, וגם אורך המורה על ההמשכה מלמעלה ל­מטה להוליד מבינתו והתבוננותו בגדולת ה' אהבה ויראה ותולדותיהן במוחו ותע­לומות לבו ואח\"כ בבחי' התגלות לבו\".\nולכאורה תמוה: כיון שד' אותיות שם הוי' דנפש האדם מתאימות לד' אותיות דשם הוי' (\"כי חלק הוי' עמו. . חלק משם הוי' ב\"ה\", וכנ\"ל) — מהו טעם החי­לוק ביניהם, שההמשכה שע\"י \"מדותיו הקדושות\" נרמזת בה\"אורך\" של אות וי\"ו, ואילו בנפש האדם, \"ההמשכה מל­",[["381","8","צע\"ק הטעם שמפרט גם \"רחמים\". וראה שם פ\"ח (פה, א. שם, ריש ע\"ב) \"ומדת חסדו ורחמנותו ושאר מדותיו. . מדת חסד ורחמים וכיוצא בהן\". ואכ\"מ."],["382","9","בסוף הפרק (צה, א)."],["383","10","ראה תניא ח\"א ספ\"ג \"ושאר המדות כולן הן ענפי היראה והאהבה ותולדותיהן\"."],["384","11","אבל י\"ל, דזה שמפרט \"חסד\" אינו רק מפני שהיא המדה הראשונה, אלא<sup data-n=\"e12\">*</sup> לפי שכאן בא לבאר ענין \"ההמשכה מלמעלה למטה\" הנעשה ע\"י \"מדותיו הקדושות\", ועיקר ענין ההמשכה והגילוי הוא במדת החסד, שהרי זהו כל ענינה של מדת החסד — ענין ההשפעה, המשכה וגילוי [וענין ה\"המשכה\" שב\"שאר מדותיו הקדושות\" הוא מצד מדת החסד הכלולה בהן, וכידוע שמדת החסד \"אזיל\" עם כל המדות — ראה לקו\"ת האזינו עו, ב (וש\"נ). ועוד]."],["385","12","או גם \"תפארת\" — ראה שער היחוד והא­מונה פ\"ח (פה, א) \"ומדת חסדו וגבורתו ורחמנותו ותפארתו הכלולה מחסדו וגבורתו וכן שאר מדו­תיו הקדושות\"."],["386","13","נדפס לקמן ע' 122."],["387","14","בסוף הפרק. וראה גם לקו\"ת תצא לט, א. שם, ג."],["e12","*","ועד\"ז י\"ל, דזה שמפרט בשער היחוה\"א פ\"ז שם רק \"חסד (ורחמים)\" הוא בהתאם להמשך דבריו שם \"ועולם ע\"י חסד יבנה. . כלי ולבוש לחסד זה\"."]]],[1301870120,"מעלה למטה להוליד. . אהבה ויראה ותולדותיהן\" [ולא רק כפי שהן עדיין ב\"מוחו ותעלומות לבו\", אלא גם כפי שהן \"בבחי' התגלות לבו\"<sup data-n=\"388\">15</sup>] נרמזת בה­\"אורך\" של אות ה\"א (ראשונה) — ואות וא\"ו קאי על הקול ודבור של עסק התורה והמצות?\nויש לומר, שהישוב על תמי' זו נרמז במ\"ש אדה\"ז \"מדת חסדו וטובו\", דקאי (כפירוש אאמו\"ר) על חסד ויסוד, \"ההת­חלה והסוף דהששה מדות\", ובזה גופא מדייק אדה\"ז \"מדת חסדו וטובו\" (ל' יחיד) — שההדגשה כאן היא כפי ששניהם (חסדו וטובו) נעשים (כמו) מדה אחת, כ­דלקמן.\nג. ויובן זה בהקדם החילוק בין ה\"או­רך\" דאות ה\"א (למעלה), \"המורה על. . ההמשכה וההשפעה מלמעלה למטה ל­עלמין סתימין\", וה\"אורך\" דאות וי\"ו (ל­מעלה), שזהו \"כשנמשכת המשכה והש­פעה זו יותר למטה לעלמין דאתגליין\" — שהחילוק ביניהם אינו רק ב\"אורך\" ה­המשכה, שעלמין דאתגליין הן \"יותר למטה\" מעלמין סתימין, אלא זהו סוג אחר של \"המשכה מלמעלה למטה\".\nדהנה החילוק שבין \"עלמין סתימין\" ל\"עלמין דאתגליין\" אינו רק ב\"העלם\" ו\"גילוי\" — אם מציאותם ניכרת ונגלית או שהיא נסתרת — אלא הוא בעצם מצי­אותן:\n\"עלמין סתימין\" הם ה\"עולמות\" ה­\"מכוסים\" במקורם (דבר ה' המחי' אותם), וכמו דגים שבים שא\"א להם להפרד ממקור חיותם, דמחוץ למקורם אין להם מציאות, כן ב\"עלמין סתימין\", שעדיין אין כאן מציאות \"נפרדת\" מאלקות, כי הם \"מכוסים\" במקורם; משא\"כ \"עלמין דאתגליין\" היינו שמציאותן היא בהת­גלות, שנתחדשה מציאות של עולמות שמחוץ למקורם ונפרדים ממנו.\nוחילוק זה מודגש בלשון אדה\"ז כאן גופא: כשמבאר ה\"המשכה\" דאות וי\"ו — \"ואח\"כ כשנמשכת המשכה והשפעה זו יותר למטה לעלמין דאתגליין\", מוסיף דוגמא — \"וכמו האדם שרוצה לגלות חכמתו לאחרים ע\"י דבורו\", דיש לומר, שבדוגמא זו מדגיש אדה\"ז<sup data-n=\"389\">16</sup>, שהחידוש דה\"המשכה\" לעלמין דאתגליין לגבי ה­המשכה לעלמין סתימין, אינו רק בכך שהיא \"יותר למטה\" (מעלמין סתימין), אלא זהו דבר חדש — התייחסות למצי­אות של \"זולת\" (\"אחרים\").\nד. לפי הקדמה זו מובנת גם ההת­אמה (הכללית) בין ענין ה\"אורך\" דאות ה\"א למעלה, שהיא \"ההשפעה. . לעלמין סתימין\", להאורך דאות ה\"א בנפש ה­אדם, \"המורה על ההמשכה. . להוליד מבינתו. . אהבה ויראה. . בבחי' הת­גלות לבו\":\nמדות האדם הן בדוגמת \"עלמין סתי­מין\", דכשם שה\"עלמין סתימין\" הרי מחד גיסא הם \"עלמין\" (דהיינו \"מציאות\" נוס­פת), אבל ביחד עם זה הרי הם \"סתימין\", שאינם נפרדים מאלקות כי מציאותם מכוסה במקורם (כדגים שבים) — עד\"ז הוא בענין המדות:\nהחידוש שבמדות ורגש הלב על ה­שכל הוא, שכל גדר המדות הוא רק ההתייחסות אל הזולת<sup data-n=\"390\">17</sup>. דענין השכל",[["388","15","ראה גם תניא אגה\"ק ס\"ה (קז, סע\"ב) \"והשפעתה מסתיימת בלב\"."],["389","16","וראה לקמן סוף סעיף ו ובהערה 33."],["390","17","בהבא לקמן ראה סה\"מ תש\"ח ע' 273 (סה\"מ תרנ\"ג ע' רפ­רפא). ובכ\"מ."]]],[1301870121,"אינו תלוי בזולת, שהרי יכול אדם להש­כיל השכלות לעצמו, ואדרבה, התרכזות המחשבה ועיון והעמקה בדבר שכל דור­שים התבודדות, והזולת מבלבל בזה; מ­שא\"כ ענין המדות הוא — היחס לאדם (או דבר) שחוץ ממנו, אם להתקרב אליו (אהבה) או להתרחק ממנו (יראה) וכיו\"ב<sup data-n=\"391\">18</sup>;\nאבל לאידך, המדה (שבלב) עצמה ה\"ה חלק מנפש האדם עצמו, שהיא רגש שלו להזולת [ועד שהמדות נחשבות כחלק מ\"מהות ועצמות\"<sup data-n=\"392\">19</sup> הנפש], ונמצא, שב­\"עולם המדות\" מציאות הזולת אינה נפ­רדת ממנו והיא רק כמו פרט ממציאותו (ורגש שלו)<sup data-n=\"393\">20</sup> — ע\"ד \"עלמין סתימין\"<sup data-n=\"394\">21</sup> המכוסים וכלולים במקורם; ורק כשבאה המדה לידי פועל — כמו השפעת החסד בפועל — נתחדשה מציאות של זולת כדבר נפרד ממנו.\nובזה מובנת גם ההתאמה (הכללית) בין ביאור אותיות ו\"ה למעלה (\"השפעה. . לעלמין דאתגליין, וכמו האדם שרוצה לגלות חכמתו לאחרים ע\"י דיבורו\") — לענינן בנפש האדם, שהוא \"עסק התורה והמצות בקול ודבור או מעשה\" — כי עסק זה (בדיבור ומעשה) הוא כפי ש­האדם פועל בעולם שחוץ ממנו<sup data-n=\"395\">22</sup>, ע\"ד עלמין דאתגליין שהם מציאות נפרדת ממקורם, כנ\"ל.\nה. ויש להבין: מהו טעם החילוק, ש­המדות שבנפש האדם הן דוגמת \"עלמין סתימין\", ואילו למעלה, ההמשכה וההש­פעה ע\"י \"מדותיו הקדושות\" היא לעלמין דאתגליין?\nויש לומר הביאור בזה:\nמשנת\"ל ש\"מדות\" הן בהאדם עצמו, עד שנחשבות מ\"עצמות ומהות\" הנפש — זהו רק במדות האדם, שהוא נברא, שגם מצד \"עצמות ומהות\" נפשו יש יחס ל­אדם (ודבר) שחוץ ממנו, ולכן גם ענין ה\"מדות\" (שהן יחסו אל הזולת) הן מ­\"מהות ועצמות\" נפשו;\nמשא\"כ למעלה כביכול, שמצד עצ­מותו ומהותו ית' אין מקום לשום דבר בלעדו ית', הרי כל ענין ה\"מדות\" (ה­מורה על היחס ונתינת מקום למציאות העולמות) מתחדש רק לאחרי שהקב\"ה השפיל את עצמו<sup data-n=\"396\">23</sup>, כביכול, כדי לברוא את העולם<sup data-n=\"397\">24</sup>.\n[שזהו א' מהפירושים<sup data-n=\"398\">25</sup> בפסוק<sup data-n=\"399\">26</sup> \"עולם",[["391","18","משא\"כ זה שענין השכל הוא הבנת ה­\"מושכל\" — הרי בזה נשאר \"מובדל\" עדיין ממנו, שלכן אין בזה ענין של התפעלות, שאין הבנת הדבר פועלת בו שינוי (שזהו כבר ענין המדות)."],["392","19","תניא ח\"א רפי\"ב."],["393","20","שלכן תתכן התעוררות המדות גם בלי זולת, כדמצינו באברהם שהצטער כשלא באו אליו אורחים, שמזה מובן שמדת חסדו היתה בהת­עוררות אצלו (אף קודם שבאו אנשים שיוכל לעשות עמם חסד) — סה\"מ תרצ\"ט ע' 15. ועוד."],["394","21","ולהעיר מהמבואר בכ\"מ דיראה ואהבה שבמוחא ולבא נק' \"הנסתרות\" (רע\"מ נשא קכג, ריש ע\"ב (וראה לקמן סעיף ז והערה 38). תקו\"ז ת\"י (כה, ב). ת\"ע (קכט, א). ועוד. וכ\"ה בתניא בהקדמה. שם רפמ\"ד)."],["395","22","והרי דיבור ומעשה נקראים לבושי הנפש (תניא ח\"א רפ\"ד. ע\"ש)."],["396","23","ראה סהמ\"צ להצ\"צ מצות האמנת אלקות פ\"ח. ועוד."],["397","24","כפירוש הזהר (ח\"א ג, ב. טו, ב. ועוד) ד\"בראשית\" — \"ברא שית\", שבשביל ענין הבריאה הי' צ\"ל (כעין) בריאת ששה מדות (\"ברא שית\") שעל ידן ברא הקב\"ה את עולמו (ראה סה\"מ תש\"ח (תרנ\"ג) שם)."],["398","25","סה\"מ תש\"ח (תרנ\"ג) שם."],["399","26","תהלים פט, ג."]]],[1301870122,"חסד יבנה\", ש\"יבנה\" קאי (לא על \"עולם\", אלא) על חסד — שכדי שיהי' עולם, \"צרי­כים לבנות את מדת החסד\", שכל ענין ה­\"חסד\" למעלה \"נבנה\" ונתחדש עם עליית הרצון לברוא העולם].\nולכן ההמשכה שע\"י \"מדותיו הקדו­שות\" היא ההשפעה לעלמין דאתגליין, ש­זהו כביכול כמו שהקב\"ה משפיל עצמו להמשיך חיות אל העולמות (כפי שנראים מציאות בפ\"ע, נפרדים ממקורם) — כי בה\"מקור\" עצמו (ה\"מוחין\" שלמעלה, אות ה' עילאה) אין מקום לדבר בלעדו ית'<sup data-n=\"400\">27</sup>.\nו. אלא שלכאורה אין הענין מחוור כל צרכו:\nכשם שמבחי' הבינה (אות ה' עילאה) נמשכים \"עלמין סתימין\", דאף שנקראים \"עולמות\" מ\"מ הרי הן \"סתימין\" וכלולים במקורם, ואינו סתירה לכך שמצד הקב\"ה אין שום דבר חוץ ממנו, כיון שאין הם מציאות נפרדת מאלקות, אלא שנרגש בהם שכל מציאותם היא רק מקורם ושרשם (ואין להם שום מציאות מחוץ למקורם), כנ\"ל — א\"כ כ\"ש וק\"ו, לכ­אורה, שיש להסביר כן ענין ה\"מדות\" למעלה, שאין כאן דבר שחוץ ממנו [וע\"ד משנת\"ל (סעיף ד) אפילו במדות דנפש האדם], ולמה אומר אדה\"ז ש\"מדותיו הקדושות\" שייכות לההשפעה לעלמין דאתגליין דוקא?\nוענין זה מתורץ ע\"י הוספת אדה\"ז \"המשכה זו [לעלמין דאתגליין] היא ע\"י מדת חסדו וטובו\", וכפירוש אאמו\"ר ש­\"הוא ההתחלה והסוף דהששה מדות ש­התחלתן חסד וסופן יסוד\":\nענינה של מדת היסוד הוא — התקש­רות המשפיע בהמקבל<sup data-n=\"401\">28</sup>, כמשל \"ההת­קשרות<sup data-n=\"402\">29</sup> שמקשר האב שכלו בשכל בנו בשעת למודו עמו באהבה ורצון שרוצה שיבין בנו. . מקשר שכלו אליו ומדבר עמו פא\"פ באהבה וחשק שחושק מאד שיבין בנו\". כלומר: אף שגם מדת החסד ענינה השפעה אל המקבל, הרי בזה ה­עיקר הוא חסדו של המשפיע, ואילו ענין היסוד הוא ההתקשרות והירידה אל ה­מקבל [שלכן יסוד הוא \"הסוף דהששה מדות\", כי ענינו התקשרות אל דרגת המקבל].\nונמצא, שההמשכה שע\"י \"מדות\" מח­ייבת מציאות של מקבל (לא כפי שהוא \"כלול\" בה\"משפיע\", אלא) בדרגתו (דה­מקבל). ולכן מדייק אדה\"ז שכללות ענין המדות היא \"מדת חסדו וטובו (יסוד)\", ובמילא מובן, שההמשכה שעל ידי \"מדו­תיו הקדושות\" [\"שהתחלתן חסד וסופן יסוד\"] שייכת לההשפעה לעלמין דאת­גליין<sup data-n=\"400\">27</sup>, \"כמו אדם הרוצה לגלות חכמתו לאחרים\".\nועפ\"ז מתורץ גם דיוק לשון אדה\"ז \"מדת חסדו וטובו\" — ל' יחיד, להורות",[["400","27","ו\"עלמין סתימין\" הנמשכים ממוחין (ומח­שבתו ית' — ראה שער היחוד והאמונה פי\"א. ובכ\"מ) — אינם נפרדים כלל.\n[ולמטה בנפש האדם, אין דוגמא ל\"עלמין סתימין\" כאלו, כי בדרגת המוחין, שענינם הבדלה מזולת, לא קיים ענין הזולת כלל (וזה מתחיל רק מדרגת המדות); משא\"כ למעלה, שגם ממוחין (ומחשבתו ית') יש התהוות, אלא ש\"עלמין\" אלו הם \"סתימין\" בתכלית (ראה המשך תרס\"ו ע' רלב). ואכ\"מ]."],["401","28","ראה בארוכה בביאורי הזהר שצויין בלקוטי לוי\"צ שם, ד\"יסוד\" הוא \"אור המאיר לזו­לתו ולחוץ ממנו\"."],["402","29","ל' התניא אגה\"ק סט\"ו (קכב, סע\"ב ואילך)."],["400","27","ו\"עלמין סתימין\" הנמשכים ממוחין (ומח­שבתו ית' — ראה שער היחוד והאמונה פי\"א. ובכ\"מ) — אינם נפרדים כלל.\n[ולמטה בנפש האדם, אין דוגמא ל\"עלמין סתימין\" כאלו, כי בדרגת המוחין, שענינם הבדלה מזולת, לא קיים ענין הזולת כלל (וזה מתחיל רק מדרגת המדות); משא\"כ למעלה, שגם ממוחין (ומחשבתו ית') יש התהוות, אלא ש\"עלמין\" אלו הם \"סתימין\" בתכלית (ראה המשך תרס\"ו ע' רלב). ואכ\"מ]."]]],[1301870123,"שאין חסד ויסוד (טוב) שני ענינים שונים, שמדת החסד היא למעלה עדיין מדרגת המקבל, ורק ב\"סוף הששה מדות\" (יסוד) מתחדש ענין הירידה אל המקבל — אלא שניהם הם ענין אחד<sup data-n=\"404\">30</sup>, שחסד ויסוד הם ההתחלה והסוף של המשכה אחת (ההמ­שכה ד\"מדות\"<sup data-n=\"405\">31</sup>), שמזה מובן שכללות ענין המדות מכריח מציאותו של \"מקבל\".\nובזה יש לבאר עוד דיוק בל' אדה\"ז כאן — שצירף יחד הביאור של אותיות ו\"ה: \"נכללת ונרמזת המשכה זו באותיות ו\"ה\", וכן בהדוגמא \"וכמו האדם שרוצה לגלות חכמתו לאחרים ע\"י דבורו\" — כי בזה מודגש עוד יותר, שכללות ההמשכה שע\"י מדות קשורה עם מציאות של \"אחרים\" כפי שהם מציאות נפרדת ממנו, שלכן, גמר השפעה זו (שע\"י אות וי\"ו) הוא ע\"י דבורו ית' (הנרמז באות ה\"א אחרונה)<sup data-n=\"406\">32</sup> — \"כמו אדם שרוצה לגלות חכמתו לאחרים ע\"י דיבורו\"<sup data-n=\"407\">33</sup>.\nז. והנה, כיון שביאור זה בד' אותיות שם הוי' למעלה ובנפש האדם כתבו אדה\"ז באגרת התשובה, מסתבר לומר, שגם פרטי הענינים שבביאור זה שייכים לענין התשובה.\nויש לומר הביאור בזה:\nבתחילת הפרק<sup data-n=\"408\">34</sup> מביא אדה\"ז \"ביאור מלת התשובה ע\"ד הסוד, תשוב ה', ה' תתאה תשובה תתאה, ה' עילאה תשובה עילאה\"<sup data-n=\"409\">35</sup>. ועפ\"ז יש לומר, שהביאור בהמשך הפרק ע\"ד ד' אותיות שם הוי' בנפש האדם, הוא בהתאם לב' מדריגות אלו שבתשובה.\nהסברת הענין:\nהחילוק בין תשובה תתאה ותשובה עילאה מבואר בהמשך הפרקים באגה\"ת: תשובה תתאה היא התשובה על עוונות, לתקן הפגמים כו' שע\"י מעשיו הרעים<sup data-n=\"410\">36</sup>, ותשובה עילאה ענינה — השבת הנפש \"מעלה מעלה למקורה ולדבקה בו ית'",[["404","30","ויש לומר, שזוהי כוונת אאמו\"ר במ\"ש \"בקר דאברהם ובקר דיוסף\" (ומציין לביאוה\"ז) — שזה ששניהם נקראים \"בוקר\" (המורה על אור וגילוי) מורה שחסד ויסוד מהותם א', ורק שזוהי ההתחלה וזהו הסיום. ולהעיר מסידור עם דא\"ח מט, ד ואילך (מאמרי אדמו\"ר האמצעי על נ\"ך ע' קסו ואילך)."],["405","31","שהן (בכללות) המשכה אחת. ויש לומר שמודגש גם בזה שכל השש מדות נרמזות באות אחת — וי\"ו. ואולי י\"ל שזהו דיוק ל' אדה\"ז \"הנכ­ללות כו' במספר שש\", שכל השש הם מציאות אחת."],["406","32","ועפ\"ז יש לבאר סגנון ל' אדה\"ז בהמשך דבריו \"הנכללות כו' במספר שש שבפסוק לך הוי' הגדולה וכו' עד לך הוי' הממלכה וכו' ולא עד בכלל כי מדת מלכותו כו'\", שמזה גופא מובן שבעצם גם \"לך הוי' הממלכה\" שייך להמדות, אלא שעכצ\"ל ש\"לא עד בכלל, כי מדת מלכותו כו' נכללת ונרזמת באות ה\"א כו'\"."],["407","33","דלכאורה אינו מובן: כיון שהמשכה זו היא ע\"י מדות, הו\"ל לנקוט דוגמא פשוטה, ממדת החסד שבאדם, שרוצה להטיב לזולתו — ולמה הביא דוגמא מהשפעת שכל לאחרים<sup data-n=\"e13\">*</sup>?\nאלא שבנפש האדם, המדה שבלב ה\"ה עדיין למעלה מהזולת בפועל, עד שיכול להיות הת­עוררות המדה בלי זולת (כנ\"ל הערה 20), ולכן הביא דוגמא מ\"אדם שרוצה לגלות חכמתו לאח­רים ע\"י דיבורו\", שגם הרצון (ה\"מדה\") \"לגלות חכמתו לאחרים ע\"י דיבורו\" לא יתכן בלי מציאות של \"אחרים\"."],["408","34","צג, ב."],["409","35","ע\"פ רע\"מ נשא קכג, א­ב. וראה הערה 38."],["410","36","אגה\"ת פ\"ו­ז."],["e13","*","אף שבפשטות הטעם, כי רוצה לבאר איך שהמשכה זו עצמה שבאות יו\"ד נמשכת למטה. ואכ\"מ."]]],[1301870124,"ביחוד נפלא\"<sup data-n=\"411\">37</sup>. ומזה מובן, שעיקר הענין דתשובה תתאה קשור עם \"עסק התורה והמצות בקול ודבור או מעשה\" (אותיות ו\"ה<sup data-n=\"412\">38</sup>); ותשובה עילאה, שענינה דביקות הנפש בשרשה ומקורה, היא ע\"י עבודת המוח והלב<sup data-n=\"413\">39</sup> (אותיות י\"ה<sup data-n=\"412\">38</sup>).\nובזה יובן היטב משנת\"ל, שה\"אורך\" דאות ה\"א (ראשונה) הוא ההמשכה ל­\"עלמין סתימין\", ובנפש האדם — במדות, שהן עדיין בהאדם עצמו; ואילו אותיות ו\"ה מרמזות על ההמשכה ל\"עלמין דאת­גליין\", שזהו כפי שהאדם פועל בעולם שחוץ ממנו:\nתשובה תתאה באה לתקן (נוסף על הפגמים שבנפשו) גם הקלקול שנפעל בעולם ע\"י מעשיו הרעים, וכמבואר ב­ארוכה באגה\"ת<sup data-n=\"415\">40</sup>, איך שע\"י החטאים גור­מים השפעת החיות \"להיכלות<sup data-n=\"416\">41</sup> הסט\"א אשר שנאה נפשו ית'\", וע\"י תשובה תתאה \"מחזיר<sup data-n=\"416\">41</sup> השפעת השכינה למקומה\";\nואילו ענינה של תשובה עילאה הוא בהאדם עצמו — \"לשוב<sup data-n=\"411\">37</sup> עד הוי' ב\"ה ממש. . ולדבקה בו ית' ביחוד נפלא כמו שהיתה מיוחדת בו ית' בתכלית היחוד בטרם שנפחה ברוח פיו ית' לירד למטה ולהתלבש בגוף האדם\" — שזהו כפי שהאדם מגבי' את עצמו למעלה מן ה­עולם<sup data-n=\"419\">42</sup> (\"בטרם שנפחה. . לירד למטה\"), \"עד הוי' ב\"ה ממש\".\n<span data-k=\"q\">(משיחת ש\"פ בראשית תשל\"א)</span>",[["411","37","שם פ\"ח (צח, סע\"א)."],["412","38","עפ\"ז מובן הטעם שאדה\"ז באגה\"ת כאן נקט חלוקה זו דוקא דד' אותיות הוי' בנפש האדם [ולא החלוקה: י' — חכמה, ה' — בינה, ו' — מדות, ה' — מחשבה דבור ומעשה (לקו\"ת ר\"פ ראה, ובכ\"מ)] — כי חלוקה זו (די\"ה שייך לעבודת הלב והמוח, ואותיות ו\"ה — לעסק התומ\"צ בדיבור ומעשה) מתאימה לב' הדרגות דתשו\"ת ותשו\"ע. ועד\"ז בלקו\"ת תצא הנ\"ל הערה 14, שבא בקשר עם ענין התשובה (ע\"ש, וכן באוה\"ת שם ע' תתקצ. ע' תתרג­ד).\nולהעיר, שברע\"מ נשא שם (ריש ע\"ב), הובאה חלוקה זו בנפש האדם [ד\"יראה ואהבה. . במוחא ולבא\" הן הנסתרות (י\"ה — תקו\"ז ריש תכ\"ב. ת\"ע שם. ובכ\"מ), \"והנגלות התורה והמצוה\" (\"ו\"ה נגלות\" — תקו\"ז ת\"ע שם)] בהמשך לביאור מלת תשובה, תשוב ה'. ע\"ש."],["413","39","כמפורש שם ספ\"ח, מר\"מ פ' נשא (ראה הערה הקודמת) \"דתשו\"ע היא דיתעסק באורייתא בדחילו ורחימו כו' בן י\"ה בינה כו'\". ושם רפ\"ט: \"דבינה איהי תשובה עילאה והאם רובצת על האפ­רוחים וכו'\". ע\"ש. וראה לקמן ע' 91 ס\"ב ואילך."],["412","38","עפ\"ז מובן הטעם שאדה\"ז באגה\"ת כאן נקט חלוקה זו דוקא דד' אותיות הוי' בנפש האדם [ולא החלוקה: י' — חכמה, ה' — בינה, ו' — מדות, ה' — מחשבה דבור ומעשה (לקו\"ת ר\"פ ראה, ובכ\"מ)] — כי חלוקה זו (די\"ה שייך לעבודת הלב והמוח, ואותיות ו\"ה — לעסק התומ\"צ בדיבור ומעשה) מתאימה לב' הדרגות דתשו\"ת ותשו\"ע. ועד\"ז בלקו\"ת תצא הנ\"ל הערה 14, שבא בקשר עם ענין התשובה (ע\"ש, וכן באוה\"ת שם ע' תתקצ. ע' תתרג­ד).\nולהעיר, שברע\"מ נשא שם (ריש ע\"ב), הובאה חלוקה זו בנפש האדם [ד\"יראה ואהבה. . במוחא ולבא\" הן הנסתרות (י\"ה — תקו\"ז ריש תכ\"ב. ת\"ע שם. ובכ\"מ), \"והנגלות התורה והמצוה\" (\"ו\"ה נגלות\" — תקו\"ז ת\"ע שם)] בהמשך לביאור מלת תשובה, תשוב ה'. ע\"ש."],["415","40","פ\"ו ואילך."],["416","41","שם ספ\"ו."],["416","41","שם ספ\"ו."],["411","37","שם פ\"ח (צח, סע\"א)."],["419","42","וראה לקמן ע' 131 ואילך, ובהנסמן בה­ערה *21 שם."]]],[1301870125,"<h3>אגרת התשובה ב</h3>\nא. באגרת התשובה פ\"ד<sup data-n=\"420\">1</sup> מבאר אד­מו\"ר הזקן, שמ\"ש<sup data-n=\"421\">2</sup> \"כי חלק הוי' עמו\" היינו שבנ\"י הם \"חלק משם הוי' ב\"ה\", כי כמו שיש ד' אותיות בשם הוי', כך יש דוגמת ד' אותיות אלו בכל נפש מיש­ראל<sup data-n=\"422\">3</sup>; ואחרי שמבאר ענין ד' אותיות שם הוי' למעלה (שהם היו\"ד ספירות ש\"נכ­ללות ונרמזות בשם הוי' ב\"ה\"), מבאר (בסוף הפרק<sup data-n=\"423\">4</sup>) ענינם בנפש האדם:\n\"בחי' שכל הנעלם (ה)מרומז באות יו\"ד, שבכחו לצאת אל הגילוי להבין ולהשכיל באמתתו ית' ובגדולתו. . וכפי אשר מעמיק שכלו ומרחיב דעתו ובינתו להתבונן בגדולתו ית' אזי נרמזת בינתו באות ה\"א שיש לה רוחב וגם אורך המו­רה על<sup data-n=\"424\">5</sup> ההמשכה מלמעלה למטה להוליד מבינתו והתבוננותו בגדולת ה' אהבה ויראה ותולדותיהן. . ומזה נמשכה עבו­דה האמיתית בעסק התורה והמצות בקול ודבור או מעשה הן אותיות וא\"ו ה\"א וכו'. וגם ההתבוננות להבין ולהשכיל באמתתו וגדולתו ית' נמשכה ג\"כ מהתורה דאוריי­תא מחכמה נפקא<sup data-n=\"425\">6</sup> היא בחי' יו\"ד של שם הוי' וכו'\".\nובהערות אאמו\"ר<sup data-n=\"426\">7</sup> עומד על שינויי הלשונות, שבתחילה \"נקט ב' דברים, ב­אמתתו ובגדולתו, ואח\"כ במרחיב דעתו ובינתו נקט רק בגדולתו<sup data-n=\"427\">8</sup>. . ובסוף הפרק כשנקט וגם ההתבוננות כו' נקט עוד הפעם באמתתו וגדולתו ית', ב' הדברים אמתתו וגדולתו\".\nוהנה אף שאאמו\"ר לא ביאר הטעם לשינויים אלה — כבר נת' כמ\"פ, שבכגון דא סמך אאמו\"ר שבעיון הראוי יוכל ה­לומד לעמוד מעצמו על הסברת הדברים.\nב. ויש לומר הביאור בזה:\nשתי הלשונות \"אמתתו\" ו\"גדולתו\" מכוונות לשני הענינים ד\"חכמה\" ו\"בינה\".\nדהנה החילוק בין חכמה ובינה הוא, דחכמה היא נקודת השכל (שלמעלה מ­פרטי הענין), ובינה היא כשהאדם מבין דבר חכמה \"לאשורו ולעמקו\"<sup data-n=\"428\">9</sup>, שזהו ע\"י שמפרט את הענין לפרטיו דוקא, שכל פרט מתיישב ובא על מקומו.\nואין זה רק כהחילוק בין \"כלל\" ו\"פרט\" (שחכמה היא הנקודה הכללית של המושכל ובינה היא הבנת הפרטים) — אלא הוא חילוק יסודי יותר: נקודת החכ­מה ענינה — הארת אמיתית המושכל עצמו, וכפי שאנו רואים אצל אדם המת­ייגע בהבנת איזה ענין, שלפתע עולה במוחו רעיון חדש, כמו \"ברק המבריק\", שברגע זה מרגיש שזהו היישוב לכל הענין המוקשה אצלו, אף שבאותה שעה אינו יכול לבאר ולהסביר כיצד נתיישב",[["420","1","צג, סע\"ב ואילך."],["421","2","האזינו לב, ט."],["422","3","שם צד, ב ואילך."],["423","4","שם צה, א."],["424","5","כ\"ה בלוח התיקון לתניא."],["425","6","זח\"ב קכא, א. ועוד."],["426","7","לקוטי לוי יצחק על תניא — ע' ל."],["427","8","\"וכן נקט אח\"כ להוליד כו' בגדולת ה', נקט רק גדולה (אלא שיש הפרש קצת, מקודם נקט גדולתו ואח\"כ נקט גדולת ה')\" — לקוטי לוי\"צ שם. וראה לקמן הערה 43."],["428","9","ל' התניא ח\"א פ\"ג."]]],[1301870126,"הענין כולו, שזהו רק לאחרי שמתבונן בכל פרטי הענין ליישבם ע\"פ נקודה זו, עד שכולם באים על מקומם. ולאידך, בעת ההתבוננות והיגיעה בהבנת פרטי המוש­כל אינו מרגיש את האמת וההפלאה של החכמה כפי שהם בעת הברקת נקודת החכמה.\nוטעם הדבר, כי בנקודת החכמה מאי­רה אמיתית המושכל עצמו, ואילו ענינה של בינה הוא מה שהאדם מתייגע לתפוס ולהשיג נקודת השכל עד שתתיישב בכלי שכלו, ומצד זה גופא לא מאיר בבינה אמיתיות השכל כפי שהוא מצד עצמו, אלא רק כפי תפיסת כלי שכלו של אדם זה<sup data-n=\"429\">10</sup>.\nונמצא, שההבדל בין \"חכמה\" ו\"בינה\" הוא כההבדל בין \"אמת\" ו\"גדולה\": בחכ­מה מאיר ה\"אמת\" של המושכל<sup data-n=\"430\">11</sup>; ובבינה שענינה \"התפשטות לרוחב. . הרחבת ה­ביאור וההבנה\"<sup data-n=\"431\">12</sup>, ע\"י תפיסת ריבוי פרטי הענין — מודגשת גדלות המושכל.\nוכן הוא בהשגת אלקות — שבחכמה של נפש האלקית מאירה \"אמיתתו ית'\" [וכמבואר גם בתניא חלק ראשון<sup data-n=\"432\">13</sup>, שב­חכמה שבנפש מאיר \"אור א\"ס ב\"ה\", וכן הובאו שם<sup data-n=\"433\">14</sup> דברי הה\"מ \"שא\"ס ב\"ה הוא אחד האמת. . וזו היא מדריגת החכמה\"], ובינה של הנשמה תופסת \"גדולתו\" ית'.\nג. עפ\"ז יש לבאר טעם שינויי הלשו­נות הנ\"ל בדברי אדה\"ז — ובהקדם ביאור לשון אדה\"ז כאן \"שכל הנעלם המרומז באות יו\"ד שבכחו לצאת אל הגילוי ל­הבין ולהשכיל באמתתו ית' ובגדולתו וכו'\":\nכפי שלומדים בפשטות, כוונתו ב­\"שכל הנעלם\" היא לכח החכמה, ומ\"ש \"(לצאת אל הגילוי) להבין כו'\" היינו בינה [וכמ\"ש לעיל בביאור ד' אותיות שם הוי' למעלה, ש\"היו\"ד. . מרמזת לחכמתו ית'\", ו\"התפשטות וגילוי ההשגה וההבנה [בינה]. . נכללת ונרמזת באות ה\"א\"],\nאבל עפ\"ז תמוה מ\"ש \"(בכחו לצאת אל הגילוי להבין) ולהשכיל כו'\": הרי \"ל­השכיל\" היא פעולת כח החכמה, וכמ\"ש אדה\"ז בתניא חלק ראשון<sup data-n=\"434\">15</sup>, ד\"השכל. . המשכיל כל דבר נקרא בשם חכמה\"?\nועכצ\"ל, שמ\"ש אדה\"ז שאות יו\"ד (שב­נפש) מרמזת על \"שכל הנעלם\", הכוונה<sup data-n=\"435\">16</sup> גם ל\"שכל הנעלם\" שלמעלה מחכמה ה­גלוי'<sup data-n=\"436\">17</sup>, וכמבואר בכ\"מ שיש לשכל (הן חכמה והן בינה) מקור נעלם בנפש (\"כח המשכיל\"), שממנו נמשך שכל גלוי; וזהו שכתב אדה\"ז ש\"שכל הנעלם. . בכחו לצאת אל הגילוי להבין ולהשכיל כו' כל חד וחד כו' לפי רוחב שכלו ובינתו\",",[["429","10","וכלשון אדה\"ז באגה\"ת כאן \"כל חד וחד לפום שיעורא דילי' לפי רוחב שכלו ובינתו\"."],["430","11","ראה מאמרי אדמו\"ר האמצעי ויקרא ח\"ב ע' תרכא ואילך. וראה גם המשך תער\"ב ח\"ג ס\"ע א'שעד ואילך. ועוד."],["431","12","ל' אדה\"ז כאן לעיל (צד, ב) בביאור אות ה\"א למעלה."],["432","13","פי\"ח."],["433","14","פל\"ה בהגה\"ה. וראה לקו\"ת מסעי (צא, ד ואילך. צג, סע\"א ואילך)."],["434","15","פ\"ג."],["435","16","עיין גם לקו\"ת תצא לט, ב. ובמאמרי אדמו\"ר האמצעי דברים ח\"ג (ע' תשפה), דשכל הנעלם הוא נקודת היו\"ד עצמו קודם שבא לידי מילוי. ע\"ש. וראה אוה\"ת עקב ע' תקמב. ד\"ה החלצו תרנ\"ט פכ\"ג (סה\"מ תרנ\"ט ע' עג). ועוד. ולהעיר מ\"קיצורים והערות\" לתניא ע' ק (ובהנסמן שם)."],["436","17","כמבואר בכ\"מ בפי' \"שכל הנעלם מכל רעיון\", דהיינו חכמה סתימאה (מאמרי אדה\"ז — פרשיות ר\"פ לך. תו\"ח שם. ועוד)."]]],[1301870127,"שמשכל נעלם זה נמשכים שני הענינים — נקודת החכמה (להשכיל) וגם רוחב הבינה<sup data-n=\"437\">18</sup>.\nועפ\"ז מבואר היטב מה ש\"נקט ב' דברים באמתתו ובגדולתו\", כי קאי הן על נקודת החכמה (הגלוי') שבה מאירה אמתתו ית', והן על רוחב דבינה שעל ידו משיגים גדולתו של הקב\"ה;\nמשא\"כ \"אח\"כ במרחיב דעתו ובינתו נקט רק בגדולתו\", כי שם קאי רק על בינתו של האדם<sup data-n=\"438\">19</sup> (ה\"מרומזת. . באות ה\"א\"<sup data-n=\"439\">20</sup>);\n\"ובסוף הפרק כשנקט וגם ההתבוננות כו' נקט עוד הפעם באמתתו וגדולתו ית', ב' הדברים אמתתו וגדולתו\" — כי גם שם מדייק אדה\"ז \"(וגם ההתבוננות) להבין ול­השכיל באמתתו וגדולתו ית'\", שמזה מובן שגם שם כוונתו לכלול ב' הענינים דנקו­דת החכמה (\"להשכיל\") והרוחב דבינה<sup data-n=\"440\">21</sup>, וכנגדם נקט \"ב' הדברים אמתתו וגדו­לתו\".\nד. לפי הסבר זה יש לבאר גם עוד שינוי (שאאמו\"ר מציין בהערותיו): ב­תחילת הענין נקט אדה\"ז \"באמתתו ית' ובגדולתו\", ואילו בסוף הפרק נקט \"באמ­תתו וגדולתו ית'\" — והם שני שינויים: (א) \"וגדולתו\", לא \"ובגדולתו\" (בב'). (ב) \"נקט ית' לבסוף אחר גדולתו, ולא כמקודם שנקט ית' אחר אמתתו\".\nוע\"פ הנ\"ל מובן, כי בתחלת הענין קאי על \"שכל הנעלם. . שבכחו לצאת אל הגילוי\", שביציאתו אל הגילוי יש שני שלבים (שונים) — גילוי נקודת החכמה, ואח\"כ הגילוי של הרחבת הביאור דבינה; ולכן אומר \"באמתתו ית' ובגדולתו\" [(א) תיבת \"ית'\" מפסקת בין \"אמתתו\" ו\"גדו­לתו\", (ב) \"ובגדולתו\" בב'] — שבזה מוד­גש שהם ב' ענינים, להשכיל \"באמתתו ית'\", וההבנה \"בגדולתו\".\nמשא\"כ בסוף הפרק קאי על ההת­בוננות, שהיא נמשכת \"מהתורה. . יו\"ד של שם הוי'\", אלא שבענין ההתבוננות כולל לא רק \"להבין\" (הרחבת הביאור) אלא גם נקודת החכמה (להשכיל) — דשניהם יחד מקורם \"מהתורה\"; וכיון שכאן כוונתו ל(נקודת ה)חכמה ובינה יחד, לכן אומר \"באמתתו וגדולתו ית'\", שתי הלשונות ביחד.\nה. אבל יש לעיין בעצם הענין:\nמדוע מבאר אדה\"ז שהיו\"ד שבנפש האדם מרמזת על \"שכל הנעלם\" (שלמע­לה מחכמה גלוי') — ולא דקאי על חכמה (הגלוי') שבנפש? והרי בד' אותיות שם הוי' למעלה לא הזכיר אדה\"ז \"שכל נעלם\" (שלמעלה מחכמה גלוי')<sup data-n=\"441\">22</sup>, אלא",[["437","18","ומה שמקדים \"להבין\" לפני \"ולהשכיל\"<sup data-n=\"e14\">*</sup> — י\"ל שזהו כדי לרמז גם על ההמשכה והירידה מחכמה סתימאה (שכל הנעלם) לחכמה הגלוי', שירידה והמשכה זו היא ע\"ד ענין הבינה (שיש לה \"אורך\", המשכת השכל מלמעלה למטה, כהמשך דברי אדה\"ז כאן באות ה\"א)."],["438","19","כלשון אדה\"ז שם \"מעמיק שכלו ומרחיב דעתו ובינתו להתבונן כו' אזי מרומזת בינתו כו'\"."],["439","20","כי גם חכמה גלוי' נכללת באות יו\"ד, אלא שבלשון \"שכל הנעלם המרומז באות יו\"ד\" הכוונה גם לחכמה סתימאה (כח המשכיל), כנ\"ל."],["440","21","ומקדים \"להבין\" לפני \"ולהשכיל\" — כי קאי על \"ההתבוננות להבין ולהשכיל כו'\". וכד­לקמן בפנים."],["441","22","ומה שמוסיף שם בסוגריים \"והקוץ שעל היו\"ד רומז לבחי' רצון העליון ב\"ה שלמעלה מעלה ממדריגת בחי' חכמה עילאה\" — ה\"ז בחי' הכתר (רצון העליון) שלמעלה מ\"שכל הנעלם\", חכמה סתימאה (וראה גם לקוטי לוי\"צ לשם — ס\"ע כט. לקמן ע' 152).\nטעם הוספה זו נת' לקמן ע' 144 ואילך."],["e14","*","הלשון \"להבין ולהשכיל\" בסוף הפרק — ראה לקמן הערה 21."]]],[1301870128,"רק \"חכמתו ית'\" [ומ\"ש שם שהחכמה \"היא בבחי' העלם והסתר\", היינו רק ל­גבי \"בחי' התפשטות וגילוי ההשגה וה­הבנה\" דבינה<sup data-n=\"442\">*22</sup>].\nועד\"ז צריך ביאור בסוף הפרק, כש­מבאר כיצד \"ההתבוננות כו' נמשכה ג\"כ מהתורה. . מחכמה. . יו\"ד של שם הוי'\" — למה צירף לענין ההתבוננות (דבינה) גם \"להשכיל באמתתו\" (שהיא פעולת החכמה)?\nויובן זה בהקדם ביאור כללי בסוף הפרק כאן, שלאחרי שמסיים אדה\"ז בי­אור ד' אותיות הוי' בנפש האדם, מוסיף: \"וגם ההתבוננות להבין ולהשכיל באמת­תו וגדולתו ית' נמשכה ג\"כ מהתורה. . בחי' יו\"ד של שם הוי' וכו'\".\nואינו מובן:\nא) מה חסר בביאור ד' אותיות שם הוי' שבנפש שלפני כן, שהוזקק להוסיף ש\"ההתבוננות כו' נמשכה ג\"כ מהתורה. . בחי' יו\"ד של שם הוי'\"?\nב) בכל אופן: למה בא ענין זה בסוף הפרק, דלכאורה מקומו לעיל, בביאור אות יו\"ד שבנפש — דלאחרי שמבאר ש­\"שכל הנעלם (ה)מרומז באות יו\"ד שבכחו לצאת אל הגילוי להבין ולהשכיל כו'\", היינו ש\"שכל הנעלם\" דאות יו\"ד הוא השורש לההתבוננות באמתתו וגדולתו ית', הנה בהמשך לזה הול\"ל \"וגם ההת­בוננות כו' נמשכה ג\"כ מהתורה דאוריי­תא מחכמה נפקא היא בחי' יו\"ד של שם הוי' כו'\".\nג) מהו החילוק בתוכן בין זה ש\"שכל הנעלם\" (המרומז באות יו\"ד) הוא המקור שממנו נמשך הכח \"להבין ולהשכיל באמתתו ית' ובגדולתו\", להא ש\"ההת­בוננות להבין ולהשכיל באמתתו וגדולתו ית' נמשכה. . מהתורה. . יו\"ד של שם הוי'\"? דלכאורה היינו הך, שהאדם לוקח \"נקודה\" המבוארת בתורה ומתבונן בה בהרחבת הדעת וההבנה, ומהו החילוק אם הנקודה היא מחכמה שבנפש או שנקודה זו מקורה בתורה?\nו. ויש לומר הביאור בכל זה:\nבביאור ד' אותיות שם הוי' בנפש האדם, מדגיש אדה\"ז בלשונו ענין שלא פירשו בביאור שם הוי' שלמעלה, והוא, שהמדריגה העליונה (הנרמזת באות הקו­דמת שבשם) היא שורש ומקור למה של­מטה ממנו.\nוכמו בביאור אות יו\"ד, שלעיל<sup data-n=\"443\">23</sup> לגבי ביאור אות יו\"ד של שם הוי' למעלה כותב רק שהיא \"מרמזת לחכמתו ית' שהיא בבחי' העלם והסתר קודם שבאה לבחי' התפשטות וגילוי ההשגה וההבנה\", אבל למטה בנפש האדם אינו אומר שהוא \"שכל הנעלם קודם שבא לידי גילוי\", אלא מדייק \"שכל הנעלם. . שבכחו לצאת אל הגילוי\", שזה מדגיש שזהו ענינו של שכל הנעלם, שהוא ה\"בכח\", המקור והשורש, \"להבין ולהשכיל כו'\".\nוכן לאח\"ז, לאחרי ביאור אות ה\"א בנפש האדם, מדייק אדה\"ז \"ומזה נמשכה עבודה האמיתית בעסק התורה והמצות בקול ודבור או מעשה הן אותיות וא\"ו",[["442","*22","אבל ראה לקמן שם ע' 151."],["443","23","צד, ב."]]],[1301870129,"ה\"א\", היינו שההתבוננות בגדולת ה' (עם אהבת ה' ויראתו הנולדות מן ההתבו­ננות) מביאה ל\"עבודה האמיתית בעסק התורה והמצות. . אותיות וא\"ו ה\"א\" (משא\"כ למעלה כתב רק \"ואח\"כ כשנמ­שכת המשכה והשפעה זו יותר למטה כו'\").\nובהסברת הדבר יש לומר:\nכוונת אדה\"ז כאן היא לבאר איך שישראל הם \"חלק משם הוי' ב\"ה\", שמזה מובן שאין הכוונה רק שבנשמת האדם יש דוגמת<sup data-n=\"444\">24</sup> ד' אותיות שם הוי' שלמעלה לפי ששרש נשמתו הוא משם הוי' (ועשר כחות הנפש משתלשלים מעשר ספירות העליונות<sup data-n=\"445\">25</sup> ה\"נרמזות בשם הוי' ב\"ה\")<sup data-n=\"446\">26</sup> — אלא שד' אותיות הוי' עצמן מאירות בנפש האדם, כפי שהיא מלובשת בגוף האדם<sup data-n=\"447\">27</sup>.\nוהנה הנשמה עצמה, אף ששרשה משם הוי', הרי (כפי שביאר אדה\"ז לעיל בהפרק<sup data-n=\"448\">28</sup>) \"ירדה בסתר המדרגה. . ע\"י בחי' האותיות שבמאמר<sup data-n=\"449\">29</sup> נעשה אדם וכו' כדי להתלבש בגוף עוה\"ז התחתון\" (שזהו ע\"י שם אלקים<sup data-n=\"450\">30</sup>). ולכן לא נרגש בה­נשמה עצמה (כפי שירדה למטה) שד' \"אותיות\" שלה הן הן ד' אותיות שם הוי' המאירות בה.\nוגילוי ענין זה (שד' אותיות של הנש­מה הן ד' אותיות שם הוי' המאירות בה) הוא ע\"י עסק התורה והמצות<sup data-n=\"451\">31</sup>, כי תורה ומצות הן חכמתו ורצונו של הקב\"ה, ואורייתא וקוב\"ה כולא חד<sup data-n=\"452\">32</sup>, ולכן, ע\"י עסק התורה והמצות מתגלה בהנשמה ש­אמיתית מציאותה היא — \"חלק משם הוי' ב\"ה\"<sup data-n=\"453\">33</sup>.\nויש לומר, שזהו דיוק ל' אדה\"ז כאן \"ומזה נמשכה עבודה האמיתית בעסק ה­תורה והמצות\": אין הכוונה רק שאז \"עסק התורה והמצות\" הוא בשלימות ובאמת (כיון שנעשים מתוך אהבת ה' ויראתו כו')<sup data-n=\"454\">34</sup>, אלא ש\"עסק התורה והמצות\" נק' \"עבודה האמיתית\" (גם) לגבי ההתבוננות בגדלות הא­ל ואהבת ה' כו'<sup data-n=\"455\">35</sup>. לפי שה­",[["444","24","כל' אדה\"ז בתניא אגה\"ק סכ\"ה (קמ, סע\"א ואילך). משא\"כ כאן באגה\"ת מדגיש \"וככה ממש\", שמזה מובן שאין כוונתו לענין של \"דוגמא\" בלבד. וראה אגה\"ת עם ליקוט פירושים כו' (קה\"ת, תשמ\"ו) ס\"ע רסט ואילך."],["445","25","תניא ח\"א רפ\"ג."],["446","26","והרי יש \"דוגמת\" עשר ספירות גם בנפש השכלית ונפש הבהמית (ראה תניא רפ\"ו. אגה\"ק סט\"ו (קכג, א). שם סכ\"ה (קמ, ב). ועוד)."],["447","27","וראה גם לקמן ע' 138. ע' 69 (ס\"ד). ע' 76 (ס\"ה)."],["448","28","צד, א."],["449","29","בראשית א, כו."],["450","30","ראה לקו\"ת בלק עג, ב."],["451","31","וכן משמע ממ\"ש בלקו\"ת פקודי (ד, רע\"ג) — לענין י\"ה שבנפש — \"וזהו הנמשך ומת­גלה ע\"י קיום מצות ל\"ת\" [אף שכ' לפנ\"ז (שם, סע\"ב) ש\"בפניהם הם ניכרים. . כי הם זרע ברך ה'. . ע\"י שיש בכל א' בחי' שם הוי' ממש\"].\nובלקו\"ת ר\"פ ראה, שהמשכת ד' אותיות הוי' לכאו\"א מישראל היתה \"בשעת קבלת התורה\"."],["452","32","תניא פ\"ד (ח, סע\"א) ורפכ\"ג בשם הזהר. וראה זח\"א כד, א. זח\"ב ס, סע\"א. שם צ, ב. ועוד."],["453","33","ע\"ד הידוע בענין \"ישראל מתקשראן ב­אורייתא ואורייתא בקוב\"ה\" (ראה זח\"ג עג, א), שגילוי שורש הנשמה בקוב\"ה הוא ע\"י אורייתא דוקא (ראה לקו\"ת שה\"ש ד\"ה יונתי והביאור (טז, ד ואילך). המשך תער\"ב ח\"א פרק עו. שם ח\"ג ע' א'תג ואילך. ועוד)."],["454","34","ראה תניא רפ\"ד \"והמקיימן באמת כו'\" (וראה קונטרס העבודה פ\"ב ע' 15). שם פט\"ז. שם פל\"ח (נ, א) ואילך."],["455","35","להעיר מתניא ספ\"מ: \"אף דדחילו ורחימו הם ג\"כ מתרי\"ג מצות אעפ\"כ נקראין גדפין להיות כי תכלית האהבה היא העבודה מאהבה\" (וראה גם תניא רפ\"ד: ואי אפשר לדבקה בו באמת כי אם בקיום רמ\"ח פקודין כו').\n[ומזה מובן (במכ\"ש וק\"ו) לענין ההתבוננות (שורש האהבה והיראה) — אף שג\"ז \"מצוה\" (ראה תניא קו\"א ד\"ה להבין מ\"ש בפע\"ח — קנו, ב)]. ואכ\"מ."]]],[1301870130,"עבודה דהתבוננות ואהבה ויראה הם שכל ומדות של נברא<sup data-n=\"456\">36</sup>, ואילו ע\"י עסק התורה ומצות, שהם חכמתו ורצונו של הקב\"ה, הרי \"אור ה' ממש\" מקיף ומלביש את הנפש \"מראשה ועד רגלה\"<sup data-n=\"457\">37</sup>.\nומטעם זה מדגיש אדה\"ז שד' אותיות של שם הוי' בנפש הן \"סדר השתל­שלות\"<sup data-n=\"458\">38</sup>, שכוונת כולן היא להביא ל­\"עבודה האמיתית בעסק התורה והמצות\" [ד\"שכל הנעלם המרומז באות יו\"ד. . בכחו לצאת אל הגילוי להבין כו'\", ומ­ההתבוננות כו' \"נמשכה עבודה האמיתית כו'\"] — לרמז, שע\"י \"עסק התורה וה­מצות\" מתגלה זה שנשמתו היא \"חלק משם הוי' ב\"ה\".\nז. עפ\"ז יש לבאר הטעם שאדה\"ז מצרף הענין ד\"להשכיל באמתתו\" (חכ­מה) לענין ההבנה (בינה) [והיו\"ד קאי על \"שכל הנעלם\" (כנ\"ל סעיף ג)]:\nלפי הנ\"ל יש מקום לומר, שהעבודה הנרמזת באותיות י\"ה (\"שכל הנעלם. . מעמיק שכלו ומרחיב דעתו להתבונן. . אהבה ויראה כו'\") הוא רק ענין של הכנה והקדמה ושורש ל\"עבודה האמיתית ב­עסק התורה והמצות\" עצמה, ולפ\"ז, בכו­חות אלו (מצ\"ע) לא נרגש באופן גלוי ש­הן \"חלק משם הוי' ב\"ה\" (כיון שענינן — שכל ורגש של נברא, כנ\"ל).\nועיקר השאלה הוא בנוגע לאות יו\"ד — \"שכל הנעלם\":\nבנוגע לאהבת ה' ויראתו (ובפרט כשהן \"בבחי' התגלות לבו\"<sup data-n=\"459\">39</sup>) יש לומר, דכיון ש\"הם המתלבשים במעשה המצות להחיותם\"<sup data-n=\"460\">40</sup> — ובפשטות, שהן גורמות חיות והתלהבות בקיום התומ\"צ, שעי\"ז הקיום הוא בתכלית השלימות — הרי נמצא, שגם הן חלק מ\"עבודה האמיתית בעסק התורה והמצות\";\nואפילו בנוגע לההתבוננות בגדולתו ית' (דבינה) יש לומר, ע\"פ הידוע שה­מוחין אינם רק השורש ומקור אל המדות (הנולדות מהם), אלא שהם החיות של ה­מדות (דככל שתתגדל ההשגה בטיב הד­בר, כך תתגדל מדת האהבה והתשוקה אל הדבר ההוא כו') — וא\"כ, גם \"בינתו והתבוננותו\"<sup data-n=\"461\">41</sup> הן חלק מה\"עבודה האמי­תית בעסק התורה והמצות\";\nאבל בנוגע לענין החכמה, שהיא רק",[["456","36","ראה בארוכה תניא פל\"ה (מד, סע\"א ואילך), ד\"נשמת האדם (מצד עצמה) אפילו הוא. . עובד ה' ביראה ואהבה. . אינה בטילה במציאות לגמרי. . רק הוא דבר בפני עצמו ירא ה' ואוהבו. . זה האוהב שהוא יש ולא אפס לית מחשבה דילי' תפיסא בי' כלל, ואין אור ה' שורה ומתגלה בו אלא ע\"י קיום המצות שהן רצונו וחכמתו ית' ממש\".\nוראה גם תניא פ\"ד, מעלת \"לבושי\" הנפש (שהם מחשבה דיבור ומעשה של התורה ומצותי') על מעלת נפש רוח ונשמה עצמן. ע\"ש."],["457","37","ל' התניא פ\"ד שם (ח, סע\"ב). וראה גם שם פמ\"ו (סו, א)."],["458","38","וי\"ל שגם בביאור ד' אותיות שם הוי' למעלה מרמז אדה\"ז ענין זה, בהדגישו \"ואח\"כ כשנמשכת המשכה והשפעה זו יותר למטה\", שכל ד' אותיות השם הן המשכה אחת."],["459","39","כהדגשת אדה\"ז באגה\"ת כאן."],["460","40","תניא פט\"ז (כב, סע\"א)."],["461","41","ראה לקמן ס\"ט, שזהו גם טעם כפל ה­לשון \"מבינתו והתבוננותו\". ע\"ש."]]],[1301870131,"נקודת השכל, השורש ומקור לההתבו­ננות דבינה — לכאורה אינו שייך לומר שהיא \"נמצאת\" ב\"עסק התורה והמצות\" עצמו.\nוכדי לשלול קס\"ד זו (שחכמה היא רק שורש ומקור לההתבוננות) — מצרף אדה\"ז \"להשכיל\" עם ענין הבינה, ומדגיש \"(להשכיל) באמתתו ית'\", שבזה מדגיש שנקודת החכמה \"נמצאת\" גם בהרחבת הביאור דבינה, והיינו מה שהיא \"שומרת\" את \"ההרחבה\" דבינה לא לנטות מאמיתית הענין. וכידוע<sup data-n=\"462\">42</sup>, שמצד ה\"רוחב\" דבינה, למצוא ריבוי סברות לכאן ולכאן, אפשר לתעות בדרך עקלתון, ונקודת הענין (נקודת החכמה) היא השומרת על השקו\"ט של השכל, שלא לסטות מהאמת — ונמצא שגם \"חכמה\" שבנפש מלובשת ב\"עבודה האמיתית בעסק התורה וה­מצות\", כיון שהיא נקודת ה\"אמת\" שבהה­תבוננות כו'<sup data-n=\"463\">43</sup> (החיות של (המדות ו)עסק התורה והמצות).\n[וזהו גם הטעם שאדה\"ז מדייק להביא ענין \"שכל הנעלם\" (שלמעלה מחכמה גלוי' כנ\"ל) — כי \"התכללות\" זו של ב' הכחות דחכמה ובינה<sup data-n=\"464\">44</sup>, שגם בעת שה­אדם עסוק בהרחבת הביאור, אינו שוכח על נקודת החכמה, הוא מצד שורשם ב­\"שכל הנעלם\" (כח המשכיל), ששם הם בהתאחדות].\nח. אלא שלאחרי כל זה, עדיין אין הענין ברור, כי סו\"ס אין לשכל שבראש \"קירוב\" כ\"כ ל\"עסק התורה והמצות בקול ודבור או מעשה\", וכמבואר ב­תניא<sup data-n=\"460\">40</sup> שאהבה ויראה שבלב \"הם המת­לבשים במעשה המצות להחיותם. . כי הלב הוא ג\"כ חומרי כשאר אברים שהם כלי המעשה אלא שהוא פנימי וחיות להם\", משא\"כ ענין השכל שבמוח<sup data-n=\"466\">45</sup> הוא \"למעלה<sup data-n=\"467\">46</sup> מעלה מבחי' המעשה\".\nולכן מוסיף אדה\"ז עוד הסברה בשיי­כות של אותיות י\"ה שבנפש לתורה — \"וגם ההתבוננות להבין ולהשכיל כו' נמ­שכה ג\"כ מהתורה\". כלומר: השייכות דהתבוננות לעסק התורה והמצות אינה רק מצד היותה \"אם\" ומקור למדות (אהבת ה' ויראתו), ש\"הם המתלבשים במעשה ה­מצות להחיותם\" — אלא מצד ההתבוננות עצמה, ש\"ההתבוננות להבין ולהשכיל באמתתו וגדולתו ית' [שבזה נכללת הן \"להבין\" — בינה, והן \"להשכיל\" — נקודת החכמה] נמשכה ג\"כ מהתורה\"; וכיון \"דאורייתא מחכמה נפקא היא בחי' יו\"ד של שם הוי\"<sup data-n=\"468\">47</sup>, הרי נמצא, שבענין ההת­בוננות כו' עצמה (שנמשכה מהתורה) יש הארת שם הוי' דלמעלה בנפש האדם.\n[ועפ\"ז יומתק יותר הטעם שבסוף ה­פרק נקט \"אמתתו וגדולתו ית'\" (ולא \"באמתתו ית' ובגדולתו\"), המדגיש ש­שניהם קשורים זב\"ז (כנ\"ל סעיף ד) — כי כשנרגש שההתבוננות כו' נמשכה מהתו­",[["462","42","ראה סה\"מ עת\"ר ע' ג. ובכ\"מ."],["463","43","וי\"ל שזהו גם טעם השינוי שבבינה עצמה נקט \"גדולתו ית'\" וב\"אורך\" הבינה להוליד ממנה מדות נקט \"גדולת ה'\" (ראה לעיל הערה 8) — כי בבינה עצמה נרגשת פעולת החכמה, ולכן אומר \"גדולתו ית'\" (המדגיש יותר שהגדולה קשורה בו ית'), משא\"כ אח\"כ אומר \"גדולת ה'\" (בב' תיבות)."],["464","44","ראה בארוכה ד\"ה החלצו תרנ\"ט ספכ\"ג (סה\"מ תרנ\"ט ס\"ע עג) ואילך, וש\"נ — בענין \"הבן בחכמה וחכם בבינה\" (ס' יצירה פ\"א מ\"ד)."],["460","40","תניא פט\"ז (כב, סע\"א)."],["466","45","ואפילו \"דחילו ורחימו שבתבונות מוחו ותעלומות לבו\" — תניא פט\"ז (שם, ריש ע\"ב)."],["467","46","ל' התניא שם."],["468","47","ולא דנפש האדם."]]],[1301870132,"רה, שהיא תורת אמת, אזי מלכתחילה אין מקום להפריד בין \"אמתתו\" ו\"גדולתו\"<sup data-n=\"469\">48</sup>].\nט. ע\"פ כל הנ\"ל יש לבאר גם הערת אאמו\"ר בהמשך הענין, שמדייק בלשון אדה\"ז \"מבינתו והתבוננותו\" — \"נקט ב' לשונות מבינתו והתבוננותו, וכן מקודם נקט ב' הלשונות הללו, ובינתו להתבונן כו'\" [וגם כאן סומך על המעיין שיעמוד מעצמו על טעם השינויים].\nולכאורה יש לדייק בדבריו:\nא) למה מעיר על פעם הב' שנאמרה לשון כפולה זו אלא שאח\"כ מוסיף \"וכן מקודם נקט ב' הלשונות כו'\" — לכאורה הו\"ל להעיר תחילה על הפעם הא' \"ובי­נתו להתבונן\", ואח\"כ להוסיף \"וכן אח\"כ נקט ב' הלשונות כו'\"?\nב) בסוף הפרק נקט אדה\"ז עוד פעם ב' לשונות אלו (אלא שבסדר הפוך) — \"וגם ההתבוננות להבין\"; ולמה לא ציין אאמו\"ר גם לזה (ובפרט שבהערה הקו­דמת, ע\"ד ב' הלשונות \"אמתתו\" ו\"גדו­לתו\", מציין השינויים בזה שבסוף הפרק, כנ\"ל)?\nויש לומר הביאור בזה:\nכשמחלקים בין ב' הלשונות \"בינה\" ו\"התבוננות\"<sup data-n=\"470\">49</sup> — הנה \"בינה\" קאי על עצם הבנת הדבר, ו\"התבוננות\" היינו ההעמקה וההסתכלות בהענין באופן ש­יפעול עליו כו'. וע\"ד ענין ה\"תבונה\" — \"אותיות בן ובת\"<sup data-n=\"471\">50</sup> (אהבה ויראה, תולדות ההתבוננות), דענין ה\"תבונה\" קאי על דרגת השכל כפי שיורדת להוליד מדות.\nוזוהי כוונת אאמו\"ר בציינו כפל ה­לשון ד\"בינתו והתבוננותו\", שהן ב' דר­גות בשכל — בינה (שלמעלה ממדות) והתבוננות (שכל השייך למדות).\nולכן, עיקר הדיוק בל' \"התבוננות\" כאן הוא כשמדבר ב\"אורך\" של הה\"א, \"המורה על ההמשכה. . להוליד מבינתו והתבוננותו. . אהבה ויראה כו'\", שבזה פשוט שהכוונה לשכל השייך למדות, אלא שמזה מובן, דזה שגם \"מקודם [ב­תחילת ביאור אות ה\"א] נקט ב' הלשונות הללו, ובינתו להתבונן\", כוונתו לענין ה­התבוננות שממנה נולדו המדות.\nוע\"פ הנ\"ל (סעיף ו') שכוונת אדה\"ז לבאר שגם עבודת ההתבוננות כו' היא בשביל \"עבודה האמיתית בעסק התורה והמצות\", מובן הטעם שמדגיש כאן הקשר שבין שכל ומדות, שאינו רק בכך שהשכל הוא מקור למדות, אלא עוד זאת, שמציאות המדות מתחלת בשכל עצמו, והוא ענין ההתבוננות (\"תבונה אותיות בן ובת\"), שמזה מובן גם לאידך, שהשכל מתלבש בהמדות להחיותם כו'.\nועפ\"ז מתורץ גם הטעם שלא ציין",[["469","48","ראה ד\"ה החלצו שם פ\"ל (סה\"מ תרנ\"ט ע' עט) ואילך, ע\"ד התכללות חו\"ב ע\"י התורה. ושם, שזהו לפי ששורש התורה הוא \"מבחי' שעשועים העצמים דא\"ס\" [ע\"ד הנ\"ל סוס\"ז בענין התכללות חכמה ובינה ע\"י \"שכל הנעלם\"].\nויש לומר, שענין זה נרמז בלשון אדה\"ז כאן \"אורייתא מחכמה נפקא\", כהפירוש בזה, שרק הגילוי (\"נפקא\") דתורה הוא מחכמה, אבל שורש התורה עצמה הוא בכתר<sup data-n=\"e15\">*</sup> (תו\"א לך יא, ג. לקו\"ת במדבר ז, א. ובכ\"מ)."],["470","49","ראה סה\"מ תר\"ן ע' שב ואילך. ועוד."],["471","50","זהר וע\"ח — הובאו בתניא ספט\"ז ב­הגה\"ה."],["e15","*","ולהעיר, שלעיל (בשם הוי' למעלה) כ' אדה\"ז ש\"הקוץ שעל היו\"ד רומז לבחי' רצון העליון ב\"ה\" — ולא ביאר ענינו בנפש האדם."]]],[1301870133,"אאמו\"ר כפל הלשון בסיום הפרק — כי שם אין כוונת אדה\"ז להדגיש את הקשר בין שכל ומדות, אלא אדרבה, שההת­בוננות עצמה נמשכה מהתורה, כנ\"ל ב­ארוכה. ובמילא מובן, שאין הכוונה בל' \"התבוננות\" כאן לדרגת השכל השייך למדות, אלא ההתבוננות דשכל עצמו, \"להבין ולהשכיל באמתתו וגדולתו ית'\".\n<span data-k=\"q\">(משיחות ש\"פ נח וש\"פ תולדות תשל\"א)</span>"],[1301870134,"<h3>אגרת התשובה ג</h3>\nא. באגרת התשובה פרק ה מבאר אדמו\"ר הזקן, ש\"ירידת הנפש האלקית לעוה\"ז להתלבש בגוף האדם נמשכה מבחי' פנימיות ומקור הדיבור הוא הבל העליון. . וכמ\"ש<sup data-n=\"472\">1</sup> ויפח באפיו נשמת חיים ויהי האדם לנפש חי'\", ולכן, \"כמו שעד\"מ כשהאדם נופח לאיזה מקום אם יש איזה דבר חוצץ ומפסיק בינתיים אין הבל הנופח עולה ומגיע כלל לאותו מקום, ככה ממש אם יש דבר חוצץ ומפ­סיק בין גוף האדם לבחי' הבל העליון\", והם עוונות האדם, כמ\"ש<sup data-n=\"473\">2</sup> \"עוונותיכם היו מבדילים ביניכם לבין אלקיכם\", \"וזהו ענין הכרת, שנכרת ונפסק חבל ההמשכה משם הוי' ב\"ה. . וכמ\"ש<sup data-n=\"474\">3</sup>. . ונכרתה הנפש ההיא מלפני אני ה', מ­לפני דייקא\".\nובהערות אאמו\"ר על אגרת התשובה<sup data-n=\"475\">4</sup> מעיר על כפל הלשון (במשל הנ\"ל) \"אין הבל הנופח עולה ומגיע כלל לאותו מ­קום\", ומפרש \"הב' לשונות עולה ומגיע י\"ל לנגד רצוא ושוב כי החיות הוא בבחי' רצוא ושוב. ועיין באגרת הקודש פל\"א\".\n— באגה\"ק שם מבואר, דזה שהשכינה נקראת \"לב\"<sup data-n=\"476\">5</sup> ונשמות ישראל נקראות \"אברי דשכינתא\"<sup data-n=\"477\">6</sup>, הוא משום שנשמות ישראל מקבלות חיותם<sup data-n=\"478\">7</sup> מהשכינה בדרך \"רצוא ושוב\", כמו החיות הנמשכת מן הלב אל האברים ע\"י הדם (שבו מלובשת חיות הנפש, \"הדם<sup data-n=\"479\">8</sup> הוא הנפש\"), שהיא תמיד באופן של \"רצוא ושוב\", שהרי הדם מתפשט בכל האברים וחוזר אל הלב ואח\"כ שוב מתפשט אל האברים כו'.\nב. ונראה לומר, שכוונת ההערה אי­נה רק לבאר כפל הלשון \"עולה ומגיע\", אלא גם ליישב ולתרץ הביטוי \"עולה (ומ­גיע)\", שלפום ריהטא אינו מובן: המשל ד\"אדם (ה)נופח כו'\" הוא על ענין המשכת וירידת החיות מ\"הבל העליון\" לנפש האלקית כפי שהיא מלובשת בגוף האדם, וא\"כ נוסף לזה שתיבת \"עולה\" היא יתור לשון [והי' יכול לכאורה לומר \"אין הבל הנופח מגיע כלל\"<sup data-n=\"480\">9</sup>] — היא לכאורה היפך תוכן הנמשל, ירידת החיות מהבל העליון (ולא — עלייתה)!\nומתרץ אאמו\"ר שכפל הלשון \"עולה ומגיע\" הוא \"לנגד רצוא ושוב, כי החיות הוא בבחי' רצוא ושוב\", ובמילא מתאים גם לשון \"עולה\" (כנגד \"רצוא\").\nועצ\"ע קצת סדרן של ב' הלשונות",[["472","1","בראשית ב, ז."],["473","2","ישעי' נט, ב."],["474","3","אמור כב, ג."],["475","4","לקוטי לוי יצחק על תניא — ע' ל."],["476","5","תקו\"ז תי\"ג (כט, א). תכ\"א (מט, ריש ע\"ב. נב, א. ועוד)."],["477","6","זח\"ג יז, א. רלא, סע\"ב (ברע\"מ). תקו\"ז תכ\"א (נב, א)."],["478","7","ובפשטות, זהו הטעם שמציין לאגה\"ק, אף שזה שהחיות האלקית היא בבחי' רצוא ושוב מבו­אר בריבוי מקומות, והובא גם בתניא ח\"א ספמ\"א (מס' יצירה) — כי באגה\"ק מבואר זה לענין המש­כת החיות לנשמות (ולא כללות חיות העולמות). — וראה לקמן סעיף ז."],["479","8","פ' ראה יב, כג. ועד\"ז פ' אחרי יז, יא. ועוד."],["480","9","ולהעיר, שבאגה\"ת מהד\"ק (בהוצאת קה\"ת (תשמ\"ב) ע' תקי) \"לא יבא שם הרוח\"."]]],[1301870135,"\"עולה ומגיע\" (\"עולה\" לפני \"מגיע\") — דלכאורה הי' צ\"ל סדרן הפוך (תחילה \"מגיע\" ואח\"כ \"עולה\"), שהרי בנמשל, המשכת וירידת \"הבל העליון\" לנשמת האדם, תחילה נמשכת החיות למטה, ואח\"כ \"עולה\" לשרשה ומקורה<sup data-n=\"481\">10</sup>.\nועוד זאת — למאי נפק\"מ כאן, לתוכן המשל מאדם ה\"נופח לאיזה מקום\", זה ש\"החיות הוא בבחי' רצוא ושוב\"? והרי במשל זה אין ענין של \"רצוא ושוב\"<sup data-n=\"482\">11</sup>.\nויש לומר, שאדרבה: ע\"י הוספה זו ד\"עולה ומגיע\" המרמזת על כך ש\"הח­יות הוא בבחי' רצוא ושוב\" — ובסדר ד\"עולה\" קודם \"ומגיע\" — מבואר ומוס­בר תוכן ביאור אדה\"ז בפרק זה, כדלקמן.\nג. תוכן פרק זה הוא לבאר גדר עונש כרת ומיתה בידי שמים<sup data-n=\"483\">12</sup>, שאינו דבר צדדי ע\"י \"פעולה\" נוספת כעונש על החטא, דכשעובר עבירה שיש בה כרת נענש בעונש זה — אלא הוא עונש טבעי הנמשך מהעבירה בדרך ממילא, דכשעובר עבירה שיש בה כרת נכרתה נשמתו ממקור חיותה, וממילא אינו יכול לחיות יותר מנ'<sup data-n=\"484\">13</sup> שנה.\nוזה הוא רק בישראל, לפי שנשמת ישראל היא \"מבחי' פנימיות ומקור הדי­בור, הוא הבל העליון המרומז באות ה\"א תתאה (של שם הוי')\"<sup data-n=\"485\">14</sup>, שלכן, ע\"י עוונו­תיכם ה\"מבדילים ביניכם לבין אלקיכם\", \"נכרת ונפסק חבל ההמשכה משם הוי' ב\"ה שנמשכה מה\"א תתאה\" (מקור חיות נשמת האדם),\nמשא\"כ בשאר נבראים לא מצינו ענין הכרת, לפי שהם \"חיים וקיימים\" (רק) מ\"רוח פיו\" שהוא החיות המלובש \"ב­אותיות שבעשרה מאמרות\"<sup data-n=\"486\">15</sup>, דיבור (לא \"הבל העליון\") [כפי שמבאר אדה\"ז ב­ארוכה בפרק הקודם<sup data-n=\"487\">16</sup> ההפרש ה\"עצום מאד\" שבין כל הנבראים ובין נשמת האדם, שהוא כההפרש שבין ההבל שיוצא מפיו בדיבורו (ש\"מלובש בו כח וחיות מעט מזעיר. . חיצוניות מנפש החי' שבקרבו\") להבל היוצא ע\"י נפיחה, ש\"מלובש בו כח וחיות פנימי'\" דהנפש].\nהיינו: אע\"פ שגם שאר הברואים חיים וקיימים אך ורק מדבר ה' ורוח פיו ית'<sup data-n=\"488\">17</sup>, מ\"מ, חיות זו המלובשת בדיבורו ית' אי­נה נפסקת<sup data-n=\"489\">18</sup> ע\"י עונות<sup data-n=\"490\">19</sup>, וכריתת \"חבל\"",[["481","10","ואף שהלשון הוא \"רצוא ושוב\" — הרי כיון שהמדובר בהמשכת וירידת החיות, היינו רצו\"ש שבאור (לגבי כלים), הרי \"הרצוא הוא בחי' מטי דהיינו התפשטות האור, והשוב הוא בחי' ולא מטי שהוא בחי' הסתלקות האור מן הכלי, כי מצינו אשר רצוא יהי' פירושו המשכה\" (סה\"מ תש\"ה ע' 3. ע\"ש)."],["482","11","באגה\"ק שם מבאר ענין החולי הנעשה ע\"י \"קלקול באיזהו מקומן המונע ומעכב או ממעט סיבוב והילוך הדם. . אזי נפסק או מתמעט הקשר הלז המקשר כל האברים אל הלב ע\"י סיבוב הלז\".\nאבל לכאורה זהו ביאור נוסף, ואינו שייך לתוכן המשל דאדם הנופח לאיזה מקום אם יש איזה דבר חוצץ כו'."],["483","12","שהתחיל בו אדה\"ז בריש פ\"ד."],["484","13","בכרת, וס' שנה במיתה בידי שמים (אגה\"ת פ\"ד שם. והוא כשיטת הירושלמי בכורים רפ\"ב — כפי' התוס' (שבת כה, א ד\"ה כרת. ועוד). — נת' בלקו\"ש ח\"ה ע' 134 הערה 21)."],["485","14","אגה\"ת כאן (רפ\"ה)."],["486","15","אגה\"ת פ\"ד (צד, א)."],["487","16","שם."],["488","17","כמשנ\"ת בארוכה בתניא ח\"ב פ\"א­ג."],["489","18","כמו במשל, שרק הבל הנופח אינו מגיע כשיש חציצה, אבל דיבורו של אדם נשמע (\"מגיע\") גם כשיש חציצה."],["490","19","אף שהם \"נגד רצון העליון ב\"ה המחי' את הכל כמ\"ש (תהלים קלה, ו) כל אשר חפץ ה' עשה בשמים ובארץ\" (המשך ל' אדה\"ז באגה\"ת כאן — צה, ב), היינו שלא רק \"שהוא מקור השפעת שם הוי'\" (אגה\"ת שם), אלא גם בשמים וארץ — ומ\"מ אין העונות גורמים הפסק החיות.\nויש לומר ההסברה בזה: \"רצון העליון ב\"ה\" מורה על הכוונה, הפנימיות של החיות, ולכן עשיית דבר שהוא \"נגד רצון העליון ב\"ה\" פוגע רק בפנימיות החיות, ולא בחיצוניות החיות, שהיא ה­חיות המלובשת בדיבורו ית'. וראה לקו\"ת שמע\"צ פב, סע\"א."]]],[1301870136,"המשכת החיות שמאתו ית' הוא רק בנוגע לפנימיות החיות (\"הבל העליון\").\nד. ולכאורה יש לעיין גם בנוגע לבני ישראל, ובהקדים:\nלעיל בפ\"ד<sup data-n=\"487\">16</sup>, לאחרי שמבאר שנשמת האדם היא \"מפנימיות החיות והשפע. . כמ\"ש ויפח\", מוסיף: \"וגם אח\"כ ירדה. . ע\"י בחי' האותיות שבמאמר נעשה אדם<sup data-n=\"492\">20</sup> וכו' כדי להתלבש בגוף עוה\"ז התחתון\".\nומזה מובן, דמ\"ש אח\"כ (בריש פ\"ה), ש\"המשכת וירידת הנפש האלקית ל­עוה\"ז להתלבש בגוף האדם נמשכה מבחי' פנימי' ומקור הדיבור הוא הבל ה­עליון\" — אין הכוונה שהחיות המלובשת ב\"הבל העליון\" היא היא המתלבשת בנש­מת האדם כפי שהיא למטה בעוה\"ז בגוף, אלא היא צריכה להתצמצם ולהתלבש תחילה ב\"אותיות שבמאמר נעשה אדם\", שאין זה \"הבל העליון\" (\"פנימי' ומקור הדיבור\"), אלא דיבור ממש.\nדהנה בפרק ה מוסיף חידוש עיקרי בענין \"ויפח\" לגבי המבואר לעיל (פרק ד):\nמשנ\"ת לעיל שהנשמה היא \"חלק<sup data-n=\"493\">21</sup> משם הוי' ב\"ה כדכתיב ויפח באפיו נשמת חיים ומאן דנפח מתוכו נפח\", קאי על שורש הנשמה למעלה [והמשל ד­\"ויפח\" הוא לענין זה, שכמו שב\"הבל היוצא ע\"י נפיחה\" מלובש \"כח וחיות פנימי' מבחי' הנפש החי'\"<sup data-n=\"494\">22</sup>, כך שורש נשמת האדם \"היא<sup data-n=\"495\">23</sup> מבחי' פנימי' הח­יות<sup data-n=\"496\">24</sup> היא חלק שם הוי' ב\"ה\"];\nמשא\"כ בפ\"ה מחדש, שגם \"המשכת וירידת הנפש האלקית לעוה\"ז להתלבש בגוף האדם נמשכה מבחי' פנימיות ומ­קור הדיבור הוא הבל העליון\"<sup data-n=\"497\">25</sup> [ולכן: (א) ענין זה אינו שייך לכללות שם הוי' אלא רק ל\"הבל העליון<sup data-n=\"498\">26</sup>, המרומז באות ה\"א תתאה\"<sup data-n=\"499\">27</sup>, (ב) בזה מוסיף אדה\"ז \"וכמ\"ש ויפח באפיו נשמת חיים ויהי האדם לנפש חי'\", להדגיש, שכאן הכוונה לשורש המ­שכת הנפש למטה להיות \"נפש חי'\", שזהו ע\"י התלבשות הנשמה בגוף, שגם זה בא מ\"ויפח\"].\nאבל אעפ\"כ מובן ע\"פ הנ\"ל, שכדי שתהי' התלבשות הנשמה בגוף בפועל, צריכה החיות להתלבש תחילה גם באו­תיות הדיבור, \"במאמר נעשה אדם\".\nועפ\"ז נמצא, שהנשמה כפי שהיא \"",[["487","16","שם."],["492","20","בראשית א, כו."],["493","21","צג, סע\"ב."],["494","22","שם צד, רע\"א."],["495","23","שם, סע\"א."],["496","24","ע\"ד פנימיות החיות המלובשת בכח ה­נופח."],["497","25","וזהו ענין ה\"נפיחה\" גופא."],["498","26","ועפ\"ז י\"ל, דזה שכאן בפ\"ה מקצר \"ומאן דנפח וכו'\", דלא כדלעיל שאומר \"מאן דנפח מתו­כו נפח\", הוא (לא רק לפי שסומך אדלעיל, אלא) — כי פנימיות זו אינה \"מתוכו ממש\" (פנימיות החיות המלובשת בהבל), אלא רק \"פנימיות ומקור הדי­בור. . הבל העליון\"."],["499","27","\"דבר ה'\", שעל ידו הוא הגילוי \"לאחרים\" (לעיל פ\"ד — צד, ב)."]]],[1301870137,"באפיו\" נמשכת (לא מ\"ויפח\", אלא) מ­\"האותיות שבמאמר נעשה אדם\", החיות המלובשת בדיבורו ית'. וצריך ביאור — למה נמשלה המשכת החיות לנשמת ה­אדם כפי שהיא בגוף, לאדם ה\"נופח לאי­זה מקום\" (ובמילא, שע\"י עונות \"נכרת ונפסק חבל ההמשכה\", כמו דבר המפסיק את הבל הנפיחה)?\nוצ\"ל, שגם לאחרי שהחיות ד\"ויפח\" מתלבשת ב\"אותיות שבמאמר נעשה א­דם\", לא נשתנתה מהותה, וה\"ה עדיין חיות פנימית (\"ויפח\")<sup data-n=\"500\">*27</sup>.\nויש לומר, שהביאור לענין זה נרמז בלשון אדה\"ז ש\"אין הבל הנופח עולה ומגיע כלל כו'\", וכפירוש אאמו\"ר שזה בא להורות ש\"החיות הוא בבחי' רצוא ושוב\".\nה. ביאור הענין:\n\"רצוא\" ו\"שוב\" הם שני הפכים, ולא רק משום שהם תנועות הפכיות, זו בעלי' למעלה וזו בהמשכה וירידה למטה, אלא הוא חילוק יסודי יותר:\nענין ה\"רצוא\" פירושו, העלי' למקורו כפי שהוא למעלה ומושלל מענין הירידה למטה (באופן ששם אין מקום להחיות המתפשטת למטה) — ע\"ד טבע העלי' (רצוא) שבאש, \"שאור<sup data-n=\"501\">28</sup> האש חפץ בטבע ליפרד מהפתילה ולידבק בשרשו למעלה. . אף שעל ידי זה יכבה ולא יאיר כלום למטה, וגם למעלה בשרשו יתבטל אורו במציאות בשרשו\"; וענין ה\"שוב\" מורה על הפירוד ממקורו והירידה למטה ול­התלבש בדבר שלמטה ממנו.\nוזה שהקשר בין החיות האלקית ל­שרשה ומקורה הוא באופן של \"רצוא ושוב\", מורה על שני הפכים בענין ה­חיות: זה שיש בה ענין ה\"רצוא\" מורה, שחיות זו אינה חיות חיצונית לבד אלא מהותה ושרשה בעצם המקור<sup data-n=\"502\">29</sup> כפי שהוא למעלה מענין הירידה למטה, ולכן יש בחיות זו התנועה התמידית ד\"רצוא\", שזוהי דביקותה במקורה ושרשה (כפי שהוא למעלה מירידה והמשכה למטה); אלא שביחד עם זה יש בה ה\"שוב\", ש­עי\"ז נמשך החיות ממקורה ושרשה בדבר נפרד שלמטה ממנו, שזהו ע\"י ה\"שוב\", ההמשכה וירידה למטה.\nונמצא, שזה ש\"החיות הוא בבחי' רצוא ושוב\" מורה על המשכת מקור הח­יות<sup data-n=\"503\">30</sup> (שלמעלה מהמשכה וירידה) להח­יות דבר שחוץ ממנו.\nוזהו שמרמז אדה\"ז כאן, שהמשכת וירידת החיות לנשמת האדם היא באופן של \"רצוא ושוב\", שמזה מובן, שגם כפי שהחיות מתלבשת באותיות הדיבור (ב­מאמר נעשה אדם), שזהו תכלית ענין ה\"שוב\", הרי מהות חיות זו היא \"פני­מיות<sup data-n=\"495\">23</sup> החיות (משם הוי') שהיא למעלה מעלה מבחי' האותיות\" (תכלית ה\"ר­צוא\"), אלא שזהו כפי שהחיות דשם הוי'",[["500","*27","ראה גם לעיל ע' 62. לקמן ע' 76 (ס\"ה). ע' 138."],["501","28","ל' התניא ח\"א רפי\"ט."],["502","29","עיין המשך תער\"ב ח\"ב ס\"פ שלד, מעלת הדביקות ד\"כח\" על הדביקות ד\"אור\"."],["503","30","ועד\"ז הוא בחיות הנפש, שהיא בדרך \"רצוא ושוב\" (כנ\"ל מאגה\"ק) — שזהו לפי שחיות הנפש המחי' את הגוף דבוקה בעצם הנפש, שהיא \"חי בעצם\". כי זה שהנפש מחי' את הגוף באופן שהגוף עצמו נעשה דבר חי (ולא רק שחיות הנפש מתפשטת ונמצאת בהגוף), ה\"ז מפני שחיות זו דבוקה בהנפש עצמה, דלהיותה \"חי בעצם\" לכן היא \"חי להחיות\" (ראה ד\"ה ויקח ה\"א תשי\"ב. ד\"ה בראשית תשי\"ג)."],["495","23","שם, סע\"א."]]],[1301870138,"מתלבשת באותיות הדיבור (שלכן היא \"בבחי' רצוא ושוב\", כנ\"ל) — ולכן גם לאחרי התלבשות החיות באותיות הדי­בור, ה\"ז \"עד\"מ כשהאדם נופח כו'\".\nו. עפ\"ז יש לבאר גם דיוק לשון אדה\"ז כאן, שלפני שמביא המשל ד\"כש­האדם נופח לאיזה מקום אם יש איזה דבר חוצץ כו'\", מקדים: \"כי הנה פשט הכתוב מ\"ש ויפח הוא להורות לנו (כמו שעד\"מ כשהאדם נופח כו')\", דלכאורה הוא יתור לשון.\n[ובפרט, שלעיל בפרק ד', כשמביא ב­פעם הא' הענין ד\"ויפח גו'\", ומבאר תוכן המשל שבזה (ההפרש \"בין ההבל שיוצא מפיו בדיבורו להבל היוצא ע\"י נפיחה\") — אינו מקדים ד\"מ\"ש ויפח הוא להורות לנו\" (או כיו\"ב)].\nגם: למה נקט לשון \"להורות\" (ולא — \"פירושו\", \"תוכנו\" וכיו\"ב)?\nוע\"פ הנ\"ל יש לבאר זה:\nכדי לבאר ענין ה\"כרת\" (שע\"י עונות נפסקת החיות המלובשת בגוף), מוכרח לומר, שהענין ד\"ויפח\" הוא לא רק בנוגע לשורש הנשמה למעלה, או אפילו לשו­רש המשכתה למטה (שהוא מה\"א תתאה כנ\"ל) — אלא גם בנוגע לחיות הנשמה כפי שהיא מלובשת בגוף. והיינו שהענין ד\"ויפח\" ישנו בכל הדרגות דהמשכת ה­נשמה, גם כפי שנמשכת בגוף (וגם לאח\"ז — כל משך זמן היותם \"אדם\", נשמה וגוף יחד). ולכן \"אם יש דבר חוצץ ומפסיק בין גוף האדם לבחי' הבל העל­יון\" הרי עי\"ז \"נכרת ונפסק חבל ההמ­שכה משם הוי' ב\"ה\".\nוזהו דיוק לשון אדה\"ז \"כי הנה פשט הכתוב מ\"ש ויפח הוא להורות לנו\": \"פשט הכתוב\" ד\"ויפח באפיו\" קאי על התלבשות הנשמה בתוך הגוף, וענין זה בא \"להורות לנו\" [לא רק תוכן ענין \"ויפח\" גופא, אלא] שגם לאחרי הפעולה ד\"נעשה אדם\" (הת­לבשות הנשמה בגוף ע\"י התלבשות ה­חיות באותיות הדיבור), הרי גם אז (אף ש­הדיבור אינו מפנימיות) ה\"ז עדיין \"עד\"מ כשהאדם נופח כו'\", דענין זה לא נשתנה ע\"י התלבשות החיות באותיות הדיבור [ולכן אין זה \"תוכן\" ענין \"ויפח\" עצמו, שהרי בכתוב ד\"ויפח\" אין הכוונה להת­לבשות החיות באותיות הדיבור (דמאמר נעשה אדם)<sup data-n=\"505\">31</sup>, אלא זהו עוד ענין הנלמד מ\"פשט הכתוב\" שנאמר \"ויפח באפיו\"].\nז. ע\"פ כל הנ\"ל מובן גם הטעם שהקדים אדה\"ז \"עולה\" ל\"ומגיע\":\nאע\"פ ש\"ויפח באפיו\" קאי על המשכת וירידת החיות מלמעלה למטה בנשמה המתלבשת בגוף, הרי לעניננו, מה ש­\"ויפח\" בא \"להורות לנו\", ה\"ז נוגע (לא לשורש החיות כפי שנמשכת מלמעלה למטה לתוך הגוף, אלא) להחיות כפי שהיא מלובשת בגוף, שגם אז ה\"ה קשו­רה עם פנימיות החיות (שלכן ה\"ז כאדם הנופח כו'); ולהדגיש שמדובר בחיות המלובשת בגוף, נקט אדה\"ז הסדר ד­\"עולה ומגיע\", כי בחיות המלובשת בגוף הסדר הוא \"רצוא ושוב\", בתחילה \"רצוא\" (היציאה מהתלבשותה בגוף ועלייתה לשרשה ומקורה), ואח\"כ \"שוב\" — ירידה והמשכה תוך הגוף.\nויש לומר, שגם מטעם זה מציין אאמו\"ר (בסוף הערתו) לאגרת הקודש<sup data-n=\"506\">32</sup> — כי שם מבואר ענין ה\"רצוא ושוב\" בין החיות דשכינה ונשמות ישראל (אברי ד­",[["505","31","שהרי בפסוק \"ויפח\" לא נזכר ענין הדי­בור."],["506","32","ראה לעיל הערה 7."]]],[1301870139,"שכינתא) כמו הרצוא ושוב של הדם באב­רים, שעל זה נאמר<sup data-n=\"507\">33</sup> \"ושכנתי בתוכם\", המורה על התלבשות<sup data-n=\"508\">34</sup> החיות בנשמות ישראל. והיינו, שהמדובר כאן (א) אינו בדביקות החיות דשכינה (ה\"א תתאה) בשרשה ומקורה, אלא החיות השוכנת ומתלבשת בישראל עם שרשה ומקורה, (ב) וענין זה הוא באופן של \"רצוא ושוב\" כמו הדם, שעולה ללב, ושם מתחדשת חיותו, ונמשכת חיות חדשה לתוך אברי הגוף (בתחילה \"רצוא\" ואח\"כ \"שוב\").\nח. והנה בענין הנ\"ל מודגש ג\"כ זה ש\"אין לך דבר עומד בפני התשובה\"<sup data-n=\"509\">35</sup> — אפילו לאחרי שעבר אדם על עון כרת ו\"נכרת ונפסק חבל ההמשכה משם הוי' ב\"ה שנמשכה מה\"א תתאה\":\nההפסק שבין החיות האלקית וגוף האדם הוא רק בדרגת החיות כפי שנפ­רדת ממקורה ויורדת להתלבש בגוף (\"שוב\")<sup data-n=\"510\">36</sup>, משא\"כ כפי שהחיות היא ל­מעלה מהתלבשות בגוף, אין מקום לפי­רוד ב\"חבל ההמשכה\", והיא בדביקות תמידית עם מקורה ושרשה.\nהיינו, שלא זו בלבד שענין כריתת החבל אינו שייך בשורש הנשמה למעלה, אלא אפילו לא כפי שהיא נמשכת ויורדת מ\"פנימיות ומקור הדיבור הוא הבל ה­עליון\" כדי \"להתלבש בגוף האדם\" [ורק לאחרי התלבשותה בגוף האדם<sup data-n=\"510\">36</sup> שייך ענין כריתת החבל].\nוכיון שבדרגא זו לא שייך שום פגם בנשמת האדם, לכן משם נמשך באדם הכח לעשות תשובה, וע\"י תשובה — \"שוב<sup data-n=\"512\">37</sup> אין עונותיכם מבדילים. . ומאחר שרוח עברה ותטהרם אזי תוכל נפשם לשוב עד הוי' ב\"ה ממש ולעלות מעלה מעלה למקורה ולדבקה בו ית' ביחוד נפלא\".\n<span data-k=\"q\">(משיחת ש\"פ וישלח תשל\"א)</span>",[["507","33","תרומה כה, ח."],["508","34","ראה אגה\"ק שם: לשון שכינה הוא שאור הוי' שוכן בעולמות כו'. וראה תניא פמ\"א (נז, ב). שם פנ\"ב (עג, א). אגה\"ק סכ\"ה (קלט, א)."],["509","35","רמב\"ם הל' תשובה ספ\"ג, ע\"פ ירושלמי פאה פ\"א סה\"א; זהר חדש ס\"פ בראשית (יט, ד) — הובא באגה\"ת לעיל רפ\"ד."],["510","36","וכדיוק לשון אדה\"ז \"אם יש דבר חוצץ ומפסיק בין גוף האדם לבחי' הבל העליון\", שה­חציצה היא מצד גוף האדם. וכן בכתוב מדייק \"עוונותיכם היו מבדילים ביניכם לבין אלקיכם\", שההבדלה היא מצד \"ביניכם\", ולא מצד \"אלקיכם\" (אף שג\"ז קאי על החיות המלובשת בהאדם, \"אלקי­כם\")."],["510","36","וכדיוק לשון אדה\"ז \"אם יש דבר חוצץ ומפסיק בין גוף האדם לבחי' הבל העליון\", שה­חציצה היא מצד גוף האדם. וכן בכתוב מדייק \"עוונותיכם היו מבדילים ביניכם לבין אלקיכם\", שההבדלה היא מצד \"ביניכם\", ולא מצד \"אלקיכם\" (אף שג\"ז קאי על החיות המלובשת בהאדם, \"אלקי­כם\")."],["512","37","אגה\"ת פ\"ח."]]],[1301870140,"<h3>אגרת התשובה ד</h3>\nא. באגרת התשובה פרק ה' מבאר אדמו\"ר הזקן, דמ\"ש (בנוגע לנשמת ה­אדם) \"ויפח באפיו נשמת חיים\"<sup data-n=\"513\">1</sup>, \"ויפח\" דוקא, \"הוא להורות לנו, [ש]כמו שעד\"מ כשהאדם נופח לאיזה מקום אם יש איזה דבר חוצץ ומפסיק בינתיים אין הבל הנופח עולה ומגיע כלל לאותו מקום, ככה ממש אם יש דבר חוצץ ומפסיק בין גוף האדם לבחי' הבל העליון. אך באמת אין שום דבר גשמי ורוחני חוצץ לפניו ית' כי הלא את השמים ואת הארץ אני מלא<sup data-n=\"514\">2</sup> ומלא כל הארץ כבודו<sup data-n=\"515\">3</sup> ולית אתר פנוי מיני'<sup data-n=\"516\">4</sup> בשמים ממעל ועל הארץ מתחת אין עוד<sup data-n=\"517\">5</sup> ואיהו ממלא כל עלמין<sup data-n=\"518\">6</sup> וכו' אלא כמ\"ש בישעי'<sup data-n=\"519\">7</sup> כי אם עוונותיכם היו מבדילים ביניכם לבין אלקיכם\".\nוכתב אאמו\"ר בהערותיו על אגרת התשובה<sup data-n=\"520\">8</sup>, שזה ש\"הביא ד' ראיות [על זה ש\"אין שום דבר גשמי ורוחני חוצץ לפניו ית'\"], שנים הראשונים מפסוקים ושנים האחרונים ממאמרי רז\"ל בזהר הקדוש, הוא לנגד הד' אותיות דשם הוי' (כי נש­מת האדם נמשכה מד' אותיות דשם הוי', חלק שם הוי' ב\"ה, כנ\"ל בפ\"ד). על אותיות י\"ה. . שהם<sup data-n=\"521\">9</sup> הנסתרות לה' אלקינו<sup data-n=\"522\">10</sup>. . הביא פסוקים. ועל אותיות ו\"ה. . שהם<sup data-n=\"523\">11</sup> נגלות הביא מאמרי רז\"ל, כי פסוקים שהם בכתב ומאמרים שהם בע\"פ, הם כמו נסתרות לגבי נגלות\" [ואח\"כ מבאר בפרטיות התאמת פרטי הלשונות בכל א' מד' הראיות להאות המקבילה מד' אותיות הוי'].\nויש לדייק בדבריו, דלכאורה יש כאן ה' ראיות, כי \"לית אתר פנוי מיני'\" הוא מאמר הזהר, ו\"בשמים ממעל ועל הארץ מתחת אין עוד\" הוא לשון הפסוק, ולמה פירש אאמו\"ר ש\"בשמים ממעל ועל ה­ארץ מתחת אין עוד\" אינה ראי' בפ\"ע, אלא פרט בהראי'<sup data-n=\"524\">12</sup> (ממארז\"ל) \"לית אתר פנוי מיני'\"<sup data-n=\"525\">13</sup>.",[["513","1","בראשית ב, ז."],["514","2","ירמי' כג, כד."],["515","3","ישעי' ו, ג."],["516","4","תקו\"ז תנ\"ז. שם ת\"ע (קכב, ב). וראה לקמן הערה 13."],["517","5","ואתחנן ד, לט. — וראה לקמן בפנים ו­הערה 13."],["518","6","רע\"מ פינחס רכה, א."],["519","7","נט, ב."],["520","8","לקוטי לוי יצחק על תניא — ע' ל."],["521","9","תקו\"ז ריש תכ\"ב. ת\"ע (קכט, א). ועוד."],["522","10","ל' הכתוב — נצבים כט, כח."],["523","11","תקו\"ז ת\"ע שם. ועוד."],["524","12","וראה לקמן הערה 18."],["525","13","ועפ\"ז צ\"ל, לכאורה, שכוונת אדה\"ז היא להמאמר בתקו\"ז ת\"ע, ששם הובא בהמשך הענין הכתוב \"כי הוי' הוא האלקים בשמים ממעל ועל הארץ מתחת אין עוד\" — דלא כבתניא ח\"ב פ\"ז (פג, ב) שמעתיק ל' התקו\"ז תנ\"ז \"לית אתר כו' לא בעילאין ולא בתתאין\" (ולא הובא שם הכתוב ד­\"בשמים ממעל גו'\").\nויש לומר, שהטעם שמשנה כאן מלעיל ח\"ב, ומביא המאמר שבצירוף ל' הכתוב \"בשמים ממעל ועל הארץ מתחת\", הוא כדי להדגיש שהוא לנגד ז\"א (ומל'), כמבואר בהערת אאמו\"ר, ד\"כאן איתמר על שמים ממעל ועל ארץ מתחת, כי בז\"א ומל' ז\"א הוא למעלה ומל' הוא למטה, משא\"כ בהלא את השמים ואת הארץ אני מלא. . או\"א כחדא. . שווין בקומתן\"."]]],[1301870141,"ב. והנה בפשטות טעמו של אאמו\"ר לפרש שהם ד' ראיות<sup data-n=\"524\">12</sup>, מפורש בדבריו גופא, דכיון ש\"נשמת האדם נמשכה מד' אותיות דשם הוי'\", לכן הביא ד' ראיות \"לנגד הד' אותיות דשם הוי'\".\nאבל אין זה מספיק, שהרי מפורש באגה\"ת לעיל (פ\"ד<sup data-n=\"527\">14</sup>) שיש דרגא חמי­שית בשם הוי' — \"הקוץ שעל היו\"ד (ה)רומז לבחי' רצון העליון ב\"ה שלמע­לה מעלה ממדרגת בחי' חכמה עילאה\"<sup data-n=\"528\">15</sup> (וכן בנפש האדם ישנו \"קוצו של יו\"ד\", כמבואר בכ\"מ<sup data-n=\"529\">16</sup> שזהו ענין המסירת נפש שלמעלה מן החכמה וטעם ודעת), וא\"כ יש מקום לפרש שיש כאן ה' ראיות לנגד ד' אותיות שם הוי' וקוצו של יו\"ד<sup data-n=\"530\">17</sup>?\nוגם את\"ל שהלשונות בהראיות שה­ביא אדה\"ז מתאימות ומכוונות רק לד' אותיות שם הוי' (כפי שאאמו\"ר מפרש בהערתו ע\"ד הקבלה)<sup data-n=\"531\">18</sup> — עיקר השאלה עדיין ישנה: למה הביא אדה\"ז ראיות רק על ד' אותיות שם הוי', ולא הביא גם ראי' חמישית לנגד קוצו של יו\"ד (רצון העליון)?\nג. ויובן זה בהקדם שאלה כללית בדברי אדה\"ז כאן:\nא) למאי נפק\"מ באגה\"ת כאן הקדמה זו ש\"באמת אין שום דבר גשמי ורוחני חוצץ לפניו ית'\" (עם כמה ראיות) — הרי הי' מספיק לומר (בקיצור), \"ככה ממש אם יש דבר חוצץ ומפסיק בין גוף האדם לבחי' הבל העליון, כמ\"ש בישעי' (כי אם) עוונותיכם היו מבדילים ביניכם לבין אלקיכם\"<sup data-n=\"532\">19</sup>?\nב) מהו החידוש בכך ש\"אין שום דבר גשמי ורוחני חוצץ לפניו ית'\", עד ש­הוזקק להביא ע\"ז ד' (או ה') ראיות<sup data-n=\"533\">20</sup> — הרי זה מילתא דפשיטא שאינה צריכה לפנים!\nומה גם שבתניא חלק ראשון<sup data-n=\"534\">21</sup> כבר ביאר אדה\"ז בארוכה דזה ש\"אין סוף\" נקרא \"סובב כל עלמין\", \"אין הפי' סובב ומקיף מלמעלה בבחי' מקום ח\"ו כי לא שייך כלל בחי' מקום ברוחניות\", ובהמ­שך הענין שם<sup data-n=\"535\">22</sup> מביא זה ש\"הארץ הלזו",[["524","12","וראה לקמן הערה 18."],["527","14","צד, ב."],["528","15","וכהמשך דברי אדה\"ז כאן גופא בטעם שעונות מבדילים, \"לפי שהם נגד רצון העליון ב\"ה. . שהוא מקור השפעת שם הוי' ונרמז בקוצו של יו\"ד\"."],["529","16","לקו\"ת תצא (לח, ג. לט, ב­ג). ובכ\"מ.\nואע\"פ שלעיל בפ\"ד לא פי' ענינו של קוצו של יו\"ד בנפש האדם — ראה לעיל ע' 65 הערה 48 (ובשוה\"ג שם) שנרמז בלשון אדה\"ז ספ\"ד. והרי גם כאן המדובר ברמז בלבד. ולקמן פ\"ח משמע, ד­ענין התשובה שייך לקוצו של יו\"ד. וראה בארוכה לקמן ע' 144 ואילך."],["530","17","וכמשנ\"ת בפרטיות בהתועדות (דש\"פ נצ­בים תשכ\"ט), התאמת הלשונות בה' הראיות לה' דרגות דקוצש\"י וד' אותיות הוי'. ע\"ש."],["531","18","וגם מלשון אדה\"ז כאן גופא יש לדייק ש\"בשמים ממעל גו'\" הוא פרט בהראי' (מתקו\"ז) \"לית אתר פנוי מיני'\", דאל\"כ הול\"ל \"ובשמים מ­מעל גו'\" (כמו בהשאר שיש וא\"ו המוסיף)."],["532","19","והדיוק עוד יותר — כי באגה\"ת מהד\"ק (בהוצאת קה\"ת תשמ\"ב — ע' תקי) אכן ליתא הק­דמה זו, והיא הוספת אדה\"ז במהד\"ב. ולהעיר שרק אז נעשה חלק שלישי דס' התניא (ראה לקמן ב­פנים)."],["533","20","וגם לפי ביאור אאמו\"ר, שד' הראיות הן לנגד ד' אותיות שם הוי' — הרי הא גופא צריך ביאור, מהו ההכרח להביא ראי' לנגד כל א' מהד' אותיות דשם הוי'?"],["534","21","פמ\"ח (סז, סע\"ב)."],["535","22","שם סח, א."]]],[1301870142,"הגשמית. . מלא כל הארץ כבודו<sup data-n=\"515\">3</sup>, והיי­נו אור א\"ס ב\"ה כמ\"ש<sup data-n=\"514\">2</sup> הלא את השמים ואת הארץ אני מלא נאם ה'\";\nוכן בתניא ח\"ב<sup data-n=\"538\">23</sup> האריך לבאר \"ש­מהותו ועצמותו יתברך הנקרא בשם אין סוף ברוך הוא מלא את כל הארץ ממש בזמן ומקום, כי בשמים ממעל ובארץ ולד' סטרין הכל מלא מאור א\"ס ב\"ה בשוה ממש, כי כך הוא בארץ מתחת כמו בשמים ממעל ממש\", ובהמשך הענין<sup data-n=\"539\">24</sup> שולל דעת האומרים שה\"צמצום כפשו­טו\", כי אין לומר \"שהקב\"ה סילק עצמו ומהותו ח\"ו מעוה\"ז. . שא\"א כלל לומר ענין הצמצום כפשוטו שהוא ממקרי הגוף על הקב\"ה הנבדל מהם ריבוא רבבות הבדלות עד אין קץ\" (ומביא שם<sup data-n=\"540\">25</sup> מאמר התיקונים<sup data-n=\"516\">4</sup> \"לית אתר פנוי מיני' לא בע­ילאין ולא בתתאין\", וכן המאמר<sup data-n=\"518\">6</sup> \"איהו ממלא כל עלמין כו'\") —\nולאחרי כ\"ז, למה הוצרך אדה\"ז לכ­תוב באגה\"ת (תניא חלק שלישי), ובסגנון דחידוש<sup data-n=\"543\">26</sup>: \"אין שום דבר גשמי ורוחני חוצץ לפניו ית'\" — ולהביא ע\"ז ד' (או ה') ראיות!\nד. ולכן נראה לומר, דמ\"ש אדה\"ז באגה\"ת כאן ש\"אין שום דבר גשמי ורוחני חוצץ לפניו ית'\", יש חידוש בזה לגבי המבואר קודם שהקב\"ה \"נמצא\" ב­כל מקום, היינו, שיש קס\"ד לומר דהגם שהקב\"ה \"נמצא\" בכל מקום, מ\"מ אפשר שיהי' דבר \"חוצץ לפניו ית'\"<sup data-n=\"544\">27</sup>, ובא וקמ\"ל שאין הדבר כן, ומביא כמה ראיות מפסוקים ומאמרי רז\"ל.\nויובן זה בהקדם ביאור גדר ה\"חצי­צה\" בהלכה, שמזה יובן גם לענין \"חצי­צה\" בפנימיות הענינים (\"אין שום דבר גשמי ורוחני חוצץ לפניו ית'\"):\nבענין טבילה במקוה — יש ב' דינים<sup data-n=\"545\">28</sup>: א) צ\"ל \"טבילת כל הגוף במקוה. . שאם טבל כולו חוץ מראש אצבע הקטנה עדיין הוא בטומאתו\"<sup data-n=\"546\">29</sup> (מן התורה<sup data-n=\"547\">30</sup>). ב) \"לא יהי' דבר חוצץ בינם ובין המים\"<sup data-n=\"548\">31</sup>, ובזה, \"דבר תורה אם. . אינו מקפיד עליו [על דבר החוצץ]. . אינו חוצץ ואע\"פ שחופה את רובו\"<sup data-n=\"548\">31</sup>.\nוהם גדרים שונים: הדין ד\"טבל כולו\" הוא במעשה הטבילה של האדם, שהאדם צריך לטבול את \"כל גופו. . בבת א­חת\"<sup data-n=\"550\">32</sup>, וכאשר (אפילו) \"ראש אצבע הקט­נה\"<sup data-n=\"551\">33</sup> חוץ למים, אין כאן מעשה טבילה; משא\"כ החסרון דחציצה אינו במעשה ה­טבילה (כי מעשה הטבילה הוא בשלי­מותו), אלא הו\"ע צדדי, שיש דבר שחוץ ממנו החוצץ בינו לבין המים, וכיון ש­",[["515","3","ישעי' ו, ג."],["514","2","ירמי' כג, כד."],["538","23","פ\"ז (פב, ריש ע\"ב)."],["539","24","שם פג, סע\"א ואילך."],["540","25","שם פג, ב."],["516","4","תקו\"ז תנ\"ז. שם ת\"ע (קכב, ב). וראה לקמן הערה 13."],["518","6","רע\"מ פינחס רכה, א."],["543","26","ובפרט, שגם להסוברים דצמצום כפשוטו, אינו מפני שס\"ל שיש בכח איזה דבר למנוע ח\"ו אותו, אלא רק מפני שרצה לצמצם עצמו, והוא רק מצד כחו ית' הכל יכול, כמשנ\"ת במ\"א באורך."],["544","27","ולהעיר מהדין (שו\"ע אדה\"ז או\"ח סנ\"ה סכ\"ב, ממג\"א שם סקט\"ו), דאע\"פ דכל השומע קולו של האומר קדיש או קדושה אפילו כמה בתים מפסיקים ביניהם יכול לענות עמהם, \"מפני שאפי­לו מחיצה של ברזל אינה מפסקת בין ישראל לאביהם שבשמים. . מ\"מ צריך שלא יהי' מפסיק טינוף או ע\"ז\". וראה לקמן הערה 41."],["545","28","בהבא לקמן ראה שו\"ת הצ\"צ יו\"ד סקנ\"ח אות א. שיורי טהרה ליו\"ד ר\"ס קצח."],["546","29","רמב\"ם הל' מקואות פ\"א ה\"ב."],["547","30","ראה צ\"צ ושיורי טהרה שם."],["548","31","רמב\"ם שם הי\"ב."],["548","31","רמב\"ם שם הי\"ב."],["550","32","רמב\"ם שם ה\"ז."],["551","33","או שערה אחת (רמב\"ם שם)."]]],[1301870143,"העדר ביאתו במים הוא (לא מצד מעשה הטבילה שלו, אלא) מצד הדבר החוצץ, לכן ה\"ז תלוי בחשיבות הדבר, דאם רק חופה את מיעוט הגוף או שאינו מקפיד עליו, (דבר תורה) עלתה לו טבילה, כיון שאין בכחו של דבר זה (שאין לו חשיבות) לחצוץ בפני מי המקוה.\nועפ\"ז יש לומר, שהחילוק בין ה­מבואר לעיל בח\"א וח\"ב (שהקב\"ה נמצא בכל מקום), להמבואר באגה\"ת כאן ש­\"אין שום דבר. . חוצץ לפניו ית'\" — הוא ע\"ד החילוק בין הגדרים הנ\"ל בדין טבי­לה, כדלקמן.\nה. ביאור הענין:\nהחילוק העיקרי בין המבואר לעיל (בח\"א וח\"ב) להמבואר באגה\"ת כאן הוא:\nזה שהקב\"ה נמצא בכל מקום (המבו­אר לעיל בח\"א וח\"ב) הוא ענין השווה בכל הנבראים כולם, דהוא ית' נקרא \"אין סוף ברוך הוא\" דכשמו כן הוא, שאין שום הגבלה אצלו ית', ובמילא אין מקום שחוץ ממנו;\nאבל באגה\"ת כאן<sup data-n=\"552\">34</sup> בא אדה\"ז לבאר הענין ד\"חלק הוי' עמו\"<sup data-n=\"553\">35</sup>, שבנ\"י הם \"ח­לק משם הוי' ב\"ה\"<sup data-n=\"554\">36</sup>, כיון ש\"ויפח באפיו נשמת חיים ומאן דנפח מתוכו נפח וכו'\"<sup data-n=\"554\">36</sup>, שזהו ענין ומעלה במציאותם של ישראל, שבהם גופא ישנו \"שם הוי'\" (וכמו שנת' לעיל בפ\"ד<sup data-n=\"556\">37</sup> שיש ד' אותיות שם הוי' בנשמת האדם).\nוענין זה הוא רק בישראל, ולא בשאר נבראים, דאף שהקב\"ה נמצא בכל מ­קום<sup data-n=\"557\">38</sup>, מ\"מ, אי אפשר לומר על כל נברא שהוא \"חלק משם הוי' ב\"ה\" ח\"ו, כי זה שהקב\"ה נמצא בכל מקום הוא מצד גדלותו ית' (שהוא ית' אין לו סוף), אבל אינו שייך למציאות הנברא (שבו הוא נמצא)<sup data-n=\"558\">39</sup>; משא\"כ בישראל נאמר \"כי חלק הוי' עמו\", דזה שהם \"חלק משם הוי' ב\"ה\" מתייחס למציאותם.\nולכן הוזקק אדה\"ז להוסיף כאן הקדמה זו \"אך באמת אין שום דבר גשמי ורוחני חוצץ לפניו ית'\", כי יש מקום לומר, שכיון שהנשמה ירדה (כמבואר בתניא<sup data-n=\"559\">40</sup>) \"ממדרגה למדרגה על ידי הש­תלשלות העולמות\", ועד שיש לה שיי­כות גם לגשמיות (דאל\"כ לא היתה יכו­לה להתלבש בגוף גשמי), הרי נמצא, שישנם \"דברים\" (\"בין גוף האדם לבחי' הבל העליון\") שהנשמה מתלבשת בהם בירידתה ממדריגה למדריגה מעולם ל­עולם, עד לעולם הזה הגשמי, שהם אינם \"חלק משם הוי' ב\"ה\" — ואיך אפשר שהוי' עצמו \"יגיע\" (ע\"י דבר זה שאינו \"חלק משם הוי' ב\"ה\") אל מציאות הנש­מה כפי שהיא מלובשת בגוף?\nובזה קמ\"ל אדה\"ז, ש\"אין שום דבר גשמי ורוחני חוצץ לפניו ית'\", דלגבי שם הוי' \"אין שום דבר גשמי ורוחני [אף שהדבר אינו \"חלק משם הוי' ב\"ה\"] חוצץ לפניו ית'\", ולכן אין שום דבר<sup data-n=\"560\">41</sup> יכול",[["552","34","פ\"ד ואילך."],["553","35","ל' הכתוב — האזינו לב, ט."],["554","36","פ\"ד (צג, סע\"ב)."],["554","36","פ\"ד (צג, סע\"ב)."],["556","37","צה, א."],["557","38","ושורש התהוות כל הנבראים הוא משם הוי', שפירושו מל' מהווה (תניא ח\"ב פ\"ד — עט, רע\"א)."],["558","39","וכן זה ששורש התהוות כל הנבראים הוא משם הוי' (כבהערה הקודמת) — ה\"ז ע\"י התלבשות בשם אלקים. וראה אגה\"ת לעיל פ\"ד (צד, א)."],["559","40","ח\"א פ\"ב."],["560","41","ורק עונות \"מבדילים ביניכם לבין אלקי­כם. . לפי שהם נגד רצון העליון ב\"ה. . מקור השפעת שם הוי'\" (אגה\"ת כאן). וע\"פ המבואר בפנים מובן, שהכוונה בזה, לא רק שאין הקב\"ה שורה בדבר שנגד רצונו ית' [ולהעיר שבאגה\"ת מהד\"ק שם מביא ע\"ז הכתוב (חבקוק א, יג) \"טהור עינים מראות ברע\"], אלא לפי שהעון מבדיל וחוצץ שלא תומשך השפעת שם הוי' ל(כללות) האדם. וכלשון אאמו\"ר כאן (בסיום ההערה) \"שעונות. . אין מניחים שיומשך מד' אותיות דשם הוי' לנשמת האדם\".\n[וע\"ד הדין הנ\"ל הערה 27 לענין עניית אמן כשיש טינוף או ע\"ז מפסיק, שאין שייך לומר כאן שזהו חסרון באדם המתפלל, שעושה משהו נגד רצונו ית' (שהרי האדם נמצא במקום שמותר לו להתפלל), אלא שהדבר המטונף נמצא בין מקום המנין לביתו, והדבר חוצץ בינו לבין המנין המת­פלל כו']."]]],[1301870144,"לחצוץ בפני (שורש) נשמת האדם שהיא \"חלק משם הוי' ב\"ה\", והעילוי ד\"ויפח\" נמשך להנשמה גם כפי שהיא מלובשת בגוף<sup data-n=\"561\">42</sup>.\nכלומר: גם כפי שהנשמה היא בציור של \"נברא\", וד' \"אותיות\" הנשמה (שהם כוחותי' — שכלה מדותי' ולבושי' (כמ\"ש אדה\"ז לעיל בפ\"ד)) הם בהתלבשות בגוף גשמי, הרי מהותם היא — ד' אותיות דשם הוי'<sup data-n=\"562\">43</sup>.\nו. ע\"פ הנ\"ל מובן גם הטעם שדוקא כאן, בענין \"אין שום דבר. . חוצץ לפניו ית'\", מביא אדה\"ז ד' ראיות — משא\"כ בחלק ראשון וחלק שני, שלא האריך בהבאת ראיות:\nלעיל בחלק ראשון ושני שם, קאי ב­ענין גדלותו של הקב\"ה, שאין לו סוף, שלכן הוא נמצא בכל מקום. וכמו אור המאיר, דככל שהאור גדול יותר, מת­פשט למרחוק יותר, כך עד\"מ הקב\"ה \"הנקרא בשם אין סוף ברוך הוא\", אין סוף להתפשטותו ונמצא בכל מקום [ע\"ד דין הא' הנ\"ל, שמעשה הטבילה מצד האדם צ\"ל בשלימות, כל גופו בבת אחת] — וענין זה אינו זקוק לכמה ראיות כו';\nמשא\"כ באגה\"ת כאן מחדש עוד ענין, דגם כשאור הוי' נמשך דרך איזה דבר (שדבר זה אינו \"חלק משם הוי' ב\"ה\"), \"אין שום דבר גשמי ורוחני חוצץ לפניו ית'\", שגם אז \"מגיע\" ומאיר שם האור דהוי' עצמו.\nולכן הביא ע\"ז ד' ראיות, שהן (כפי­רוש אאמו\"ר) \"לנגד הד' אותיות דשם הוי'\" — כי החידוש בהכלל ד\"אין שום דבר. . חוצץ לפניו ית'\" אינו בשייכות ל\"עצמותו ומהותו ית' הנקרא בשם אין סוף ברוך הוא\", סובב כל עלמין (\"שאינו נתפס כלל תוך העולמות\"<sup data-n=\"563\">44</sup>), ונמצא בכל מקום בשווה — אלא בנוגע לשם הוי', דאע\"פ שיש בו ד' אותיות, שכל אות היא צורה אחרת (המורה על \"ציור\" ההמ­שכה<sup data-n=\"564\">45</sup>, וכמבואר באגה\"ת לעיל פ\"ד<sup data-n=\"565\">46</sup>,",[["561","42","ראה גם לעיל ע' 69."],["562","43","ולדוגמא — השגת אלקות דהנשמה, דאף שהיא השגה של נברא, ועד שנעשה בה הגבלה של גשם מצד ההתלבשות במוח הגשמי — מ\"מ, מהות השגת אלקות דהנשמה היא \"ה\"א ראשונה\" (כב­אגה\"ת ספ\"ד). וראה לעיל ע' 62 (ס\"ו)."],["563","44","ל' התניא ח\"ב פ\"ז שם (פג, ב) לענין שהצמצום אינו כפשוטו, וממשיך \"וזהו ג\"כ ענין סוכ\"ע\", שמזה מובן, שאין זה שייך להעולמות עצמם, כ\"א זהו רק מצד הבל\"ג שלו, שאין הצמצום מעלים לגבי'. משא\"כ באגה\"ת ש\"אין שום דבר. . חוצץ לפניו ית'\", היינו בהאור פנימי כו'. ואכ\"מ."],["564","45","ראה תניא ח\"ב פי\"ב בהגה\"ה.\nוכמודגש גם בחילוקי הלשונות בהד' ראיות, בהתאם להאות המקבילה של השם, כמבואר בה­ערת אאמו\"ר (אם נאמר בה רק \"שמים\", או \"שמים וארץ\", ועוד)."],["565","46","צד, ב. וע\"ש השייכות לצורת האותיות."]]],[1301870145,"איך היו\"ד ספירות נכללות ונרמזות בד' אותיות דשם הוי'), מ\"מ, אין שום דבר חוצץ לפניו ית', ובמילא אין הגבלה ב­התפשטותו ית' גם כפי שנמשכת על ידי ד' אותיות שם הוי'.\n[והטעם ש\"אין שום דבר.. חוצץ לפניו ית'\" הוא ע\"ד הדין הנ\"ל בחציצה בטבילה, דכיון שאין להדבר החוצץ חשיבות (אם מצד מיעוטו או מפני שאינו מקפיד עליו), אין בכוחו לחצוץ בפני מי המקוה.\nוכן הוא ברוחניות, שהטעם שאין שום דבר חוצץ בפני שם הוי' הוא לפי שלגבי שם הוי', כל הנבראים (אף שאינם \"חלק משם הוי' ב\"ה\") בטלים אצלו ית', וכמ­שנ\"ת בארוכה בתניא חלק שני<sup data-n=\"566\">47</sup>, דמצד שם הוי', אף \"דשם הוי' פירושו שמהוה את הכל\"<sup data-n=\"567\">48</sup>, הרי ההתהוות דשם הוי' היא באופן שהנבראים הם בטלים במקורם (כמו אור השמש כשהוא עדיין במקורו בגוף השמש), שכל מציאותם היא רק מקורם — וכיון שאין הם \"מציאות\", אין בכחם \"לחצוץ\" ולמנוע ההתפשטות דשם הוי', \"אין שום דבר. . חוצץ לפניו ית'\"].\nועפ\"ז מבואר גם הטעם שהביא רק ד' ראיות, ולא ה' (גם לנגד קוצו של יו\"ד) — כי \"קוצו של יו\"ד\" הוא גילוי אור אלקי כפי שהוא למעלה מ\"ציור\" (אף לא \"נקו­דה לבד\", כהיו\"ד), ובעבודה הו\"ע המסי­רת נפש שלמעלה מטעם ודעת, וכיון שמדריגה זו אינה נתפסת ב\"ציור\"<sup data-n=\"568\">49</sup>, ה\"ז ע\"ד \"סובב כל עלמין\", שלגבי' אין צרי­כים לשלול ש\"אין שום דבר. . חוצץ לפניו ית'\" (כנ\"ל).\n<span data-k=\"q\">(משיחות ש\"פ נצבים תשכ\"ט, ש\"פ וישב תשל\"א) </span>",[["566","47","ראה שם פ\"ג­ד."],["567","48","שם פ\"ד (עט, רע\"א)."],["568","49","ויש לומר, שבפרטיות יותר, הראי' מ\"לית אתר פנוי מיני' בשמים ממעל ועל הארץ מתחת גו'\", היא (לא רק לנגד ז\"א, אלא) גם לנגד דעת, \"קיום המדות וחיותן\" (תניא ספ\"ג).\nועפ\"ז נכלל בזה גם הענין דקוצו של יו\"ד (שבנפש) — כידוע דדעת עולה עד הכתר — אלא שזהו כפי שפנימיות הנפש נמשכת ב\"ציור\" (פני­מיות המדות).\nוזהו גם הטעם שנרמז בלשון \"לית אתר פנוי מיני'\", המורה על ביטול גדול ביותר, שמלכת­חילה אין כאן \"אתר\" בלעדו ית' [דבשאר הראיות נאמר רק \"מלא\", \"ממלא\" — אבל לא מודגש שאין מציאות לשמים וארץ בלעדו], דכיון שכאן המדו­בר בהמשכת הכתר (שלמעלה מ\"ציור\") בהשתל­שלות, צ\"ל הביטול (שבגללו אין ה\"ציור\" דהשתל­שלות \"חוצץ לפניו\") בעומק יותר, \"לית אתר פנוי מיני'\"."]]],[1301870146,"<h3>אגרת התשובה ה</h3>\nא. באגרת התשובה (פרקים ד­ו) מא­ריך אדמו\"ר הזקן \"בביאור<sup data-n=\"569\">1</sup> מלת תשובה ע\"ד הסוד — תשוב ה', ה\"א תתאה [דשם הוי'] תשובה תתאה, ה\"א עילאה תשובה עילאה\", ד\"ה\"א תתאה\" היא מקור הנפש האלקית<sup data-n=\"570\">2</sup>, וע\"י עוונות \"נכרת<sup data-n=\"571\">3</sup> ונפסק ח­בל ההמשכה. . מה\"א תתאה\" לנשמת האדם, וכן גורם ל\"גלות השכינה\", כי ע\"י מעשיו הרעים כו' הוא ממשיך ומו­ריד השפעת ה\"א תתאה [שרש נשמת ה­אדם ומקורה] עד תוך היכלות הסטרא אחרא<sup data-n=\"572\">4</sup> — \"וכשהאדם<sup data-n=\"573\">5</sup> עושה תשובה נכו­נה אזי מסלק מהם ההשפעה שהמשיך במעשיו ומחשבותיו, כי בתשובתו מחזיר השפעת השכינה למקומה, וזהו תשוב ה\"א תתאה מבחי' גלות כו'\".\nואח\"כ ממשיך בריש פ\"ז: \"ואולם דרך האמת והישר לבחי' תשובה תתאה ה\"א תתאה הנ\"ל הם ב' דברים דרך כלל, הא' הוא לעורר רחמים העליונים. . על נש­מתו. . שנפלה. . לבירא עמיקתא הן היכלות הטומאה והסט\"א, ועל מקורה. . לעורר רחמים על השפעת שם הוי' ב\"ה שנשתלשלה וירדה תוך היכלות הסט\"א. . והב' לבטש ולהכניע הקליפה וסט\"א. . ע\"י לב נשבר ונדכה. . זבחי אלקים רוח נשברה כו'\".\nובהערות אאמו\"ר על אגה\"ת<sup data-n=\"574\">6</sup> מבאר ב' הלשונות (בריש פ\"ז) \"דרך האמת וה­ישר לבחי' תשובה תתאה ה\"א תתאה\", וז\"ל:\n\"אמת הוא תפארת, מדתו של יעקב, מדת הרחמים, והישר הוא יסוד. . והם הם הראשים דמלכות. . מתפארת נמ­שכו חסדים לכתר מלכות, ומיסוד נמשכו גבורות לדעת דמלכות. . זהו שאמת והישר. . הם דרך לבחי' תשובה תתאה ה\"א תתאה בחי' מלכות, שהם משיבים ומחזירים אותה למקומה\".\nואח\"כ מבאר \"והיינו הב' דברים ש­אמר לקמן לעורר רחמים העליונים כו', רחמים הוא תפארת בחי' אמת (ועיין ל­קמן באגה\"ק פ\"ו, ע\"ש). . ולבטש ולהכ­ניע כו' שזהו בחי' גבורות זבחי אלקים כו' הוא בחי' ישר, יסוד, בחי' גבורות\".\nוהנה כבר נת' כמ\"פ, שבכמה מקומות נראה שבהערות אלו כוונת אאמו\"ר היא לא רק לבאר את דיוקי הלשונות בספר התניא, אלא גם לרמז ביאור בתוכן ה­כללי של הפרק (הענין).\nוכן יש לומר בעניננו, שביאור אאמו\"ר הנ\"ל, שב' הדברים ד\"אמת\" ו\"ישר\" [ה­מכוונים ל\"ב' דברים. . לעורר רחמים. . ולבטש ולהכניע\"] הם כנגד ב' הספירות דתפארת ויסוד (\"הראשים דמלכות\"), ו\"הם משיבים ומחזירים\" ה\"א תתאה (מלכות) למקומה — מבארים כללות תוכן הפרק ע\"ד ב' הדברים ד\"לעורר רחמים. . ולבטש ולהכניע כו'\".\nב. דהנה לכאורה נראה, דמ\"ש ב­רפ\"ז \"דרך האמת והישר לבחי' תשובה תתאה ה\"א תתאה הנ\"ל הם ב' דברים",[["569","1","פ\"ד (צג, ב)."],["570","2","רפ\"ה."],["571","3","פ\"ה (צה, ב)."],["572","4","פ\"ו (צו, א­ב)."],["573","5","שם בסוף הפרק."],["574","6","לקוטי לוי יצחק לתניא — ע' לא."]]],[1301870147,"כו'\", היינו, שהטעם שהאדם צריך \"לעו­רר רחמים העליונים. . על נשמתו\", וכן \"לבטש ולהכניע הקליפה. . ע\"י לב נש­בר ונדכה כו'\", הוא כדי לתקן הענין ד\"גלות השכינה\" שנגרם ע\"י החטאים, וכפי שממשיך בפרק ח<sup data-n=\"575\">7</sup>, ש\"אחרי העמקת הדעת בכל הנ\"ל. . תקבע בלבו באמת גודל הרחמנות על בחי' אלקות שבנפשו ושלמעלה כנ\"ל, ובזה יעורר רחמים ה­עליונים מי\"ג מדה\"ר. . (ה)מנקים כל הפגמים. . ושוב אין יניקה להחיצונים והסט\"א מהשפעת ה\"א תתאה. . ובזה תשוב ה\"א תתאה למקומה\".\nאבל דוחק לפרש כן, כי לפ\"ז נמצא, שכל האריכות בפרק זה אודות שני דב­רים אלה (לעורר רחמים ולבטש ולהכניע כו') אינה ענין לעבודת התשובה עצמה (\"לשוב אל ה' בכל לבו\"<sup data-n=\"576\">8</sup>), אלא הוא ענין בפ\"ע — לתקן את \"גלות השכינה\" הנג­רמת ע\"י עוונותיו<sup data-n=\"577\">9</sup>.\nועוד זאת: בסוף פ\"ו כבר כתב אדה\"ז (כנ\"ל) \"וכשהאדם עושה תשובה נכונה אזי מסלק מהם ההשפעה כו' כי בתשו­בתו מחזיר השפעת השכינה למקומה\", הרי מפורש שע\"י התשובה עצמה \"מח­זיר השפעת השכינה למקומה\"<sup data-n=\"578\">10</sup>, ואיך מתאים זה עם המשך הענין, שאין \"תשו­בה נכונה\" מספיקה להחזיר השפעת ה­שכינה למקומה, אלא צריכים עוד דברים נוספים — \"לעורר רחמים כו' לבטש ולהכניע הקליפה כו'\"?\nוגם: מדוע בפ\"ח, כשמבאר איך מפ­סיקים יניקת החיצונים ופועלים ש\"תשוב ה\"א תתאה למקומה\", לא הזכיר כלל הדבר הב' שבפ\"ז (ע\"ד ביטוש והכנעה), אלא רק הדבר הא' (התעוררות רחמים על בחי' אלקות שבנפשו ושלמעלה)?\nולכן מסתבר לומר, שכוונת אדה\"ז במ\"ש \"ואולם דרך האמת והישר לבחי' תשובה תתאה ה\"א תתאה הנ\"ל\" היא (בעיקר) לעבודת התשובה דהאדם<sup data-n=\"579\">*10</sup>, שב' הדברים המבוארים בהפרק (לעורר רח­מים כו' והביטוש וההכנעה) הם הפועלים שהתשובה תתאה דהאדם תהי' באמת וב­אופן ישר (ואזי היא \"תשובה נכונה\" שעל ידה \"מחזיר השפעת השכינה למקומה\").\n[אלא שבפ\"ח מוסיף עוד ענין, שע\"י שנקבע \"בלבו באמת גודל הרחמנות על בחי' אלקות שבנפשו כו'\", נעשה ענין נוסף, שרחמי האדם מעוררים \"רחמים העליונים מי\"ג מדות הרחמים. . (ה)מנ­קים כל הפגמים\"].\nוצריך ביאור: מהו הקשר בין שני דברים אלה לתוכן ענין התשובה, \"לשוב אל ה' בכל לבו ובכל נפשו\"<sup data-n=\"576\">8</sup>, \"באמת ובלב שלם\"<sup data-n=\"581\">11</sup> — שלכן רק הם ה\"דרך האמת והישר לבחי' תשובה תתאה\"?\nוענין זה יובן ע\"פ הערת אאמו\"ר, שב' דברים אלה [שכנגד \"תפארת\" ו\"יסוד\", \"הראשים דמלכות\"] \"הם משיבים ומחזי­רים אותה (ה\"א תתאה) למקומה\", כדל­קמן.",[["575","7","צח, א."],["576","8","אגה\"ת פ\"א (צא, א)."],["577","9","ואינו דומה להאריכות לעיל פ\"ב­ג ע\"ד תעניות וצדקה, שהרי עכ\"פ הם פועלים \"גמר הכ­פרה\", משא\"כ ענין התעוררות רחמים על נפשו, שהוא רק ענין צדדי וגרם (שמעוררים י\"ג מדות הרחמים), ולא שהוא הדבר הפועל תיקון הפגמים והחזרת ה\"א תתאה למקומה."],["578","10","ראה גם לקו\"ת בלק עג, ג."],["579","*10","ראה גם לקמן פ\"י (צט, ב). ד\"ה דרשו תרצ\"א (סה\"מ קונטרסים ח\"א קלה, ב)."],["576","8","אגה\"ת פ\"א (צא, א)."],["581","11","אגה\"ת רפ\"ד. וראה לקמן הערה 23."]]],[1301870148,"ג. ביאור הדבר:\nבגדר מצות תשובה כתב אדה\"ז לעיל (פ\"א<sup data-n=\"582\">12</sup>) \"שיגמור בלבו. . לבל ישוב עוד לכסלה למרוד במלכותו ית' ולא יעבור עוד מצות המלך ח\"ו הן במ\"ע הן במל\"ת\", שמזה מובן, שעיקר ענין התשובה הוא קבלת עול מלכות שמים וקבלת עול מצות<sup data-n=\"583\">13</sup>.\nדהנה בכל מעשה עבירה, יש בו פריקת עול מלכות שמים, דאם הי' עליו עולו ית', הי' מושל ברוח תאוותו כו' מצד עול מלכות שמים, כמו עבד, דאף שבהפקירא ניחא לי'<sup data-n=\"584\">14</sup>, ה\"ה כופה א\"ע מחמת עול אדונו שעליו. ולכן, ראשית ענין התשובה, \"לשוב אל ה'\", היא לקבל עליו מחדש את עול מלכותו ית'.\nוזוהי השייכות דתשובה תתאה לה\"א תתאה שבנפש — כי ה\"א תתאה היא מדת מלכותו ית'<sup data-n=\"585\">15</sup>, ובעבודת האדם היא קבלת עול מלכותו ית'.\nוזה מתאים עם דברי אדה\"ז לעיל<sup data-n=\"586\">16</sup>, דה\"א תתאה בנפש האדם קאי על עסק התורה והמצות במעשה — כי קבלת עול מלכות שמים שייכת למעשה, כמו עבד שמקבל עליו עול אדונו, שאין קבלת ה­עול משנה את פנימיותו (שכלו ומדותיו) — שהרי גם אחרי קבלת העול \"בהפקירא ניחא לי'\" — אלא שבנוגע למעשה בפועל מתנהג כפי רצון אדונו; וכן הוא בעבודת השם, שקבלת עול מלכות שמים היא (בעיקר) בנוגע למעשה האדם, כל' אדה\"ז הנ\"ל \"שלא יעבור. . מצות המלך ח\"ו הן במ\"ע הן במל\"ת\".\nד. והנה, כשם שמצינו בנוגע לה\"א תתאה (ספירת המלכות) למעלה, ש\"בנ­ינה\" הוא ע\"י הספירות שלמעלה ממנה (וכמבואר בהערת אאמו\"ר, ש\"תפארת\" ו\"יסוד\" הם \"הראשים דמלכות\") — עד\"ז צריך לומר גם לענין ה\"א תתאה שבנפש, קבלת עול מלכותו ית', דעם היות ש­קבלת עול (בפועל) שייכת ל\"מעשה\" וחיצוניות האדם, מ\"מ, \"בנין\" מדת הקב­לת עול שבאדם הוא ע\"י הפנימיות שלו (שלמעלה ממעשה).\nויש לומר הביאור בזה:\nענין קבלת עול מלכותו ית' שאצל ישראל, אינו דבר חיצוני לבד (שכופה א\"ע להתנהג כפי רצון המלך ושלא למ­רוד במלכותו ית'), אלא הוא בפנימיותו ועד שמושרש בפנימיות נפשו<sup data-n=\"587\">17</sup>, דלהיות ש\"חלק הוי' עמו. . חלק משם הוי' ב\"ה\"<sup data-n=\"588\">18</sup>, וכל א' מישראל מקושר אליו ית' בפנימיות נפשו, הרי מלכותו ית' נרגשת בנפשו והוא מקבל עליו עולו ית'.\nוזהו ג\"כ מ\"ש אדה\"ז כאן \"ואולם דרך האמת והישר לבחי' תשובה תתאה כו' הם שני דברים כו'\":\nב' הדברים ד\"לעורר רחמים כו' לב­טש ולהכניע כו'\", הם ה\"פנימיות\" דקבלת עול והיא \"נבנית\" על ידם [ע\"ד ש\"תפ­ארת\" ו\"יסוד\" הם \"הראשים דמלכות\" ובונים אותה], כדלקמן סעיף ה; ולכן נדרשים לבחי' תשובה תתאה שני דברים אלה, כי לאחרי שאדם פרק מעליו עולו ית', הרי מובן, שכדי לתקן זה ו\"לבנות\"",[["582","12","צא, רע\"א."],["583","13","ראה המשך תרס\"ו ע' ב. לקמן ע' 123 הערה 14. ועוד."],["584","14","גיטין יג, א."],["585","15","כבאגה\"ת לעיל (פ\"ד — צד, ב)."],["586","16","שם (צה, א)."],["587","17","ראה לקו\"ש ח\"ח ע' 128 ואילך. ועוד."],["588","18","אגה\"ת רפ\"ד (צג, סע\"ב)."]]],[1301870149,"מחדש את מדת הקבלת עול, צריכים לתקן הפגם מעיקרו, שהקבלת עול שלו תהי' מצד פנימיות נפשו<sup data-n=\"589\">19</sup>.\nובזה מובן דיוק לשון אדה\"ז \"(דרך) האמת והישר\":\nאע\"פ שקיום \"מצות התשובה\" הוא ע\"י עצם קבלת עול מלכותו ית' (ואין נפק\"מ אופן הקבלת עול או סיבתו) — כי \"מצות התשובה. . היא עזיבת החטא בלבד\"<sup data-n=\"590\">20</sup> — מ\"מ, כדי שתהי' \"באמת\" ה\"ז רק אם היא באופן שהקבלת עול קשורה ו\"דבוקה\" עם פנימיות נפשו. דנוסף לזה שרק אז יש לה קיום (\"שפת<sup data-n=\"591\">21</sup> אמת תכון לעד\") — כי באם הקבלת עול שלו היא רק באופן חיצוני הרי עלול ביותר שלא יהי' לה קיום, כיון שמצד נפשו \"בהפ­קירא ניחא לי'\" — הנה עוד זאת, שעצם הגדר ד\"אמת\" מורה שנעשה מצד הפני­מיות שלו.\nואז התשובה היא באופן של \"דרך. . הישר\": ענינו של \"ישר\" הוא — שהתשו­בה אינה בגלל סיבה מבחוץ [להעיר מתשובת ר' אלעזר בן דורדייא<sup data-n=\"592\">22</sup>], אלא מצד האדם עצמו. ובנוגע לעניננו: סתם קבלת עול (חיצונית) הרי סיבתה אימת האדון (שחוץ להעבד); משא\"כ כשהקב­לת עול היא תוצאה מהתקשרות הפני­מית של הנפש בו ית', ה\"ז \"דרך. . הישר\", שהוא ענין בהאדם עצמו<sup data-n=\"593\">23</sup>.\nה. ע\"פ הנ\"ל יש לבאר הטעם שדוקא ב' דברים אלה — \"לעורר רחמים כו' לבטש ולהכניע כו'\" — הם ה\"דרך האמת והישר\" להעבודה דתשובה תתאה:\nענין קבלת עול מלכות קשור, בכל­לות, עם ב' ענינים: א) הרגשת מלכותו ית', ב) הכנעת מציאות העבד. וע\"ד עבד שמקבל עליו עול אדונו, שראשית כל עליו לדעת ולהרגיש שזהו אדונו והוא קנוי אליו; אבל זה בלבד אינו מספיק, דאם מדת ההפקירות שלו היא חזקה, הרי הידיעה שזהו אדונו לא תוכל להג­בילו, וקבלת עול האדון דורשת הכנעת ישות ומציאות העבד כלפי האדון.\nוהם שני הענינים ד\"חסדים\" ו\"גבו­רות\" (ה\"בונים\" את המלכות): \"חסד\" ענינו גילוי, והוא התגלות המלך<sup data-n=\"594\">24</sup>; ו\"גבו­רה\" היינו הכנעת האדם, שעי\"ז עול המלך מתקבל בנפשו וחודר ללבו<sup data-n=\"594\">24</sup>.\nוכך הוא בענין התשובה, שכדי שה­אדם יוכל לתקן מדת ה\"קבלת עול מל­כות\" שלו — הרי זה ע\"י \"ב' דברים דרך כלל, הא' הוא לעורר רחמים כו' על נש­מתו כו' והב' לבטש ולהכניע הקליפה כו' ע\"י לב נשבר ונדכה\":\nזה שנקבע \"בלבו באמת גודל הרחמ­",[["589","19","ראה גם לקמן ע' 133 (ס\"ט). וראה שם ואילך בארוכה, שעפ\"ז מובן מ\"ש לעיל רפ\"ד, שגם בשביל ביאור \"התחלת מצות התשובה ועיקרה לשוב עד ה' באמת ובלב שלם, ההכרח לבאר היטב בהרחבת הביאור. . מלת תשובה ע\"ד הסוד תשוב ה'\". ע\"ש בארוכה."],["590","20","אגה\"ת פ\"א (צא, רע\"א)."],["591","21","ל' הכתוב — משלי יב, יט. וראה לעיל ח\"א ספי\"ג (יט, א)."],["592","22","ע\"ז יז, א. וראה לעיל ח\"א ספמ\"ג שזהו \"הוראת שעה\" ואין זה \"סדר העבודה הקבועה ותלוי' בבחירת האדם\"."],["593","23","ועפ\"ז י\"ל שב' הלשונות \"(דרך) האמת והישר\" הם לנגד ב' הלשונות שהתחיל בו לעיל (רפ\"ד) בביאור ענין התשובה ע\"ד הסוד (תשוב ה') — \"(לשוב עד ה') באמת ובלב שלם\". וראה לקמן בסוף הביאור."],["594","24","מתאים לזה ש\"מתפארת נמשכו חסדים לכתר מלכות\", שזהו ענין התגלות המלך; והגבו­רות נמשכות לדעת דמלכות, ענין הפנימיות."],["594","24","מתאים לזה ש\"מתפארת נמשכו חסדים לכתר מלכות\", שזהו ענין התגלות המלך; והגבו­רות נמשכות לדעת דמלכות, ענין הפנימיות."]]]]});
